# ║                          CAMERA SYSTEM                                        ║
# ╚═══════════════════════════════════════════════════════════════════════════════╝

class Camera:
    """
    Advanced camera system with shake, zoom, pan, and parallax effects.
    """

    def __init__(self, width: float, height: float):
        self.width = width
        self.height = height
        self.x = 0  # Camera position
        self.y = 0
        self.target_x = 0
        self.target_y = 0
        self.zoom = 1.0
        self.target_zoom = 1.0
        self.rotation = 0
        self.target_rotation = 0

        # Shake parameters
        self.shake_intensity = 0
        self.shake_decay = 0.9
        self.shake_offset_x = 0
        self.shake_offset_y = 0

        # Smooth follow
        self.follow_speed = 0.1
        self.zoom_speed = 0.05

        # Cinematic bars
        self.letterbox = 0  # 0 = none, 1 = full cinematic bars
        self.target_letterbox = 0

    def shake(self, intensity: float, decay: float = 0.9):
        """Apply screen shake effect"""
        self.shake_intensity = intensity
        self.shake_decay = decay

    def set_position(self, x: float, y: float, immediate: bool = False):
        """Set camera target position"""
        self.target_x = x
        self.target_y = y
        if immediate:
            self.x = x
            self.y = y

    def set_zoom(self, zoom: float, immediate: bool = False):
        """Set camera zoom level"""
        self.target_zoom = clamp(zoom, 0.5, 3.0)
        if immediate:
            self.zoom = self.target_zoom

    def set_letterbox(self, amount: float, immediate: bool = False):
        """Set cinematic letterbox bars"""
        self.target_letterbox = clamp(amount, 0, 1)
        if immediate:
            self.letterbox = self.target_letterbox

    def follow(self, target_x: float, target_y: float, speed: float = None):
        """Smoothly follow a target"""
        if speed:
            self.follow_speed = speed
        self.target_x = target_x - self.width / 2
        self.target_y = target_y - self.height / 2

    def update(self):
        """Update camera state with smooth interpolation"""
        # Smooth position with eased interpolation
        self.x = lerp(self.x, self.target_x, self.follow_speed)
        self.y = lerp(self.y, self.target_y, self.follow_speed)

        # Smooth zoom with ease
        self.zoom = lerp(self.zoom, self.target_zoom, self.zoom_speed)

        # Smooth letterbox transition
        self.letterbox = lerp(self.letterbox, self.target_letterbox, 0.06)

        # Smooth organic shake using sine waves (not random noise)
        if self.shake_intensity > 0.1:
            # Use multiple sine waves for smooth organic shake
            t = np.random.rand() * 100  # Phase offset for variety
            shake_x = (np.sin(t * 17.3) * 0.5 + np.sin(t * 23.7) * 0.3 + np.sin(t * 41.1) * 0.2)
            shake_y = (np.sin(t * 19.1) * 0.5 + np.sin(t * 29.3) * 0.3 + np.sin(t * 37.9) * 0.2)
            self.shake_offset_x = shake_x * self.shake_intensity
            self.shake_offset_y = shake_y * self.shake_intensity
            self.shake_intensity *= self.shake_decay
        else:
            # Smooth return to center
            self.shake_offset_x = lerp(self.shake_offset_x, 0, 0.2)
            self.shake_offset_y = lerp(self.shake_offset_y, 0, 0.2)
            if abs(self.shake_offset_x) < 0.1:
                self.shake_offset_x = 0
            self.shake_offset_y = 0
            self.shake_intensity = 0

    def get_view_bounds(self) -> Tuple[float, float, float, float]:
        """Get the current view bounds (x_min, x_max, y_min, y_max)"""
        # Calculate zoomed dimensions
        view_width = self.width / self.zoom
        view_height = self.height / self.zoom

        # Center offset
        center_x = self.x + self.width / 2 + self.shake_offset_x
        center_y = self.y + self.height / 2 + self.shake_offset_y

        x_min = center_x - view_width / 2
        x_max = center_x + view_width / 2
        y_min = center_y - view_height / 2
        y_max = center_y + view_height / 2

        return x_min, x_max, y_min, y_max

    def apply_to_axes(self, ax):
        """Apply camera transform to matplotlib axes"""
        x_min, x_max, y_min, y_max = self.get_view_bounds()
        ax.set_xlim(x_min, x_max)
        ax.set_ylim(y_min, y_max)

    def render_letterbox(self, ax):
        """Render cinematic letterbox bars"""
        if self.letterbox > 0.01:
            bar_height = self.height * 0.1 * self.letterbox
            x_min, x_max, y_min, y_max = self.get_view_bounds()

            # Top bar
            top_bar = patches.Rectangle(
                (x_min, y_max - bar_height * (y_max - y_min) / self.height),
                x_max - x_min, bar_height * (y_max - y_min) / self.height * 2,
                color='black', zorder=1000
            )
            ax.add_patch(top_bar)

            # Bottom bar
            bottom_bar = patches.Rectangle(
                (x_min, y_min - bar_height * (y_max - y_min) / self.height),
                x_max - x_min, bar_height * (y_max - y_min) / self.height * 2,
                color='black', zorder=1000
            )
            ax.add_patch(bottom_bar)

    def world_to_screen(self, world_x: float, world_y: float) -> Tuple[float, float]:
        """Convert world coordinates to screen coordinates"""
        return world_x, world_y  # With proper axes limits, this is identity

    def get_parallax_offset(self, depth: float) -> Tuple[float, float]:
        """Get parallax offset for a given depth layer (0=foreground, 1=background)"""
        parallax_factor = 1 - depth * 0.5
        offset_x = self.x * (1 - parallax_factor)
        offset_y = self.y * (1 - parallax_factor)
        return offset_x, offset_y


# ╔═══════════════════════════════════════════════════════════════════════════════╗
# ║                         WEATHER SYSTEM                                        ║
# ╚═══════════════════════════════════════════════════════════════════════════════╝

class WeatherType(Enum):
    CLEAR = auto()
    CLOUDY = auto()
    RAIN = auto()
    STORM = auto()
    SNOW = auto()
    FOG = auto()
    MAGICAL = auto()


class WeatherSystem:
    """Dynamic weather system with transitions"""

    def __init__(self, particles: AdvancedParticleSystem):
        self.particles = particles
        self.current_weather = WeatherType.CLEAR
        self.target_weather = WeatherType.CLEAR
        self.intensity = 0
        self.target_intensity = 0
        self.transition_speed = 0.02

        # Storm specifics
        self.lightning_timer = 0
        self.lightning_flash = 0
        self.thunder_delay = 0

        # Wind
        self.wind_strength = 0
        self.wind_direction = 0  # radians

        # Clouds
        self.clouds: List[Dict] = []
        self._generate_clouds()

    def _generate_clouds(self):
        """Generate cloud positions"""
        self.clouds = []
        for _ in range(15):
            self.clouds.append({
                'x': np.random.uniform(-200, WIDTH + 200),
                'y': np.random.uniform(HEIGHT * 0.6, HEIGHT * 0.95),
                'size': np.random.uniform(100, 300),
                'speed': np.random.uniform(0.2, 1.0),
                'opacity': np.random.uniform(0.3, 0.8),
            })

    def set_weather(self, weather: WeatherType, intensity: float = 1.0, immediate: bool = False):
        """Set target weather"""
        self.target_weather = weather
        self.target_intensity = clamp(intensity, 0, 1)
        if immediate:
            self.current_weather = weather
            self.intensity = intensity

    def update(self, frame: int):
        """Update weather state"""
        # Transition intensity
        self.intensity = lerp(self.intensity, self.target_intensity, self.transition_speed)

        # Weather-specific updates
        if self.current_weather == WeatherType.RAIN or self.target_weather == WeatherType.RAIN:
            if self.intensity > 0.1:
                self.particles.emit_rain(WIDTH, HEIGHT, self.intensity)

        if self.current_weather == WeatherType.SNOW or self.target_weather == WeatherType.SNOW:
            if self.intensity > 0.1:
                self.particles.emit_snow(WIDTH, HEIGHT, self.intensity)

        if self.current_weather == WeatherType.STORM or self.target_weather == WeatherType.STORM:
            if self.intensity > 0.1:
                self.particles.emit_rain(WIDTH, HEIGHT, self.intensity * 2)

                # Lightning
                self.lightning_timer -= 1
                if self.lightning_timer <= 0 and np.random.random() < 0.02 * self.intensity:
                    self.lightning_flash = 10
                    self.thunder_delay = np.random.randint(20, 60)
                    self.lightning_timer = np.random.randint(60, 180)

        # Update lightning flash
        if self.lightning_flash > 0:
            self.lightning_flash -= 1

        # Update clouds
        for cloud in self.clouds:
            cloud['x'] += cloud['speed'] + self.wind_strength
            if cloud['x'] > WIDTH + 300:
                cloud['x'] = -300
            elif cloud['x'] < -300:
                cloud['x'] = WIDTH + 300

        # Weather transition
        if self.intensity < 0.1 and self.target_weather != self.current_weather:
            self.current_weather = self.target_weather

    def render_sky_overlay(self, ax, base_color: str) -> str:
        """Get modified sky color based on weather"""
        if self.current_weather == WeatherType.STORM:
            return lerp_color(base_color, Palette.SKY_STORM, self.intensity * 0.7)
        elif self.current_weather == WeatherType.CLOUDY:
            return lerp_color(base_color, '#9CA3AF', self.intensity * 0.4)
        elif self.current_weather == WeatherType.FOG:
            return lerp_color(base_color, Palette.FOG, self.intensity * 0.5)
        return base_color

    def render(self, ax):
        """Render weather effects"""
        # Lightning flash
        if self.lightning_flash > 0:
            flash_alpha = self.lightning_flash / 10 * 0.8
            flash = patches.Rectangle((0, 0), WIDTH, HEIGHT,
                                       color='white', alpha=flash_alpha, zorder=500)
            ax.add_patch(flash)

            # Lightning bolt
            if self.lightning_flash > 7:
                bolt_x = np.random.uniform(WIDTH * 0.2, WIDTH * 0.8)
                self._draw_lightning(ax, bolt_x, HEIGHT, bolt_x + np.random.uniform(-100, 100), HEIGHT * 0.3)

        # Clouds
        cloud_opacity_mult = 1.0
        if self.current_weather in [WeatherType.RAIN, WeatherType.STORM]:
            cloud_opacity_mult = 1.5
        elif self.current_weather == WeatherType.CLEAR:
            cloud_opacity_mult = 0.3

        for cloud in self.clouds:
            self._draw_cloud(ax, cloud['x'], cloud['y'], cloud['size'],
                           cloud['opacity'] * cloud_opacity_mult * self.intensity if self.current_weather != WeatherType.CLEAR else cloud['opacity'] * 0.3)

        # Fog overlay
        if self.current_weather == WeatherType.FOG and self.intensity > 0.1:
            fog = patches.Rectangle((0, 0), WIDTH, HEIGHT,
                                    color=Palette.FOG, alpha=self.intensity * 0.4, zorder=200)
            ax.add_patch(fog)

    def _draw_cloud(self, ax, x: float, y: float, size: float, opacity: float):
        """Draw a fluffy cloud"""
        opacity = clamp(opacity, 0, 0.9)
        # Cloud is made of overlapping circles
        offsets = [
            (0, 0, 1.0),
            (-0.3, 0.1, 0.7),
            (0.3, 0.1, 0.7),
            (-0.15, 0.2, 0.5),
            (0.15, 0.2, 0.5),
        ]
        for ox, oy, scale in offsets:
            circle = patches.Circle(
                (x + ox * size, y + oy * size),
                size * 0.4 * scale,
                color='white', alpha=opacity, zorder=50
            )
            ax.add_patch(circle)

    def _draw_lightning(self, ax, x1: float, y1: float, x2: float, y2: float, branches: int = 3):
        """Draw a lightning bolt"""
        points = [(x1, y1)]
        segments = 8
        for i in range(1, segments):
            t = i / segments
            x = lerp(x1, x2, t) + np.random.uniform(-50, 50)
            y = lerp(y1, y2, t)
            points.append((x, y))
        points.append((x2, y2))

        # Draw main bolt
        xs = [p[0] for p in points]
        ys = [p[1] for p in points]
        ax.plot(xs, ys, color=Palette.LIGHTNING, linewidth=4, zorder=501, alpha=0.9)
        ax.plot(xs, ys, color='white', linewidth=2, zorder=502, alpha=1.0)

        # Draw branches
        for _ in range(branches):
            branch_start = np.random.randint(1, len(points) - 2)
            bx1, by1 = points[branch_start]
            bx2 = bx1 + np.random.uniform(-100, 100)
            by2 = by1 - np.random.uniform(50, 150)
            branch_points = [(bx1, by1)]
            for i in range(1, 4):
                t = i / 4
                bx = lerp(bx1, bx2, t) + np.random.uniform(-20, 20)
                by = lerp(by1, by2, t)
                branch_points.append((bx, by))
            bxs = [p[0] for p in branch_points]
            bys = [p[1] for p in branch_points]
            ax.plot(bxs, bys, color=Palette.LIGHTNING, linewidth=2, zorder=501, alpha=0.7)


# ╔═══════════════════════════════════════════════════════════════════════════════╗
# ║                         LIGHTING SYSTEM                                       ║
# ╚═══════════════════════════════════════════════════════════════════════════════╝

class TimeOfDay(Enum):
    DAWN = auto()
    MORNING = auto()
    NOON = auto()
    AFTERNOON = auto()
    SUNSET = auto()
    DUSK = auto()
    NIGHT = auto()
    MIDNIGHT = auto()


class LightingSystem:
    """Dynamic lighting and time of day system"""

    TIME_COLORS = {
        TimeOfDay.DAWN: {'sky': '#FFB6C1', 'ambient': (1.0, 0.9, 0.9), 'sun_pos': 0.1},
        TimeOfDay.MORNING: {'sky': '#87CEEB', 'ambient': (1.0, 1.0, 0.95), 'sun_pos': 0.3},
        TimeOfDay.NOON: {'sky': '#87CEEB', 'ambient': (1.0, 1.0, 1.0), 'sun_pos': 0.5},
        TimeOfDay.AFTERNOON: {'sky': '#87CEEB', 'ambient': (1.0, 0.98, 0.95), 'sun_pos': 0.7},
        TimeOfDay.SUNSET: {'sky': '#FF6B4A', 'ambient': (1.0, 0.8, 0.7), 'sun_pos': 0.9},
        TimeOfDay.DUSK: {'sky': '#4A3B6B', 'ambient': (0.7, 0.6, 0.8), 'sun_pos': 0.95},
        TimeOfDay.NIGHT: {'sky': '#0D1B2A', 'ambient': (0.3, 0.3, 0.5), 'sun_pos': 0},
        TimeOfDay.MIDNIGHT: {'sky': '#0A0A0F', 'ambient': (0.2, 0.2, 0.3), 'sun_pos': 0},
    }

    def __init__(self):
        self.current_time = TimeOfDay.NOON
        self.target_time = TimeOfDay.NOON
        self.transition_progress = 1.0
        self.transition_speed = 0.01

        # Point lights
        self.point_lights: List[Dict] = []

        # Global modifiers
        self.brightness = 1.0
        self.contrast = 1.0

        # Stars (for night)
        self.stars = [(np.random.uniform(0, WIDTH),
                       np.random.uniform(HEIGHT * 0.4, HEIGHT),
                       np.random.uniform(0.3, 1.0),
                       np.random.uniform(0, 2*np.pi)) for _ in range(200)]

    def set_time(self, time: TimeOfDay, immediate: bool = False):
        """Set target time of day"""
        if time != self.current_time:
            self.target_time = time
            if immediate:
                self.current_time = time
                self.transition_progress = 1.0
            else:
                self.transition_progress = 0.0

    def add_point_light(self, x: float, y: float, radius: float,
                        color: Tuple[float, float, float] = (1, 0.9, 0.7),
                        intensity: float = 1.0) -> int:
        """Add a point light source"""
        light = {
            'x': x, 'y': y,
            'radius': radius,
            'color': color,
            'intensity': intensity,
            'flicker': 0,
        }
        self.point_lights.append(light)
        return len(self.point_lights) - 1

    def update_point_light(self, index: int, x: float = None, y: float = None,
                          intensity: float = None):
        """Update a point light"""
        if 0 <= index < len(self.point_lights):
            if x is not None:
                self.point_lights[index]['x'] = x
            if y is not None:
                self.point_lights[index]['y'] = y
            if intensity is not None:
                self.point_lights[index]['intensity'] = intensity

    def remove_point_light(self, index: int):
        """Remove a point light"""
        if 0 <= index < len(self.point_lights):
            self.point_lights.pop(index)

    def clear_point_lights(self):
        """Remove all point lights"""
        self.point_lights = []

    def update(self, frame: int):
        """Update lighting state"""
        # Transition between times
        if self.transition_progress < 1.0:
            self.transition_progress = min(1.0, self.transition_progress + self.transition_speed)
            if self.transition_progress >= 1.0:
                self.current_time = self.target_time

        # Update point light flicker
        for light in self.point_lights:
            light['flicker'] = 0.9 + np.random.uniform(-0.1, 0.1)

    def get_sky_color(self) -> str:
        """Get current sky color"""
        if self.transition_progress >= 1.0:
            return self.TIME_COLORS[self.current_time]['sky']

        current_sky = self.TIME_COLORS[self.current_time]['sky']
        target_sky = self.TIME_COLORS[self.target_time]['sky']
        return lerp_color(current_sky, target_sky,
                         Easing.ease_in_out_cubic(self.transition_progress))

    def get_ambient(self) -> Tuple[float, float, float]:
        """Get current ambient light color"""
        if self.transition_progress >= 1.0:
            return self.TIME_COLORS[self.current_time]['ambient']

        current = self.TIME_COLORS[self.current_time]['ambient']
        target = self.TIME_COLORS[self.target_time]['ambient']
        t = Easing.ease_in_out_cubic(self.transition_progress)
        return (
            lerp(current[0], target[0], t),
            lerp(current[1], target[1], t),
            lerp(current[2], target[2], t)
        )

    def render_celestial(self, ax, frame: int):
        """Render sun, moon, and stars"""
        time_data = self.TIME_COLORS[self.current_time]
        sun_pos = time_data['sun_pos']

        if self.current_time in [TimeOfDay.NIGHT, TimeOfDay.MIDNIGHT]:
            # Render stars
            for sx, sy, brightness, phase in self.stars:
                twinkle = 0.5 + 0.5 * np.sin(frame * 0.05 + phase)
                alpha = brightness * twinkle
                ax.scatter([sx], [sy], c='white', s=brightness * 20,
                          alpha=clamp(alpha, 0.1, 1.0), zorder=5)

            # Render moon
            moon_x = WIDTH * 0.8
            moon_y = HEIGHT * 0.85
            # Moon glow
            for i in range(3):
                glow = patches.Circle((moon_x, moon_y), 60 + i * 20,
                                      color=Palette.MOON_GLOW,
                                      alpha=0.1 - i * 0.03, zorder=6)
                ax.add_patch(glow)
            # Moon body
            moon = patches.Circle((moon_x, moon_y), 50,
                                 color=Palette.MOON, zorder=7)
            ax.add_patch(moon)
            # Moon craters
            crater_positions = [(moon_x - 15, moon_y + 10),
                               (moon_x + 20, moon_y - 5),
                               (moon_x + 5, moon_y + 20)]
            for cx, cy in crater_positions:
                crater = patches.Circle((cx, cy), 8,
                                        color='#E5E5D0', zorder=8)
                ax.add_patch(crater)

        elif sun_pos > 0:
            # Render sun
            sun_x = WIDTH * sun_pos
            sun_y = HEIGHT * (0.5 + 0.4 * np.sin(sun_pos * np.pi))

            # Sun glow
            for i in range(5):
                glow = patches.Circle((sun_x, sun_y), 80 + i * 30,
                                      color=Palette.SUN_GLOW,
                                      alpha=0.15 - i * 0.025, zorder=3)
                ax.add_patch(glow)

            # Sun rays
            num_rays = 12
            for i in range(num_rays):
                angle = (i / num_rays) * 2 * np.pi + frame * 0.005
                ray_length = 100 + 20 * np.sin(frame * 0.03 + i)
                ray_x = sun_x + np.cos(angle) * ray_length
                ray_y = sun_y + np.sin(angle) * ray_length
                ax.plot([sun_x, ray_x], [sun_y, ray_y],
                       color=Palette.SUN, linewidth=3, alpha=0.4, zorder=4)

            # Sun body
            sun = patches.Circle((sun_x, sun_y), 60,
                                color=Palette.SUN, zorder=5)
            ax.add_patch(sun)

    def render_point_lights(self, ax):
        """Render point light effects"""
        for light in self.point_lights:
            intensity = light['intensity'] * light['flicker']
            r, g, b = light['color']

            # Render light glow
            for i in range(5):
                radius = light['radius'] * (1 + i * 0.4)
                alpha = intensity * (0.2 - i * 0.035)
                glow = patches.Circle(
                    (light['x'], light['y']), radius,
                    color=(r, g, b), alpha=clamp(alpha, 0, 0.3), zorder=150
                )
                ax.add_patch(glow)

    def apply_ambient_to_color(self, color: str) -> str:
        """Apply ambient lighting to a color"""
        ambient = self.get_ambient()

        # Parse hex color
        r = int(color.lstrip('#')[0:2], 16) / 255
        g = int(color.lstrip('#')[2:4], 16) / 255
        b = int(color.lstrip('#')[4:6], 16) / 255

        # Apply ambient
        r = clamp(r * ambient[0] * self.brightness, 0, 1)
        g = clamp(g * ambient[1] * self.brightness, 0, 1)
        b = clamp(b * ambient[2] * self.brightness, 0, 1)

        return f'#{int(r*255):02x}{int(g*255):02x}{int(b*255):02x}'

    def render_god_rays(self, ax, frame: int, source_x: float = None, source_y: float = None,
                        color: str = '#FFD700', intensity: float = 0.3, num_rays: int = 8):
        """Render cinematic god rays / volumetric light shafts"""
        if source_x is None:
            # Default to sun position
            time_data = self.TIME_COLORS[self.current_time]
            sun_pos = time_data['sun_pos']
            if sun_pos <= 0:
                return  # No god rays at night
            source_x = WIDTH * sun_pos
            source_y = HEIGHT * (0.5 + 0.4 * np.sin(sun_pos * np.pi))

        # Parse color
        r = int(color.lstrip('#')[0:2], 16) / 255
        g = int(color.lstrip('#')[2:4], 16) / 255
        b = int(color.lstrip('#')[4:6], 16) / 255

        # Create volumetric light shafts
        for i in range(num_rays):
            # Each ray has different angle and animation phase
            base_angle = (i / num_rays) * np.pi * 0.6 - np.pi * 0.3  # Spread downward
            angle_wobble = np.sin(frame * 0.02 + i * 1.5) * 0.05
            angle = base_angle + angle_wobble - np.pi / 2  # Point downward

            # Ray properties vary over time
            ray_alpha = intensity * (0.5 + 0.5 * np.sin(frame * 0.015 + i * 0.7))
            ray_length = HEIGHT * 0.8 * (0.8 + 0.2 * np.sin(frame * 0.01 + i))
            ray_width = 40 + 20 * np.sin(frame * 0.025 + i * 1.2)

            # Calculate ray endpoints
            end_x = source_x + np.cos(angle) * ray_length
            end_y = source_y + np.sin(angle) * ray_length

            # Draw tapered ray using polygon
            perp_x = np.cos(angle + np.pi/2)
            perp_y = np.sin(angle + np.pi/2)

            # Ray gets wider as it goes down
            top_width = ray_width * 0.3
            bottom_width = ray_width * 2

            vertices = [
                (source_x + perp_x * top_width, source_y + perp_y * top_width),
                (source_x - perp_x * top_width, source_y - perp_y * top_width),
                (end_x - perp_x * bottom_width, end_y - perp_y * bottom_width),
                (end_x + perp_x * bottom_width, end_y + perp_y * bottom_width),
            ]

            ray_patch = patches.Polygon(vertices, closed=True,
                                        facecolor=(r, g, b, clamp(ray_alpha * 0.15, 0, 0.3)),
                                        edgecolor='none', zorder=4)
            ax.add_patch(ray_patch)

            # Add inner brighter core
            core_vertices = [
                (source_x + perp_x * top_width * 0.3, source_y + perp_y * top_width * 0.3),
                (source_x - perp_x * top_width * 0.3, source_y - perp_y * top_width * 0.3),
                (end_x - perp_x * bottom_width * 0.5, end_y - perp_y * bottom_width * 0.5),
                (end_x + perp_x * bottom_width * 0.5, end_y + perp_y * bottom_width * 0.5),
            ]
            core_patch = patches.Polygon(core_vertices, closed=True,
                                         facecolor=(1, 1, 1, clamp(ray_alpha * 0.08, 0, 0.15)),
                                         edgecolor='none', zorder=5)
            ax.add_patch(core_patch)

    def render_vignette(self, ax, intensity: float = 0.4, color: str = 'black'):
        """Render cinematic vignette effect for atmospheric depth"""
        if intensity < 0.01:
            return

        # Create smooth radial vignette using concentric ellipses
        center_x, center_y = WIDTH / 2, HEIGHT / 2
        max_radius = np.sqrt(WIDTH**2 + HEIGHT**2) / 2

        num_layers = 15
        for i in range(num_layers):
            # Progress from edge (0) to center (1)
            t = i / num_layers

            # Ellipse gets smaller toward center
            radius_x = WIDTH * (0.6 + t * 0.5)
            radius_y = HEIGHT * (0.6 + t * 0.5)

            # Alpha decreases toward center (more opaque at edges)
            layer_alpha = intensity * (1 - t) ** 2 * 0.12

            vignette = patches.Ellipse((center_x, center_y), radius_x * 2, radius_y * 2,
                                       fill=False, edgecolor=color,
                                       linewidth=80, alpha=clamp(layer_alpha, 0, 0.3),
                                       zorder=950)
            ax.add_patch(vignette)

    def render_lens_flare(self, ax, frame: int, source_x: float, source_y: float,
                          intensity: float = 0.5):
        """Render cinematic lens flare effect"""
        # Calculate flare line from source through center
        center_x, center_y = WIDTH / 2, HEIGHT / 2
        dx = center_x - source_x
        dy = center_y - source_y

        # Normalize direction
        dist = np.sqrt(dx**2 + dy**2)
        if dist < 1:
            return
        dx /= dist
        dy /= dist

        # Flare elements along the line
        flare_colors = ['#FFD700', '#FF6B4A', '#00BFFF', '#FF69B4', '#FFFFFF']
        flare_sizes = [30, 20, 45, 15, 25]
        flare_positions = [0.3, 0.5, 0.7, 0.85, 1.0]

        for i, (color, size, pos) in enumerate(zip(flare_colors, flare_sizes, flare_positions)):
            flare_x = source_x + dx * dist * pos * 1.5
            flare_y = source_y + dy * dist * pos * 1.5

            # Pulsing size
            pulse = 1 + 0.2 * np.sin(frame * 0.05 + i * 1.5)

            # Hexagonal flare shape for some elements
            if i % 2 == 0:
                flare = patches.RegularPolygon((flare_x, flare_y), numVertices=6,
                                               radius=size * pulse,
                                               facecolor=color,
                                               alpha=clamp(intensity * 0.3 * (1 - pos * 0.5), 0, 0.4),
                                               zorder=960)
            else:
                flare = patches.Circle((flare_x, flare_y), size * pulse * 0.7,
                                       facecolor=color,
                                       alpha=clamp(intensity * 0.25 * (1 - pos * 0.5), 0, 0.35),
                                       zorder=960)
            ax.add_patch(flare)

        # Anamorphic flare streak (horizontal light streak)
        streak_width = 300 * intensity
        streak_height = 8
        streak = patches.Rectangle((source_x - streak_width, source_y - streak_height/2),
                                   streak_width * 2, streak_height,
                                   facecolor='#ADD8E6', alpha=clamp(intensity * 0.4, 0, 0.5),
                                   zorder=955)
        ax.add_patch(streak)

    def render_film_grain(self, ax, frame: int, intensity: float = 0.03):
        """Render subtle film grain for cinematic texture"""
        if intensity < 0.005:
            return

        # Create deterministic but varied grain pattern
        np.random.seed(frame % 1000)  # Changes each frame for animated grain

        # Sparse grain dots for efficiency
        num_grains = int(150 * intensity * 10)
        for _ in range(num_grains):
            gx = np.random.uniform(0, WIDTH)
            gy = np.random.uniform(0, HEIGHT)
            grain_alpha = np.random.uniform(0.02, 0.08) * intensity * 10
            grain_size = np.random.uniform(2, 6)
            grain_color = np.random.choice(['white', '#888888', 'black'])

            ax.scatter([gx], [gy], c=grain_color, s=grain_size,
                      alpha=clamp(grain_alpha, 0, 0.1), zorder=970)

    def render_chromatic_aberration(self, ax, frame: int, intensity: float = 0.3):
        """Render chromatic aberration effect at screen edges for impact moments"""
        if intensity < 0.05:
            return

        # Chromatic aberration is strongest at corners/edges
        # We'll render colored edge overlays
        offset = intensity * 8

        # Red channel shift (top-left direction)
        for edge_pos in [(0, HEIGHT), (WIDTH, HEIGHT)]:
            ax.add_patch(patches.Rectangle(
                (edge_pos[0] - 50, edge_pos[1] - 50), 100, 100,
                facecolor='#FF0000', alpha=clamp(intensity * 0.15, 0, 0.2),
                zorder=965
            ))

        # Cyan channel shift (bottom-right direction)
        for edge_pos in [(0, 0), (WIDTH, 0)]:
            ax.add_patch(patches.Rectangle(
                (edge_pos[0] - 50, edge_pos[1] - 50), 100, 100,
                facecolor='#00FFFF', alpha=clamp(intensity * 0.15, 0, 0.2),
                zorder=965
            ))

        # Edge color fringing
        edge_width = 30 * intensity
        # Left edge - red tint
        ax.add_patch(patches.Rectangle(
            (0, 0), edge_width, HEIGHT,
            facecolor='#FF0000', alpha=clamp(intensity * 0.1, 0, 0.15),
            zorder=964
        ))
        # Right edge - cyan tint
        ax.add_patch(patches.Rectangle(
            (WIDTH - edge_width, 0), edge_width, HEIGHT,
            facecolor='#00FFFF', alpha=clamp(intensity * 0.1, 0, 0.15),
            zorder=964
        ))

    def render_dust_motes(self, ax, frame: int, density: float = 1.0):
        """Render floating dust particles for atmospheric depth"""
        if density < 0.1:
            return

        np.random.seed(42)  # Consistent positions
        num_motes = int(25 * density)

        for i in range(num_motes):
            # Each mote has its own floating pattern
            base_x = np.random.uniform(0, WIDTH)
            base_y = np.random.uniform(HEIGHT * 0.3, HEIGHT)

            # Gentle floating motion
            float_x = np.sin(frame * 0.008 + i * 2.5) * 30
            float_y = np.sin(frame * 0.012 + i * 1.7) * 20 + (frame * 0.1) % HEIGHT

            mote_x = (base_x + float_x) % WIDTH
            mote_y = (base_y + float_y) % (HEIGHT * 0.7) + HEIGHT * 0.3

            # Size varies with "depth"
            depth = (i % 5) / 5
            size = 3 + depth * 8
            alpha = 0.1 + depth * 0.2

            # Slight twinkle
            twinkle = 0.8 + 0.2 * np.sin(frame * 0.1 + i)

            ax.scatter([mote_x], [mote_y], c='white', s=size * twinkle,
                      alpha=clamp(alpha * density, 0.05, 0.4), zorder=100)

    def render_bloom(self, ax, frame: int, source_x: float, source_y: float,
                    radius: float = 100, color: str = '#FFFFFF', intensity: float = 0.5):
        """Render bloom/glow effect around bright light sources"""
        if intensity < 0.05:
            return

        # Parse color
        r = int(color.lstrip('#')[0:2], 16) / 255
        g = int(color.lstrip('#')[2:4], 16) / 255
        b = int(color.lstrip('#')[4:6], 16) / 255

        # Multiple soft layers for smooth bloom
        num_layers = 8
        for i in range(num_layers):
            layer_radius = radius * (1 + i * 0.5)
            layer_alpha = intensity * (1 - i / num_layers) ** 2 * 0.15

            # Pulsing bloom
            pulse = 1 + 0.1 * np.sin(frame * 0.05 + i * 0.5)

            bloom = patches.Circle((source_x, source_y), layer_radius * pulse,
                                   facecolor=(r, g, b, clamp(layer_alpha, 0, 0.2)),
                                   edgecolor='none', zorder=80)
            ax.add_patch(bloom)


# ╔═══════════════════════════════════════════════════════════════════════════════╗
# ║                         CHARACTER SYSTEM                                      ║
# ╚═══════════════════════════════════════════════════════════════════════════════╝

class Emotion(Enum):
    NEUTRAL = auto()
    HAPPY = auto()
    SAD = auto()
    ANGRY = auto()
    SCARED = auto()
    DETERMINED = auto()
    LOVE = auto()
    SHOCKED = auto()
    SLEEPING = auto()
    HURT = auto()
    POWERFUL = auto()
    EVIL = auto()


class Character:
    """Base class for all animated characters"""

    def __init__(self, x: float, y: float, scale: float = 1.0, name: str = ""):
        self.x = x
        self.y = y
        self.scale = scale
        self.name = name
        self.emotion = Emotion.NEUTRAL
        self.facing = 1  # 1 = right, -1 = left
        self.alpha = 1.0

        # Animation state
        self.anim_frame = 0
        self.blink_timer = np.random.randint(0, 120)
        self.breath_phase = np.random.uniform(0, 2 * np.pi)

        # Movement
        self.target_x = x
        self.target_y = y
        self.velocity_x = 0
        self.velocity_y = 0
        self.jump_velocity = 0
        self.is_jumping = False
        self.ground_y = y

        # Speech
        self.speech_text = ""
        self.speech_timer = 0

    def move_to(self, x: float, y: float, speed: float = 0.1):
        """Set movement target"""
        self.target_x = x
        self.target_y = y
        if x < self.x:
            self.facing = -1
        elif x > self.x:
            self.facing = 1

    def jump(self, power: float = 15):
        """Make character jump"""
        if not self.is_jumping:
            self.jump_velocity = power
            self.is_jumping = True
            self.ground_y = self.y

    def say(self, text: str, duration: int = 180):
        """Make character speak"""
        self.speech_text = text
        self.speech_timer = duration

    def update(self, frame: int):
        """Update character state with smooth animations"""
        self.anim_frame = frame

        # Smooth blinking with variable timing
        self.blink_timer -= 1
        if self.blink_timer <= 0:
            self.blink_timer = np.random.randint(120, 240)

        # Smoother movement interpolation with easing
        move_speed = 0.06
        self.x = lerp(self.x, self.target_x, move_speed)
        self.y = lerp(self.y, self.target_y, move_speed)

        # Smooth jump physics with better arc
        if self.is_jumping:
            self.y += self.jump_velocity
            self.jump_velocity -= 0.65  # Slightly slower gravity for smoother arc
            if self.y <= self.ground_y:
                self.y = self.ground_y
                self.is_jumping = False
                self.jump_velocity = 0

        # Speech timer with fade
        if self.speech_timer > 0:
            self.speech_timer -= 1

    def render(self, ax, frame: int):
        """Override in subclasses"""
        raise NotImplementedError

    def render_speech(self, ax):
        """Render speech bubble"""
        if self.speech_timer > 0 and self.speech_text:
            bubble_x = self.x + 60 * self.scale
            bubble_y = self.y + 80 * self.scale

            # Bubble background
            bubble = patches.FancyBboxPatch(
                (bubble_x - 60, bubble_y - 20), 120, 40,
                boxstyle="round,pad=0.05,rounding_size=10",
                facecolor='white', edgecolor='black',
                linewidth=2, zorder=200
            )
            ax.add_patch(bubble)

            # Bubble pointer
            pointer = patches.Polygon([
                [bubble_x - 20, bubble_y - 20],
                [self.x + 20 * self.scale, self.y + 50 * self.scale],
                [bubble_x, bubble_y - 20]
            ], color='white', zorder=199)
            ax.add_patch(pointer)

            # Text
            alpha = min(1, self.speech_timer / 30) if self.speech_timer < 30 else 1
            ax.text(bubble_x, bubble_y, self.speech_text,
                   ha='center', va='center', fontsize=10,
                   color='black', alpha=alpha, zorder=201)


class Frog(Character):
    """Eli the Frog - Our Hero"""

    def __init__(self, x: float, y: float, scale: float = 1.0,
                 color: str = 'green', name: str = "Eli"):
        super().__init__(x, y, scale, name)

        # Color variants
        self.colors = {
            'green': (Palette.FROG_BODY, Palette.FROG_BELLY, Palette.FROG_DARK),
            'golden': ('#FFD700', '#FFEC8B', '#DAA520'),
            'blue': ('#4169E1', '#87CEEB', '#0000CD'),
            'red': ('#DC143C', '#FA8072', '#8B0000'),
            'dark': ('#2F4F4F', '#696969', '#1C1C1C'),
            'princess': ('#FF69B4', '#FFB6C1', '#DB7093'),
        }
        self.body_color, self.belly_color, self.dark_color = self.colors.get(
            color, self.colors['green'])

        # Special states
        self.is_glowing = False
        self.glow_color = Palette.MAGIC_GREEN
        self.glow_intensity = 0
        self.power_level = 0  # For transformation effects
        self.has_crown = False
        self.mouth_open = 0

    def set_glow(self, enabled: bool, color: str = None, intensity: float = 1.0):
        """Enable/disable magical glow"""
        self.is_glowing = enabled
        self.glow_intensity = intensity if enabled else 0
        if color:
            self.glow_color = color

    def render(self, ax, frame: int):
        """Render the frog with all details and smooth animations"""
        if self.alpha <= 0:
            return

        s = self.scale * 50
        x, y = self.x, self.y

        # Smooth breathing animation with multiple frequencies for realism
        breath = (np.sin(frame * 0.04 + self.breath_phase) * 1.5 +
                  np.sin(frame * 0.11 + self.breath_phase * 0.7) * 0.5)

        # Subtle idle sway animation
        idle_sway_x = np.sin(frame * 0.02 + self.breath_phase) * s * 0.03
        idle_sway_y = np.sin(frame * 0.025 + self.breath_phase * 1.3) * s * 0.02
        x += idle_sway_x
        y += idle_sway_y

        # Enhanced glow effect with pulsing
        if self.is_glowing and self.glow_intensity > 0:
            pulse = 0.85 + 0.15 * np.sin(frame * 0.08)
            for i in range(4):
                glow_size = s * (2.2 + i * 0.6) * pulse
                glow = patches.Circle(
                    (x, y), glow_size,
                    color=self.glow_color,
                    alpha=self.glow_intensity * (0.18 - i * 0.04) * self.alpha,
                    zorder=9
                )
                ax.add_patch(glow)

        # Shadow
        shadow = patches.Ellipse(
            (x, y - s * 0.8), s * 2.2, s * 0.4,
            color='black', alpha=0.2 * self.alpha, zorder=8
        )
        ax.add_patch(shadow)

        # Back legs
        for side in [-1, 1]:
            leg_angle = 20 + np.sin(frame * 0.1) * 5 if not self.is_jumping else 45
            leg = patches.Ellipse(
                (x + side * s * 0.7 * self.facing, y - s * 0.5),
                s * 0.6, s * 0.35,
                angle=side * leg_angle * self.facing,
                color=self.dark_color, alpha=self.alpha, zorder=10
            )
            ax.add_patch(leg)

        # Body
        body_height = s * 1.4 + breath
        body = patches.Ellipse(
            (x, y), s * 2, body_height,
            color=self.body_color, alpha=self.alpha, zorder=11
        )
        ax.add_patch(body)

        # Belly
        belly = patches.Ellipse(
            (x, y - s * 0.1), s * 1.3, s * 0.9,
            color=self.belly_color, alpha=self.alpha, zorder=12
        )
        ax.add_patch(belly)

        # Front legs
        for side in [-1, 1]:
            front_leg = patches.Ellipse(
                (x + side * s * 0.5 * self.facing, y - s * 0.4),
                s * 0.35, s * 0.25,
                angle=side * -15 * self.facing,
                color=self.dark_color, alpha=self.alpha, zorder=13
            )
            ax.add_patch(front_leg)

        # Eyes
        is_blinking = self.blink_timer < 5
        eye_y = y + s * 0.4

        for side in [-1, 1]:
            eye_x = x + side * s * 0.4 * self.facing

            # Eye bulge
            bulge = patches.Circle(
                (eye_x, eye_y + s * 0.15), s * 0.35,
                color=self.body_color, alpha=self.alpha, zorder=14
            )
            ax.add_patch(bulge)

            if not is_blinking and self.emotion != Emotion.SLEEPING:
                # Eye white
                eye_white = patches.Circle(
                    (eye_x, eye_y), s * 0.28,
                    color='white', alpha=self.alpha, zorder=15
                )
                ax.add_patch(eye_white)

                # Pupil - varies by emotion
                pupil_size = s * 0.14
                pupil_offset_x = 0
                pupil_offset_y = 0

                if self.emotion == Emotion.SCARED:
                    pupil_size = s * 0.08
                elif self.emotion == Emotion.ANGRY:
                    pupil_offset_y = s * 0.05
                elif self.emotion == Emotion.LOVE:
                    # Heart-shaped indication
                    pupil_size = s * 0.12
                elif self.emotion == Emotion.EVIL:
                    pupil_size = s * 0.06

                pupil = patches.Circle(
                    (eye_x + pupil_offset_x, eye_y + pupil_offset_y), pupil_size,
                    color='black', alpha=self.alpha, zorder=16
                )
                ax.add_patch(pupil)

                # Eye highlight
                highlight = patches.Circle(
                    (eye_x + s * 0.08, eye_y + s * 0.08), s * 0.06,
                    color='white', alpha=self.alpha * 0.8, zorder=17
                )
                ax.add_patch(highlight)
            else:
                # Closed eye
                eye_line = patches.Rectangle(
                    (eye_x - s * 0.2, eye_y - s * 0.02),
                    s * 0.4, s * 0.04,
                    color=self.dark_color, alpha=self.alpha, zorder=15
                )
                ax.add_patch(eye_line)

        # Mouth - varies by emotion
        mouth_y = y - s * 0.2

        if self.emotion == Emotion.HAPPY or self.mouth_open > 0:
            mouth = patches.Arc(
                (x, mouth_y), s * 0.8, s * 0.5,
                angle=0, theta1=200, theta2=340,
                color=self.dark_color, linewidth=3, zorder=18
            )
            ax.add_patch(mouth)
        elif self.emotion == Emotion.SAD:
            mouth = patches.Arc(
                (x, mouth_y - s * 0.1), s * 0.5, s * 0.3,
                angle=0, theta1=20, theta2=160,
                color=self.dark_color, linewidth=3, zorder=18
            )
            ax.add_patch(mouth)
        elif self.emotion == Emotion.ANGRY:
            # Angry frown
            ax.plot([x - s * 0.3, x + s * 0.3],
                   [mouth_y + s * 0.05, mouth_y + s * 0.05],
                   color=self.dark_color, linewidth=3, zorder=18)
        elif self.emotion == Emotion.SHOCKED:
            mouth = patches.Circle(
                (x, mouth_y), s * 0.15,
                color=self.dark_color, alpha=self.alpha, zorder=18
            )
            ax.add_patch(mouth)
        else:
            # Neutral
            mouth = patches.Arc(
                (x, mouth_y), s * 0.5, s * 0.2,
                angle=0, theta1=200, theta2=340,
                color=self.dark_color, linewidth=2, zorder=18
            )
            ax.add_patch(mouth)

        # Crown (if has_crown)
        if self.has_crown:
            crown_y = y + s * 0.9
            # Crown base
            crown_points = [
                [x - s * 0.4, crown_y],
                [x - s * 0.35, crown_y + s * 0.3],
                [x - s * 0.2, crown_y + s * 0.15],
                [x, crown_y + s * 0.4],
                [x + s * 0.2, crown_y + s * 0.15],
                [x + s * 0.35, crown_y + s * 0.3],
                [x + s * 0.4, crown_y],
            ]
            crown = patches.Polygon(crown_points, color='#FFD700',
                                   alpha=self.alpha, zorder=20)
            ax.add_patch(crown)
            # Crown jewel
            jewel = patches.Circle((x, crown_y + s * 0.25), s * 0.08,
                                  color='#FF0000', alpha=self.alpha, zorder=21)
            ax.add_patch(jewel)

        # Emotion-specific effects
        if self.emotion == Emotion.LOVE:
            # Floating hearts
            for i in range(3):
                heart_y = y + s * (0.8 + (frame * 0.02 + i * 0.5) % 1.5)
                heart_x = x + s * 0.5 + np.sin(frame * 0.05 + i) * s * 0.3
                heart_alpha = 1 - ((frame * 0.02 + i * 0.5) % 1.5) / 1.5
                ax.text(heart_x, heart_y, '♥', fontsize=int(12 * self.scale),
                       color='#FF69B4', alpha=heart_alpha * self.alpha,
                       ha='center', va='center', zorder=25)

        elif self.emotion == Emotion.ANGRY:
            # Anger veins
            vein_x = x + s * 0.5
            vein_y = y + s * 0.6
            ax.text(vein_x, vein_y, '💢', fontsize=int(10 * self.scale),
                   alpha=self.alpha, ha='center', zorder=25)

        elif self.emotion == Emotion.POWERFUL:
            # Power aura
            for i in range(2):
                aura = patches.Circle(
                    (x, y), s * (2 + i * 0.5) + np.sin(frame * 0.1) * s * 0.2,
                    fill=False, edgecolor=self.glow_color,
                    linewidth=2, alpha=0.5 - i * 0.2, zorder=8
                )
                ax.add_patch(aura)

        # Render speech bubble
        self.render_speech(ax)


class WiseTurtle(Character):
    """Sage the Ancient Turtle - Eli's Mentor"""

    def __init__(self, x: float, y: float, scale: float = 1.5):
        super().__init__(x, y, scale, "Sage")
        self.shell_pattern_phase = np.random.uniform(0, 2 * np.pi)

    def render(self, ax, frame: int):
        if self.alpha <= 0:
            return

        s = self.scale * 40
        x, y = self.x, self.y

        # Shell
        shell = patches.Ellipse((x, y + s * 0.2), s * 2.5, s * 2,
                                color='#8B4513', alpha=self.alpha, zorder=10)
        ax.add_patch(shell)

        # Shell pattern (hexagonal-ish)
        shell_top = patches.Ellipse((x, y + s * 0.3), s * 2, s * 1.5,
                                    color='#A0522D', alpha=self.alpha, zorder=11)
        ax.add_patch(shell_top)

        # Shell segments
        for i in range(5):
            angle = (i / 5) * np.pi + 0.3
            seg_x = x + np.cos(angle) * s * 0.7
            seg_y = y + s * 0.3 + np.sin(angle) * s * 0.5
            seg = patches.Circle((seg_x, seg_y), s * 0.3,
                                 color='#6B4423', alpha=self.alpha * 0.7, zorder=12)
            ax.add_patch(seg)

        # Head
        head_x = x + s * 1.2 * self.facing
        head = patches.Ellipse((head_x, y), s * 0.8, s * 0.6,
                              color='#6B8E23', alpha=self.alpha, zorder=13)
        ax.add_patch(head)

        # Wise old eyes
        for side in [-1, 1]:
            eye_x = head_x + side * s * 0.15 * self.facing
            eye_y = y + s * 0.1

            # Eye
            eye = patches.Circle((eye_x, eye_y), s * 0.12,
                                 color='white', alpha=self.alpha, zorder=14)
            ax.add_patch(eye)

            # Small wise pupil
            pupil = patches.Circle((eye_x, eye_y), s * 0.05,
                                   color='black', alpha=self.alpha, zorder=15)
            ax.add_patch(pupil)

        # Wise wrinkles / eyebrows
        brow_y = y + s * 0.25
        ax.plot([head_x - s * 0.25, head_x - s * 0.1],
               [brow_y, brow_y + s * 0.05],
               color='#556B2F', linewidth=2, alpha=self.alpha, zorder=16)
        ax.plot([head_x + s * 0.1, head_x + s * 0.25],
               [brow_y + s * 0.05, brow_y],
               color='#556B2F', linewidth=2, alpha=self.alpha, zorder=16)

        # Gentle smile
        mouth = patches.Arc((head_x, y - s * 0.15), s * 0.3, s * 0.15,
                           angle=0, theta1=200, theta2=340,
                           color='#556B2F', linewidth=2, zorder=16)
        ax.add_patch(mouth)

        # Legs
        leg_positions = [(-1, -0.3), (1, -0.3), (-0.8, 0.5), (0.8, 0.5)]
        for lx, ly in leg_positions:
            leg = patches.Ellipse((x + lx * s, y + ly * s * 0.5 - s * 0.3),
                                 s * 0.4, s * 0.25,
                                 color='#6B8E23', alpha=self.alpha, zorder=9)
            ax.add_patch(leg)

        # Tail
        tail = patches.Polygon([
            [x - s * 1.2, y - s * 0.2],
            [x - s * 1.5, y - s * 0.3],
            [x - s * 1.2, y - s * 0.4],
        ], color='#6B8E23', alpha=self.alpha, zorder=9)
        ax.add_patch(tail)

        # Wisdom aura (subtle)
        if frame % 3 == 0:
            aura = patches.Circle((x, y), s * 3,
                                  fill=False, edgecolor='#FFD700',
                                  linewidth=1, alpha=0.1, zorder=8)
            ax.add_patch(aura)

        self.render_speech(ax)


class Dragonfly(Character):
    """Spark the Brave Dragonfly - Eli's loyal friend"""

    def __init__(self, x: float, y: float, scale: float = 0.8):
        super().__init__(x, y, scale, "Spark")
        self.wing_phase = 0
        self.hover_offset = 0

    def render(self, ax, frame: int):
        if self.alpha <= 0:
            return

        s = self.scale * 30
        x = self.x
        # Hovering motion
        self.hover_offset = np.sin(frame * 0.15) * s * 0.3
        y = self.y + self.hover_offset

        # Wings (fast flapping)
        self.wing_phase = frame * 0.8
        wing_angle = np.sin(self.wing_phase) * 30

        for side in [-1, 1]:
            # Upper wings
            wing_points = [
                [x, y],
                [x + side * s * 1.5, y + s * 0.8 + wing_angle * side * 0.02],
                [x + side * s * 0.5, y + s * 0.3],
            ]
            wing = patches.Polygon(wing_points, color='#ADD8E6',
                                  alpha=self.alpha * 0.6, zorder=12)
            ax.add_patch(wing)

            # Lower wings
            wing_points2 = [
                [x, y - s * 0.2],
                [x + side * s * 1.2, y - s * 0.5 - wing_angle * side * 0.02],
                [x + side * s * 0.3, y - s * 0.3],
            ]
            wing2 = patches.Polygon(wing_points2, color='#87CEEB',
                                   alpha=self.alpha * 0.5, zorder=12)
            ax.add_patch(wing2)

        # Body segments
        body_colors = ['#00CED1', '#008B8B', '#006666']
        for i, color in enumerate(body_colors):
            seg_y = y - i * s * 0.4
            seg = patches.Ellipse((x, seg_y), s * 0.4, s * 0.5,
                                 color=color, alpha=self.alpha, zorder=13)
            ax.add_patch(seg)

        # Tail
        for i in range(4):
            tail_y = y - s * (1.2 + i * 0.3)
            tail_width = s * (0.25 - i * 0.04)
            tail = patches.Ellipse((x, tail_y), tail_width, s * 0.35,
                                  color='#005555', alpha=self.alpha, zorder=13)
            ax.add_patch(tail)

        # Head
        head = patches.Circle((x, y + s * 0.5), s * 0.35,
                             color='#00CED1', alpha=self.alpha, zorder=14)
        ax.add_patch(head)

        # Big compound eyes
        for side in [-1, 1]:
            eye = patches.Circle((x + side * s * 0.2, y + s * 0.55), s * 0.18,
                                color='#FF4500', alpha=self.alpha, zorder=15)
            ax.add_patch(eye)
            # Eye shine
            shine = patches.Circle((x + side * s * 0.22, y + s * 0.58), s * 0.05,
                                  color='white', alpha=self.alpha * 0.7, zorder=16)
            ax.add_patch(shine)

        self.render_speech(ax)


class ShadowSerpent(Character):
    """The Shadow Serpent - First Major Boss"""

    def __init__(self, x: float, y: float, scale: float = 2.0):
        super().__init__(x, y, scale, "Shadow Serpent")
        self.coil_phase = 0
        self.health = 100
        self.is_attacking = False

    def render(self, ax, frame: int):
        if self.alpha <= 0:
            return

        s = self.scale * 30
        x, y = self.x, self.y
        self.coil_phase = frame * 0.03

        # Menacing shadow aura
        for i in range(3):
            aura = patches.Circle((x, y), s * (4 + i),
                                  color='#1a0033', alpha=0.1 - i * 0.03, zorder=5)
            ax.add_patch(aura)

        # Serpent body (sinuous coils)
        num_segments = 15
        for i in range(num_segments):
            t = i / num_segments
            seg_x = x - s * 3 * t + np.sin(self.coil_phase + t * 4) * s * 0.8
            seg_y = y - s * t * 2 + np.cos(self.coil_phase + t * 3) * s * 0.5
            seg_size = s * (1.2 - t * 0.6)

            # Dark scales
            segment = patches.Circle((seg_x, seg_y), seg_size,
                                    color='#2d0a4e', alpha=self.alpha, zorder=10 + i)
            ax.add_patch(segment)

            # Purple highlights
            highlight = patches.Circle((seg_x, seg_y + seg_size * 0.3),
                                       seg_size * 0.6,
                                       color='#4a0080', alpha=self.alpha * 0.5,
                                       zorder=11 + i)
            ax.add_patch(highlight)

        # Head
        head_x = x + s * 0.5
        head_y = y + np.sin(frame * 0.05) * s * 0.3

        head = patches.Ellipse((head_x, head_y), s * 2, s * 1.5,
                              angle=15 * self.facing,
                              color='#2d0a4e', alpha=self.alpha, zorder=30)
        ax.add_patch(head)

        # Evil eyes
        for side in [-1, 1]:
            eye_x = head_x + s * 0.3 * self.facing
            eye_y = head_y + side * s * 0.3

            eye = patches.Ellipse((eye_x, eye_y), s * 0.4, s * 0.25,
                                 color='#FF0000', alpha=self.alpha, zorder=31)
            ax.add_patch(eye)

            # Slit pupil
            pupil = patches.Ellipse((eye_x, eye_y), s * 0.08, s * 0.2,
                                   color='black', alpha=self.alpha, zorder=32)
            ax.add_patch(pupil)

        # Fangs
        if self.is_attacking or self.emotion == Emotion.ANGRY:
            for side in [-1, 1]:
                fang_x = head_x + s * 0.8
                fang_points = [
                    [fang_x, head_y + side * s * 0.2],
                    [fang_x + s * 0.5, head_y + side * s * 0.1],
                    [fang_x + s * 0.1, head_y + side * s * 0.4 * side],
                ]
                fang = patches.Polygon(fang_points, color='white',
                                       alpha=self.alpha, zorder=33)
                ax.add_patch(fang)

        # Forked tongue
        tongue_flick = np.sin(frame * 0.3) * s * 0.2
        tongue_x = head_x + s * 1
        ax.plot([head_x + s * 0.8, tongue_x, tongue_x + s * 0.3],
               [head_y, head_y, head_y + tongue_flick],
               color='#8B0000', linewidth=3, alpha=self.alpha, zorder=34)
        ax.plot([tongue_x, tongue_x + s * 0.3],
               [head_y, head_y - tongue_flick],
               color='#8B0000', linewidth=3, alpha=self.alpha, zorder=34)


class StormHeron(Character):
    """The Storm Heron - Second Major Boss"""

    def __init__(self, x: float, y: float, scale: float = 2.5):
        super().__init__(x, y, scale, "Storm Heron")
        self.wing_phase = 0
        self.health = 100

    def render(self, ax, frame: int):
        if self.alpha <= 0:
            return

        s = self.scale * 25
        x, y = self.x, self.y
        self.wing_phase = frame * 0.08

        wing_flap = np.sin(self.wing_phase) * 0.3

        # Wings
        for side in [-1, 1]:
            wing_angle = 20 + wing_flap * 40 * side
            wing_span = s * 4

            # Main wing
            wing_points = [
                [x, y + s * 1.5],
                [x + side * wing_span, y + s * 2 + wing_flap * s * side],
                [x + side * wing_span * 0.8, y + s * 1],
                [x + side * s * 0.5, y + s * 0.5],
            ]
            wing = patches.Polygon(wing_points, color='#E8E8E8',
                                  alpha=self.alpha, zorder=10)
            ax.add_patch(wing)

            # Wing feathers
            for i in range(5):
                f_t = i / 5
                f_x = x + side * wing_span * (0.3 + f_t * 0.7)
                f_y = y + s * (1.5 + wing_flap * f_t * side)
                feather = patches.Ellipse((f_x, f_y), s * 0.3, s * 1,
                                         angle=side * (30 + wing_flap * 20),
                                         color='#D3D3D3', alpha=self.alpha, zorder=11)
                ax.add_patch(feather)

        # Body
        body = patches.Ellipse((x, y + s * 1), s * 1.5, s * 3,
                              color='#F5F5F5', alpha=self.alpha, zorder=15)
        ax.add_patch(body)

        # Neck
        neck_curve_x = [x + i * s * 0.15 * self.facing for i in range(8)]
        neck_curve_y = [y + s * (2.5 + i * 0.5 - (i/8)**2 * 2) for i in range(8)]
        for i in range(7):
            neck_seg = patches.Circle((neck_curve_x[i], neck_curve_y[i]),
                                      s * (0.4 - i * 0.03),
                                      color='#F0F0F0', alpha=self.alpha, zorder=16 + i)
            ax.add_patch(neck_seg)

        # Head
        head_x = neck_curve_x[-1] + s * 0.5 * self.facing
        head_y = neck_curve_y[-1]

        head = patches.Ellipse((head_x, head_y), s * 1.2, s * 0.8,
                              angle=15 * self.facing,
                              color='#F5F5F5', alpha=self.alpha, zorder=25)
        ax.add_patch(head)

        # Menacing eye
        eye_x = head_x + s * 0.2 * self.facing
        eye_y = head_y + s * 0.1
        eye = patches.Circle((eye_x, eye_y), s * 0.15,
                            color='#FF4500', alpha=self.alpha, zorder=26)
        ax.add_patch(eye)
        pupil = patches.Circle((eye_x + s * 0.03 * self.facing, eye_y), s * 0.06,
                              color='black', alpha=self.alpha, zorder=27)
        ax.add_patch(pupil)

        # Deadly beak
        beak_points = [
            [head_x + s * 0.5 * self.facing, head_y + s * 0.1],
            [head_x + s * 2.5 * self.facing, head_y],
            [head_x + s * 0.5 * self.facing, head_y - s * 0.2],
        ]
        beak = patches.Polygon(beak_points, color='#FFA500',
                              alpha=self.alpha, zorder=28)
        ax.add_patch(beak)

        # Legs
        leg_y = y - s * 0.5
        for side in [-1, 1]:
            # Upper leg
            ax.plot([x + side * s * 0.3, x + side * s * 0.5],
                   [leg_y, leg_y - s * 2],
                   color='#FFA500', linewidth=4, alpha=self.alpha, zorder=14)
            # Lower leg
            ax.plot([x + side * s * 0.5, x + side * s * 0.3],
                   [leg_y - s * 2, leg_y - s * 3],
                   color='#FFA500', linewidth=3, alpha=self.alpha, zorder=14)


class TheDarkOne(Character):
    """The Dark One - Ultimate Final Boss"""

    def __init__(self, x: float, y: float, scale: float = 3.0):
        super().__init__(x, y, scale, "The Dark One")
        self.health = 100
        self.phase = 1  # Boss phases 1-3
        self.aura_phase = 0

    def render(self, ax, frame: int):
        if self.alpha <= 0:
            return

        s = self.scale * 40
        x, y = self.x, self.y
        self.aura_phase = frame * 0.02

        # Massive dark aura
        for i in range(5):
            aura_size = s * (5 + i * 1.5) + np.sin(self.aura_phase + i) * s * 0.5
            aura = patches.Circle((x, y), aura_size,
                                  color='#0a0010',
                                  alpha=0.15 - i * 0.025, zorder=3)
            ax.add_patch(aura)

        # Swirling dark energy
        for i in range(12):
            angle = (i / 12) * 2 * np.pi + self.aura_phase
            dist = s * 3 + np.sin(self.aura_phase * 2 + i) * s
            ex = x + np.cos(angle) * dist
            ey = y + np.sin(angle) * dist
            energy = patches.Circle((ex, ey), s * 0.4,
                                    color='#4B0082', alpha=0.6, zorder=4)
            ax.add_patch(energy)

        # Main form - amorphous dark entity
        body = patches.Circle((x, y), s * 2 + np.sin(frame * 0.05) * s * 0.2,
                              color='#0D0D0D', alpha=self.alpha, zorder=10)
        ax.add_patch(body)

        # Inner glow
        inner = patches.Circle((x, y), s * 1.5,
                               color='#1a0033', alpha=self.alpha, zorder=11)
        ax.add_patch(inner)

        # Core
        core = patches.Circle((x, y), s * 0.8,
                              color='#4B0082', alpha=self.alpha, zorder=12)
        ax.add_patch(core)

        # Multiple evil eyes
        eye_positions = [
            (0, 0.5, 1.0),    # Center top (main eye)
            (-0.4, 0.2, 0.6), # Left
            (0.4, 0.2, 0.6),  # Right
            (-0.2, -0.3, 0.4),
            (0.2, -0.3, 0.4),
        ]

        for ex_off, ey_off, eye_scale in eye_positions:
            eye_x = x + ex_off * s
            eye_y = y + ey_off * s

            # Eye socket
            socket = patches.Circle((eye_x, eye_y), s * 0.3 * eye_scale,
                                   color='#8B0000', alpha=self.alpha, zorder=13)
            ax.add_patch(socket)

            # Glowing eye
            eye = patches.Circle((eye_x, eye_y), s * 0.2 * eye_scale,
                                 color='#FF0000', alpha=self.alpha, zorder=14)
            ax.add_patch(eye)

            # Pulsing pupil
            pulse = np.sin(frame * 0.1) * 0.3 + 0.7
            pupil = patches.Circle((eye_x, eye_y), s * 0.08 * eye_scale * pulse,
                                   color='#FFFF00', alpha=self.alpha, zorder=15)
            ax.add_patch(pupil)

        # Dark tendrils
        for i in range(8):
            angle = (i / 8) * 2 * np.pi + np.sin(frame * 0.02) * 0.5
            tendril_length = s * (2.5 + np.sin(frame * 0.05 + i) * 0.5)

            points = []
            for j in range(6):
                t = j / 5
                tx = x + np.cos(angle + np.sin(frame * 0.03 + j) * 0.3) * tendril_length * t
                ty = y + np.sin(angle + np.cos(frame * 0.04 + j) * 0.3) * tendril_length * t
                points.append([tx, ty])

            for j in range(len(points) - 1):
                width = 8 * (1 - j / len(points))
                ax.plot([points[j][0], points[j+1][0]],
                       [points[j][1], points[j+1][1]],
                       color='#1a0033', linewidth=width,
                       alpha=self.alpha * 0.8, zorder=9)


# ╔═══════════════════════════════════════════════════════════════════════════════╗
# ║                     HUUTERS STORYLINE CHARACTERS                              ║
# ╚═══════════════════════════════════════════════════════════════════════════════╝

class Waitress(Character):
    """Bella - The Last of the Starborn, Celestial Guardian of Huuters

    For ten thousand years she has waited, serving those who find their way
    to the sanctuary, knowing that one day THE ONE FORETOLD would arrive.
    Her amber-gold coloring is SOLIDIFIED STARLIGHT. Her blue eyes contain
    actual PIECES OF THE COSMOS. Her beauty is a FUNDAMENTAL FORCE OF THE UNIVERSE.

    When in celestial form, wings of pure light unfurl and her power becomes
    visible as golden flames, channeling the full might of the Seven Ley Lines."""

    def __init__(self, x: float, y: float, scale: float = 1.0):
        super().__init__(x, y, scale, "Bella")
        self.apron_sway = 0
        self.hair_flow = 0
        # Bella has a unique warm amber/honey coloring (SOLIDIFIED STARLIGHT)
        self.body_color = '#DAA520'  # Goldenrod - warm, inviting
        self.belly_color = '#FFE4B5'  # Moccasin - soft, gentle
        self.accent_color = '#8B4513'  # Saddle brown for details
        self.eye_color = '#4169E1'  # Royal blue - contains PIECES OF THE COSMOS
        # Celestial form properties
        self.celestial_form = False
        self.celestial_power = 0.0  # 0-1, how much power is being channeled
        self.wing_phase = 0

    def render(self, ax, frame: int):
        if self.alpha <= 0:
            return

        s = self.scale * 50
        x, y = self.x, self.y

        # Gentle breathing animation
        breath = np.sin(frame * 0.05 + 0.3) * 2

        # Graceful idle sway
        self.apron_sway = np.sin(frame * 0.04) * 3
        self.hair_flow = np.sin(frame * 0.03) * 2

        # Warm glow aura (she has an inner warmth)
        if self.emotion == Emotion.LOVE or self.emotion == Emotion.HAPPY:
            for i in range(3):
                glow = patches.Circle(
                    (x, y), s * (1.8 + i * 0.4),
                    color='#FFD700', alpha=0.08 - i * 0.02, zorder=8
                )
                ax.add_patch(glow)

        # Shadow
        shadow = patches.Ellipse(
            (x, y - s * 0.7), s * 2, s * 0.35,
            color='black', alpha=0.15 * self.alpha, zorder=8
        )
        ax.add_patch(shadow)

        # Back legs (elegant, slender)
        for side in [-1, 1]:
            leg = patches.Ellipse(
                (x + side * s * 0.6, y - s * 0.4),
                s * 0.5, s * 0.3,
                angle=side * 15,
                color=self.accent_color, alpha=self.alpha, zorder=10
            )
            ax.add_patch(leg)

        # Body (slightly more slender/elegant than regular frogs)
        body = patches.Ellipse(
            (x, y), s * 1.8, s * 1.3 + breath,
            color=self.body_color, alpha=self.alpha, zorder=11
        )
        ax.add_patch(body)

        # Belly
        belly = patches.Ellipse(
            (x, y - s * 0.1), s * 1.2, s * 0.8,
            color=self.belly_color, alpha=self.alpha, zorder=12
        )
        ax.add_patch(belly)

        # Apron (waitress uniform!) - white with slight sway
        apron_points = [
            [x - s * 0.5 + self.apron_sway * 0.3, y + s * 0.1],
            [x + s * 0.5 + self.apron_sway * 0.3, y + s * 0.1],
            [x + s * 0.6 + self.apron_sway * 0.5, y - s * 0.5],
            [x - s * 0.6 + self.apron_sway * 0.5, y - s * 0.5],
        ]
        apron = patches.Polygon(apron_points, color='#FFFAFA',
                               alpha=self.alpha * 0.95, zorder=13)
        ax.add_patch(apron)

        # Apron strings (tied in back, visible on sides)
        for side in [-1, 1]:
            string = patches.FancyBboxPatch(
                (x + side * s * 0.55, y + s * 0.05), s * 0.08, s * 0.3,
                boxstyle="round,pad=0.02", color='#FFFAFA',
                alpha=self.alpha * 0.9, zorder=12
            )
            ax.add_patch(string)

        # Front legs (delicate)
        for side in [-1, 1]:
            front_leg = patches.Ellipse(
                (x + side * s * 0.4, y - s * 0.35),
                s * 0.28, s * 0.2,
                angle=side * -10,
                color=self.accent_color, alpha=self.alpha, zorder=14
            )
            ax.add_patch(front_leg)

        # Elegant eyes (larger, more expressive)
        eye_y = y + s * 0.35

        for side in [-1, 1]:
            eye_x = x + side * s * 0.35

            # Eye bulge (feminine curve)
            bulge = patches.Circle(
                (eye_x, eye_y + s * 0.12), s * 0.32,
                color=self.body_color, alpha=self.alpha, zorder=15
            )
            ax.add_patch(bulge)

            is_blinking = self.blink_timer < 6

            if not is_blinking:
                # Large, beautiful eyes
                eye_white = patches.Ellipse(
                    (eye_x, eye_y), s * 0.28, s * 0.32,
                    color='white', alpha=self.alpha, zorder=16
                )
                ax.add_patch(eye_white)

                # Striking blue irises
                iris = patches.Circle(
                    (eye_x, eye_y), s * 0.16,
                    color=self.eye_color, alpha=self.alpha, zorder=17
                )
                ax.add_patch(iris)

                # Pupil
                pupil = patches.Circle(
                    (eye_x, eye_y), s * 0.08,
                    color='black', alpha=self.alpha, zorder=18
                )
                ax.add_patch(pupil)

                # Sparkle highlights (two for that anime/beautiful effect)
                highlight1 = patches.Circle(
                    (eye_x + s * 0.06, eye_y + s * 0.08), s * 0.05,
                    color='white', alpha=self.alpha * 0.9, zorder=19
                )
                ax.add_patch(highlight1)
                highlight2 = patches.Circle(
                    (eye_x - s * 0.04, eye_y - s * 0.04), s * 0.025,
                    color='white', alpha=self.alpha * 0.7, zorder=19
                )
                ax.add_patch(highlight2)

                # Long eyelashes
                for i in range(3):
                    lash_angle = (0.3 + i * 0.25) * side
                    lash_x = eye_x + side * s * 0.2
                    lash_y = eye_y + s * 0.15
                    ax.plot([lash_x, lash_x + np.cos(lash_angle + np.pi/2) * s * 0.12],
                           [lash_y, lash_y + np.sin(lash_angle + np.pi/2) * s * 0.12],
                           color='black', linewidth=2, alpha=self.alpha, zorder=20)
            else:
                # Gentle closed eyes (curved line)
                eye_arc = patches.Arc(
                    (eye_x, eye_y), s * 0.3, s * 0.15,
                    angle=0, theta1=200, theta2=340,
                    color=self.accent_color, linewidth=2.5, zorder=16
                )
                ax.add_patch(eye_arc)

        # Gentle smile
        if self.emotion in [Emotion.HAPPY, Emotion.LOVE]:
            mouth = patches.Arc(
                (x, y - s * 0.15), s * 0.6, s * 0.35,
                angle=0, theta1=210, theta2=330,
                color=self.accent_color, linewidth=2.5, zorder=20
            )
        else:
            mouth = patches.Arc(
                (x, y - s * 0.15), s * 0.4, s * 0.2,
                angle=0, theta1=210, theta2=330,
                color=self.accent_color, linewidth=2, zorder=20
            )
        ax.add_patch(mouth)

        # Little beauty mark
        beauty_mark = patches.Circle(
            (x + s * 0.25, y - s * 0.05), s * 0.03,
            color=self.accent_color, alpha=self.alpha, zorder=21
        )
        ax.add_patch(beauty_mark)

        # Love/emotional effects
        if self.emotion == Emotion.LOVE:
            for i in range(4):
                heart_y = y + s * (0.7 + (frame * 0.015 + i * 0.4) % 1.2)
                heart_x = x + s * 0.4 + np.sin(frame * 0.04 + i) * s * 0.25
                heart_alpha = 1 - ((frame * 0.015 + i * 0.4) % 1.2) / 1.2
                ax.text(heart_x, heart_y, '♥', fontsize=int(14 * self.scale),
                       color='#FF69B4', alpha=heart_alpha * self.alpha,
                       ha='center', va='center', zorder=25)

        # ═══════════════════════════════════════════════════════════════════
        # CELESTIAL FORM - When Bella reveals her true Starborn nature!
        # Wings of pure light unfurl, golden flames surround her,
        # and she channels the full might of the Seven Ley Lines.
        # ═══════════════════════════════════════════════════════════════════
        if self.celestial_form:
            self.wing_phase = frame * 0.08
            power = self.celestial_power

            # SEVEN LEY LINE AURA - concentric rings of different colors
            ley_colors = ['#FFD700', '#FF6B35', '#FF1493', '#9400D3', '#00FF7F', '#00BFFF', '#FFFFFF']
            for i, color in enumerate(ley_colors):
                ring_radius = s * (2.5 + i * 0.4 + np.sin(frame * 0.05 + i) * 0.2)
                ring = patches.Circle(
                    (x, y), ring_radius,
                    fill=False, edgecolor=color, linewidth=3 - i * 0.3,
                    alpha=power * 0.4 * (1 - i * 0.1), zorder=6
                )
                ax.add_patch(ring)

            # MASSIVE GOLDEN AURA - the power of ten thousand years
            for i in range(8):
                aura_size = s * (2 + i * 0.5 + np.sin(frame * 0.06 + i * 0.5) * 0.3)
                aura = patches.Circle(
                    (x, y), aura_size,
                    color='#FFD700', alpha=power * 0.12 * (1 - i * 0.1), zorder=5
                )
                ax.add_patch(aura)

            # WINGS OF PURE LIGHT - ethereal, flowing with cosmic energy
            for side in [-1, 1]:
                wing_spread = s * 2.5 * power
                wing_flap = np.sin(self.wing_phase) * 20

                # Main wing structure - multiple layered feathers of light
                for feather in range(7):
                    feather_angle = (side * 45 + wing_flap + feather * side * 12) * np.pi / 180
                    feather_length = wing_spread * (1 - feather * 0.08)
                    feather_width = s * 0.4 * (1 - feather * 0.05)

                    fx = x + side * s * 0.5 + np.cos(feather_angle) * feather_length * 0.5
                    fy = y + s * 0.3 + np.sin(feather_angle) * feather_length * 0.3

                    # Feather glow
                    feather_glow = patches.Ellipse(
                        (fx, fy), feather_length, feather_width,
                        angle=np.degrees(feather_angle) + 90,
                        color='#FFD700', alpha=power * 0.3 * (1 - feather * 0.04), zorder=7
                    )
                    ax.add_patch(feather_glow)

                    # Bright feather core
                    feather_core = patches.Ellipse(
                        (fx, fy), feather_length * 0.6, feather_width * 0.5,
                        angle=np.degrees(feather_angle) + 90,
                        color='#FFFFFF', alpha=power * 0.5 * (1 - feather * 0.06), zorder=8
                    )
                    ax.add_patch(feather_core)

            # COSMIC SPARKLES emanating from her form
            for i in range(20):
                angle = (frame * 0.03 + i * 0.314) % (2 * np.pi)
                dist = s * (1.5 + np.sin(frame * 0.05 + i) * 0.5 + i * 0.15)
                sparkle_x = x + np.cos(angle) * dist
                sparkle_y = y + np.sin(angle) * dist * 0.7
                sparkle_size = 15 + 10 * np.sin(frame * 0.1 + i)
                ax.scatter([sparkle_x], [sparkle_y], c='#FFD700',
                          s=sparkle_size * power, alpha=power * 0.8, zorder=30)

            # GOLDEN FLAMES at her feet - the power of the ley lines
            for i in range(12):
                flame_x = x + (i - 6) * s * 0.2 + np.sin(frame * 0.15 + i) * s * 0.1
                flame_height = s * (0.5 + 0.3 * np.sin(frame * 0.2 + i * 0.5))
                flame_y = y - s * 0.6 + flame_height * 0.3
                flame = patches.Polygon([
                    [flame_x - s * 0.1, y - s * 0.7],
                    [flame_x, y - s * 0.7 + flame_height],
                    [flame_x + s * 0.1, y - s * 0.7],
                ], color='#FFD700', alpha=power * 0.6, zorder=4)
                ax.add_patch(flame)

            # Eyes glow with cosmic power when in celestial form
            for side in [-1, 1]:
                eye_x = x + side * s * 0.35
                eye_y_cosmic = y + s * 0.35
                for i in range(3):
                    eye_glow = patches.Circle(
                        (eye_x, eye_y_cosmic), s * (0.2 + i * 0.1),
                        color='#00BFFF', alpha=power * 0.4 * (1 - i * 0.25), zorder=50
                    )
                    ax.add_patch(eye_glow)

        self.render_speech(ax)


class MajesticHorse(Character):
    """Thunder - The Celestial Steed, Guardian of Huuters

    An ETERNAL SPIRIT made flesh, the physical manifestation of COURAGE and LOYALTY.
    Created by the Starborn alongside Huuters, Thunder has guarded the sanctuary
    for millennia. His dark coat contains the VOID BETWEEN STARS. His mane flows
    with the WINDS OF ETERNITY. His hooves strike with the force of COLLIDING GALAXIES.

    Thunder can only be ridden by those whose hearts are ABSOLUTELY PURE and
    whose love is ABSOLUTELY TRUE. He has waited ten thousand years for riders
    worthy of his back. His tears become shooting stars.

    When in cosmic_form, Thunder reveals his true nature: starlight traces his
    form, his hooves leave trails of galaxies, and he can run between dimensions."""

    def __init__(self, x: float, y: float, scale: float = 2.0):
        super().__init__(x, y, scale, "Thunder")
        self.gallop_phase = 0
        self.mane_flow = 0
        self.is_galloping = False
        self.speed = 0
        self.body_color = '#2F1810'  # Dark brown - contains the VOID BETWEEN STARS
        self.mane_color = '#1a0a05'  # Flowing black mane - WINDS OF ETERNITY
        self.eye_color = '#8B4513'  # Warm brown eyes - ancient wisdom
        # Cosmic form properties
        self.cosmic_form = False
        self.cosmic_power = 0.0  # 0-1, how much celestial power is visible
        self.tears_of_joy = False  # When worthy riders mount him

    def render(self, ax, frame: int):
        if self.alpha <= 0:
            return

        s = self.scale * 40
        x, y = self.x, self.y

        # Galloping animation
        if self.is_galloping:
            self.gallop_phase = frame * 0.25
            gallop_y = np.sin(self.gallop_phase) * s * 0.3
            y += gallop_y
            self.mane_flow = np.sin(frame * 0.15) * 15 + self.speed * 2
        else:
            self.mane_flow = np.sin(frame * 0.03) * 5

        # Dramatic shadow
        shadow_stretch = 1 + (self.speed * 0.1 if self.is_galloping else 0)
        shadow = patches.Ellipse(
            (x, y - s * 1.2), s * 3 * shadow_stretch, s * 0.4,
            color='black', alpha=0.2 * self.alpha, zorder=5
        )
        ax.add_patch(shadow)

        # Legs (animated for galloping)
        leg_positions = [
            (-0.8, 'back_left'), (-0.4, 'front_left'),
            (0.4, 'front_right'), (0.8, 'back_right')
        ]
        for lx_offset, leg_name in leg_positions:
            leg_x = x + lx_offset * s

            if self.is_galloping:
                # Dynamic leg movement
                phase_offset = {'back_left': 0, 'front_left': np.pi/2,
                              'front_right': np.pi, 'back_right': 3*np.pi/2}
                leg_phase = self.gallop_phase + phase_offset[leg_name]
                leg_angle = np.sin(leg_phase) * 35
                leg_y_offset = abs(np.sin(leg_phase)) * s * 0.3
            else:
                leg_angle = 0
                leg_y_offset = 0

            # Upper leg
            upper_leg = patches.FancyBboxPatch(
                (leg_x - s * 0.1, y - s * 0.8 + leg_y_offset),
                s * 0.2, s * 0.6,
                boxstyle="round,pad=0.02",
                color=self.body_color, alpha=self.alpha, zorder=10
            )
            ax.add_patch(upper_leg)

            # Lower leg
            lower_leg_y = y - s * 1.3 + leg_y_offset + abs(leg_angle) * 0.01 * s
            lower_leg = patches.FancyBboxPatch(
                (leg_x - s * 0.08, lower_leg_y),
                s * 0.16, s * 0.5,
                boxstyle="round,pad=0.01",
                color=self.body_color, alpha=self.alpha, zorder=9
            )
            ax.add_patch(lower_leg)

            # Hoof
            hoof = patches.Ellipse(
                (leg_x, lower_leg_y - s * 0.05), s * 0.18, s * 0.1,
                color='#1a1a1a', alpha=self.alpha, zorder=11
            )
            ax.add_patch(hoof)

        # Main body (powerful, muscular)
        body = patches.Ellipse(
            (x, y), s * 2.5, s * 1.4,
            color=self.body_color, alpha=self.alpha, zorder=15
        )
        ax.add_patch(body)

        # Chest
        chest = patches.Ellipse(
            (x + s * 0.8, y + s * 0.1), s * 0.9, s * 1.0,
            color=self.body_color, alpha=self.alpha, zorder=16
        )
        ax.add_patch(chest)

        # Neck (arched, proud)
        neck_points = [
            [x + s * 1.0, y + s * 0.4],
            [x + s * 1.3, y + s * 1.2],
            [x + s * 1.5, y + s * 1.6],
            [x + s * 1.2, y + s * 1.7],
            [x + s * 0.9, y + s * 1.3],
            [x + s * 0.7, y + s * 0.6],
        ]
        neck = patches.Polygon(neck_points, color=self.body_color,
                              alpha=self.alpha, zorder=17)
        ax.add_patch(neck)

        # Head
        head_x = x + s * 1.4
        head_y = y + s * 1.8

        # Head shape
        head = patches.Ellipse(
            (head_x, head_y), s * 0.8, s * 0.5,
            angle=25, color=self.body_color, alpha=self.alpha, zorder=18
        )
        ax.add_patch(head)

        # Snout
        snout = patches.Ellipse(
            (head_x + s * 0.35, head_y - s * 0.1), s * 0.5, s * 0.35,
            angle=15, color=self.body_color, alpha=self.alpha, zorder=19
        )
        ax.add_patch(snout)

        # Nostrils
        for n_off in [0.1, 0.25]:
            nostril = patches.Circle(
                (head_x + s * 0.55, head_y - s * n_off), s * 0.05,
                color='#0a0505', alpha=self.alpha, zorder=20
            )
            ax.add_patch(nostril)

        # Eye (intense, noble)
        eye_x = head_x + s * 0.1
        eye_y = head_y + s * 0.1
        eye_white = patches.Ellipse(
            (eye_x, eye_y), s * 0.18, s * 0.14,
            color='white', alpha=self.alpha, zorder=20
        )
        ax.add_patch(eye_white)
        eye_iris = patches.Circle(
            (eye_x, eye_y), s * 0.07,
            color=self.eye_color, alpha=self.alpha, zorder=21
        )
        ax.add_patch(eye_iris)
        eye_pupil = patches.Circle(
            (eye_x, eye_y), s * 0.04,
            color='black', alpha=self.alpha, zorder=22
        )
        ax.add_patch(eye_pupil)

        # Ear
        ear_points = [
            [head_x - s * 0.1, head_y + s * 0.2],
            [head_x, head_y + s * 0.5],
            [head_x + s * 0.1, head_y + s * 0.25],
        ]
        ear = patches.Polygon(ear_points, color=self.body_color,
                             alpha=self.alpha, zorder=23)
        ax.add_patch(ear)

        # FLOWING MANE - dramatic and windswept
        mane_segments = 12
        for i in range(mane_segments):
            t = i / mane_segments
            mane_x = x + s * (0.9 + t * 0.5)
            mane_y = y + s * (0.6 + t * 1.0)

            # Mane flows in wind
            flow_offset = np.sin(frame * 0.1 + i * 0.5) * (s * 0.1 + self.mane_flow * 0.02)
            wind_offset = self.mane_flow * (1 - t) * 0.05 * s

            mane_strand = patches.Ellipse(
                (mane_x - wind_offset + flow_offset, mane_y),
                s * 0.15, s * (0.4 + (1 - t) * 0.3),
                angle=-30 - self.mane_flow * 0.5,
                color=self.mane_color, alpha=self.alpha * (0.9 - t * 0.2), zorder=24
            )
            ax.add_patch(mane_strand)

        # Tail (flowing dramatically)
        tail_base_x = x - s * 1.2
        tail_base_y = y + s * 0.3
        tail_segments = 8
        for i in range(tail_segments):
            t = i / tail_segments
            tail_x = tail_base_x - t * s * 0.8 - self.mane_flow * 0.03 * s
            tail_y = tail_base_y - t * s * 0.6 + np.sin(frame * 0.08 + i * 0.4) * s * 0.15
            tail_strand = patches.Ellipse(
                (tail_x, tail_y), s * 0.1, s * (0.5 - t * 0.2),
                angle=-45 - self.mane_flow * 0.3,
                color=self.mane_color, alpha=self.alpha * (1 - t * 0.3), zorder=14
            )
            ax.add_patch(tail_strand)

        # Speed lines when galloping fast
        if self.is_galloping and self.speed > 5:
            for i in range(5):
                line_y = y + s * (-0.5 + i * 0.3)
                line_x = x - s * 2
                line_len = s * (1 + self.speed * 0.1)
                ax.plot([line_x, line_x - line_len], [line_y, line_y],
                       color='white', linewidth=2, alpha=0.3 * (1 - i * 0.15), zorder=4)

        # Breath/snort particles when galloping
        if self.is_galloping and frame % 15 == 0:
            for _ in range(3):
                snort_x = head_x + s * 0.6 + np.random.randn() * s * 0.1
                snort_y = head_y - s * 0.1 + np.random.randn() * s * 0.05
                snort = patches.Circle(
                    (snort_x, snort_y), s * 0.05,
                    color='white', alpha=0.4, zorder=25
                )
                ax.add_patch(snort)

        # ═══════════════════════════════════════════════════════════════════
        # COSMIC FORM - Thunder's true celestial nature revealed!
        # His coat shows the VOID BETWEEN STARS, his hooves leave galaxy trails,
        # and he runs between dimensions themselves.
        # ═══════════════════════════════════════════════════════════════════
        if self.cosmic_form:
            power = self.cosmic_power

            # STARLIGHT AURA - the void between stars made visible
            for i in range(6):
                aura_size = s * (3.5 + i * 0.6 + np.sin(frame * 0.04 + i) * 0.3)
                aura = patches.Ellipse(
                    (x, y), aura_size * 1.5, aura_size,
                    color='#4B0082', alpha=power * 0.1 * (1 - i * 0.12), zorder=3
                )
                ax.add_patch(aura)

            # CONSTELLATION PATTERNS on his coat - stars within the void
            np.random.seed(42)  # Consistent constellation pattern
            for i in range(30):
                star_x = x + (np.random.rand() - 0.5) * s * 3
                star_y = y + (np.random.rand() - 0.5) * s * 2
                star_twinkle = 0.5 + 0.5 * np.sin(frame * 0.1 + i * 0.7)
                star_size = (5 + np.random.rand() * 10) * star_twinkle
                ax.scatter([star_x], [star_y], c='white',
                          s=star_size * power, alpha=power * 0.8, zorder=26)

            # GALAXY TRAIL from hooves when galloping
            if self.is_galloping:
                for leg_i in range(4):
                    trail_x = x + (leg_i - 1.5) * s * 0.5 - self.speed * s * 0.1
                    trail_y = y - s * 1.3
                    for t in range(8):
                        galaxy_x = trail_x - t * s * 0.15 - self.mane_flow * 0.02 * t
                        galaxy_y = trail_y + np.sin(frame * 0.1 + t * 0.5 + leg_i) * s * 0.1
                        galaxy_size = s * (0.15 - t * 0.015)
                        # Spiral galaxy effect
                        galaxy = patches.Circle(
                            (galaxy_x, galaxy_y), galaxy_size,
                            color='#9400D3', alpha=power * 0.5 * (1 - t * 0.1), zorder=2
                        )
                        ax.add_patch(galaxy)
                        # Galaxy core
                        core = patches.Circle(
                            (galaxy_x, galaxy_y), galaxy_size * 0.3,
                            color='#FFD700', alpha=power * 0.7 * (1 - t * 0.1), zorder=3
                        )
                        ax.add_patch(core)

            # MANE OF ETERNAL WINDS - flowing with cosmic energy
            for i in range(8):
                mane_trail_x = x + s * (0.8 - i * 0.1) - self.mane_flow * 0.04 * s
                mane_trail_y = y + s * (1.0 + i * 0.08)
                cosmic_strand = patches.Ellipse(
                    (mane_trail_x, mane_trail_y),
                    s * 0.3, s * (0.6 - i * 0.05),
                    angle=-30 - self.mane_flow * 0.5,
                    color='#00BFFF', alpha=power * 0.4 * (1 - i * 0.1), zorder=25
                )
                ax.add_patch(cosmic_strand)

            # EYES GLOW with ancient wisdom when cosmic
            eye_x_cosmic = head_x + s * 0.1
            eye_y_cosmic = head_y + s * 0.1
            for i in range(4):
                eye_cosmic_glow = patches.Circle(
                    (eye_x_cosmic, eye_y_cosmic), s * (0.15 + i * 0.08),
                    color='#FFD700', alpha=power * 0.4 * (1 - i * 0.2), zorder=50
                )
                ax.add_patch(eye_cosmic_glow)

            # DIMENSIONAL RIPPLES around hooves
            for leg_i in range(4):
                ripple_x = x + (leg_i - 1.5) * s * 0.5
                ripple_y = y - s * 1.4
                for r in range(3):
                    ripple = patches.Circle(
                        (ripple_x, ripple_y), s * (0.3 + r * 0.15 + (frame * 0.05) % 0.3),
                        fill=False, edgecolor='#9400D3', linewidth=2,
                        alpha=power * 0.3 * (1 - r * 0.25), zorder=1
                    )
                    ax.add_patch(ripple)

        # TEARS OF JOY - shooting stars when worthy riders mount
        if self.tears_of_joy:
            for i in range(5):
                tear_x = head_x + s * 0.15 + (frame * 3 + i * 30) % (WIDTH * 0.5)
                tear_y = head_y + s * 0.05 - (frame * 2 + i * 20) % (HEIGHT * 0.3)
                # Shooting star trail
                for t in range(6):
                    trail_x = tear_x - t * 15
                    trail_y = tear_y + t * 10
                    trail = patches.Circle(
                        (trail_x, trail_y), 3 - t * 0.4,
                        color='#FFD700', alpha=0.8 - t * 0.12, zorder=100
                    )
                    ax.add_patch(trail)


# ╔═══════════════════════════════════════════════════════════════════════════════╗
# ║                         ENVIRONMENT SYSTEM                                    ║
# ╚═══════════════════════════════════════════════════════════════════════════════╝

class Environment:
    """Base environment renderer"""

    def __init__(self):
        self.elements = []

    def render_background(self, ax, frame: int, lighting: LightingSystem):
        raise NotImplementedError

    def render_foreground(self, ax, frame: int):
        pass


class PondEnvironment(Environment):
    """Peaceful pond environment"""

    def __init__(self):
        super().__init__()
        # Generate lilypads
        self.lilypads = [
            {'x': WIDTH * 0.2, 'y': HEIGHT * 0.22, 'size': 100, 'rot': 0},
            {'x': WIDTH * 0.5, 'y': HEIGHT * 0.18, 'size': 120, 'rot': 15},
            {'x': WIDTH * 0.75, 'y': HEIGHT * 0.25, 'size': 90, 'rot': -10},
            {'x': WIDTH * 0.35, 'y': HEIGHT * 0.28, 'size': 80, 'rot': 25},
        ]
        # Reeds
        self.reeds = [50, 120, WIDTH - 80, WIDTH - 150]
        # Flies
        self.flies = [(np.random.uniform(100, WIDTH-100),
                      np.random.uniform(HEIGHT*0.4, HEIGHT*0.7),
                      np.random.uniform(0, 2*np.pi)) for _ in range(6)]

    def render_background(self, ax, frame: int, lighting: LightingSystem):
        # Sky
        sky_color = lighting.get_sky_color()
        ax.set_facecolor(sky_color)

        # Render celestial bodies
        lighting.render_celestial(ax, frame)

        # Distant hills (parallax layer)
        hill_color = lighting.apply_ambient_to_color('#228B22')
        for i, (hx, hw, hh) in enumerate([(0, 600, 150), (400, 800, 200), (900, 700, 180)]):
            hill = patches.Ellipse((hx + hw/2, HEIGHT * 0.4 + hh/2),
                                  hw, hh, color=hill_color, alpha=0.6, zorder=2)
            ax.add_patch(hill)

        # Pond water
        water_color = lighting.apply_ambient_to_color(Palette.WATER_SURFACE)
        pond = patches.Rectangle((0, 0), WIDTH, HEIGHT * 0.35,
                                 color=water_color, zorder=5)
        ax.add_patch(pond)

        # Water surface shimmer
        for i in range(8):
            wave_y = HEIGHT * 0.35 - i * 10
            phase = frame * 0.03 + i * 0.5
            wave_x = np.linspace(0, WIDTH, 50)
            wave_heights = wave_y + np.sin(wave_x * 0.01 + phase) * 3
            ax.fill_between(wave_x, wave_heights, wave_y - 5,
                           color=Palette.WATER_SHALLOW, alpha=0.15, zorder=6)

        # Lilypads
        for pad in self.lilypads:
            bob = np.sin(frame * 0.02 + pad['x'] * 0.01) * 2
            pad_color = lighting.apply_ambient_to_color(Palette.LILYPAD_NORMAL)

            lilypad = patches.Ellipse((pad['x'], pad['y'] + bob),
                                      pad['size'], pad['size'] * 0.6,
                                      angle=pad['rot'],
                                      color=pad_color, zorder=7)
            ax.add_patch(lilypad)

            # Lilypad notch
            notch = patches.Wedge((pad['x'], pad['y'] + bob),
                                  pad['size'] * 0.4, 170 + pad['rot'], 190 + pad['rot'],
                                  color=water_color, zorder=8)
            ax.add_patch(notch)

        # Cattails/reeds
        for rx in self.reeds:
            for h in range(7):
                ry = HEIGHT * 0.35 + h * 25
                sway = np.sin(frame * 0.02 + rx * 0.01 + h * 0.2) * 4
                reed = patches.Rectangle((rx + sway - 3, ry), 6, 22,
                                         color='#556B2F', zorder=6)
                ax.add_patch(reed)
            # Cattail head
            head_sway = np.sin(frame * 0.02 + rx * 0.01) * 4
            head = patches.Ellipse((rx + head_sway, HEIGHT * 0.35 + 190),
                                  14, 35, color='#8B4513', zorder=7)
            ax.add_patch(head)

        # Flies
        for i, (fx, fy, phase) in enumerate(self.flies):
            fly_x = fx + np.sin(frame * 0.08 + phase) * 25
            fly_y = fy + np.cos(frame * 0.1 + phase) * 15
            fly = patches.Circle((fly_x, fly_y), 4, color='#333333', zorder=20)
            ax.add_patch(fly)
            # Wings
            wing_spread = 2 + np.sin(frame * 0.5 + i) * 2
            ax.plot([fly_x - wing_spread, fly_x, fly_x + wing_spread],
                   [fly_y + 2, fly_y, fly_y + 2],
                   color='#666666', linewidth=1, alpha=0.6, zorder=20)


class DarkForestEnvironment(Environment):
    """Ominous dark forest"""

    def __init__(self):
        super().__init__()
        self.trees = [(np.random.uniform(0, WIDTH),
                      np.random.uniform(0.4, 0.9),
                      np.random.uniform(0.8, 1.5)) for _ in range(15)]

    def render_background(self, ax, frame: int, lighting: LightingSystem):
        ax.set_facecolor('#0a0a12')

        # Eerie fog layers
        for i in range(3):
            fog_y = HEIGHT * (0.3 + i * 0.2)
            fog = patches.Rectangle((0, fog_y - 50), WIDTH, 100,
                                    color='#1a1a2a', alpha=0.3, zorder=3 + i)
            ax.add_patch(fog)

        # Dead trees
        for tx, ty_mult, scale in self.trees:
            ty = HEIGHT * ty_mult
            trunk_h = 200 * scale
            trunk_w = 20 * scale

            # Trunk
            trunk = patches.Rectangle((tx - trunk_w/2, ty - trunk_h),
                                      trunk_w, trunk_h,
                                      color='#1a1a1a', zorder=5)
            ax.add_patch(trunk)

            # Gnarled branches
            for b in range(4):
                b_angle = np.pi/4 + b * np.pi/6 + np.sin(frame * 0.01 + tx) * 0.1
                b_len = 60 * scale
                bx = tx + np.cos(b_angle) * b_len * (1 if b % 2 == 0 else -1)
                by = ty - trunk_h * 0.7 + b * 20
                ax.plot([tx, bx], [by, by + 30],
                       color='#1a1a1a', linewidth=8 * scale, zorder=5)

        # Ground fog
        fog = patches.Rectangle((0, 0), WIDTH, HEIGHT * 0.2,
                                color='#2a2a3a', alpha=0.5, zorder=4)
        ax.add_patch(fog)


class BattleArenaEnvironment(Environment):
    """Epic battle arena"""

    def __init__(self):
        super().__init__()

    def render_background(self, ax, frame: int, lighting: LightingSystem):
        # Dramatic dark red sky
        ax.set_facecolor('#1a0a0a')

        # Ominous clouds
        for i in range(5):
            cx = (frame * 0.5 + i * 400) % (WIDTH + 400) - 200
            cy = HEIGHT * (0.7 + i * 0.05)
            cloud = patches.Ellipse((cx, cy), 300, 80,
                                   color='#2a1515', alpha=0.6, zorder=2)
            ax.add_patch(cloud)

        # Cracked ground
        ground = patches.Rectangle((0, 0), WIDTH, HEIGHT * 0.3,
                                   color='#2a1a10', zorder=5)
        ax.add_patch(ground)

        # Lava cracks
        for i in range(8):
            cx = WIDTH * (i + 0.5) / 8
            crack_glow = np.sin(frame * 0.05 + i) * 0.3 + 0.7
            crack = patches.Rectangle((cx - 5, 0), 10, HEIGHT * 0.25,
                                      color='#FF4500', alpha=crack_glow * 0.5, zorder=6)
            ax.add_patch(crack)

        # Dramatic pillars
        for i, px in enumerate([WIDTH * 0.1, WIDTH * 0.9]):
            pillar = patches.Rectangle((px - 30, 0), 60, HEIGHT * 0.6,
                                       color='#333333', zorder=7)
            ax.add_patch(pillar)
            # Fire on top
            fire_flicker = np.sin(frame * 0.1 + i) * 10
            fire = patches.Circle((px, HEIGHT * 0.6 + fire_flicker),
                                  40 + fire_flicker, color='#FF4500',
                                  alpha=0.8, zorder=8)
            ax.add_patch(fire)


# ╔═══════════════════════════════════════════════════════════════════════════════╗
# ║                        CINEMATIC TRANSITIONS                                  ║
# ╚═══════════════════════════════════════════════════════════════════════════════╝

class TransitionType(Enum):
    """Types of cinematic transitions"""
    FADE = auto()
    IRIS_IN = auto()
    IRIS_OUT = auto()
    DISSOLVE = auto()
    WIPE_LEFT = auto()
    WIPE_RIGHT = auto()
    RIPPLE_DISSOLVE = auto()
    FLASH = auto()


class TransitionManager:
    """Manages cinematic transitions between scenes"""

    def __init__(self):
        self.active = False
        self.transition_type = TransitionType.FADE
        self.progress = 0
        self.duration = 60
        self.center_x = WIDTH / 2
        self.center_y = HEIGHT / 2

    def start(self, transition_type: TransitionType, duration: int = 60,
              center_x: float = None, center_y: float = None):
        """Start a transition"""
        self.active = True
        self.transition_type = transition_type
        self.progress = 0
        self.duration = max(1, duration)  # Prevent division by zero
        self.center_x = center_x if center_x else WIDTH / 2
        self.center_y = center_y if center_y else HEIGHT / 2

    def update(self):
        """Update transition progress"""
        if self.active:
            self.progress += 1 / self.duration
            if self.progress >= 1:
                self.active = False
                self.progress = 0

    def render(self, ax, going_out: bool = True):
        """Render the transition effect"""
        if not self.active:
            return

        t = Easing.smooth_step(self.progress)
        if not going_out:
            t = 1 - t

        if self.transition_type == TransitionType.FADE:
            fade = patches.Rectangle((0, 0), WIDTH, HEIGHT,
                                     color='black', alpha=t, zorder=1000)
            ax.add_patch(fade)

        elif self.transition_type == TransitionType.IRIS_OUT:
            # Circular iris closing
            radius = (1 - t) * np.sqrt(WIDTH**2 + HEIGHT**2) / 2
            # Draw black corners
            for angle in range(360):
                theta = np.radians(angle)
                if radius > 10:
                    # Create a black ring outside the iris
                    outer = patches.Wedge((self.center_x, self.center_y),
                                          WIDTH * 2, angle, angle + 2,
                                          width=WIDTH * 2 - radius,
                                          color='black', zorder=1000)
                    ax.add_patch(outer)

        elif self.transition_type == TransitionType.IRIS_IN:
            # Circular iris opening
            radius = t * np.sqrt(WIDTH**2 + HEIGHT**2) / 2
            for angle in range(0, 360, 5):
                outer = patches.Wedge((self.center_x, self.center_y),
                                      WIDTH * 2, angle, angle + 6,
                                      width=max(0, WIDTH * 2 - radius),
                                      color='black', zorder=1000)
                ax.add_patch(outer)

        elif self.transition_type == TransitionType.WIPE_LEFT:
            wipe = patches.Rectangle((WIDTH * (1 - t), 0), WIDTH * t, HEIGHT,
                                     color='black', zorder=1000)
            ax.add_patch(wipe)

        elif self.transition_type == TransitionType.WIPE_RIGHT:
            wipe = patches.Rectangle((0, 0), WIDTH * t, HEIGHT,
                                     color='black', zorder=1000)
            ax.add_patch(wipe)

        elif self.transition_type == TransitionType.FLASH:
            flash = patches.Rectangle((0, 0), WIDTH, HEIGHT,
                                      color='white', alpha=1 - t, zorder=1000)
            ax.add_patch(flash)

        elif self.transition_type == TransitionType.RIPPLE_DISSOLVE:
            # Dreamy ripple effect for flashbacks
            for i in range(20):
                ring_t = (t + i * 0.05) % 1
                ring_radius = ring_t * np.sqrt(WIDTH**2 + HEIGHT**2)
                ring = patches.Circle((self.center_x, self.center_y), ring_radius,
                                      fill=False, edgecolor='white',
                                      linewidth=5, alpha=(1 - ring_t) * 0.5, zorder=999)
                ax.add_patch(ring)
            fade = patches.Rectangle((0, 0), WIDTH, HEIGHT,
                                     color='white', alpha=t * 0.7, zorder=998)
            ax.add_patch(fade)


# ╔═══════════════════════════════════════════════════════════════════════════════╗
# ║                         NARRATION SYSTEM                                      ║
# ╚═══════════════════════════════════════════════════════════════════════════════╝

class NarrationSystem:
    """Cinematic narration with typewriter effect"""

    def __init__(self):
        self.text = ""
        self.displayed_text = ""
        self.char_timer = 0
        self.char_delay = 3  # frames per character
        self.active = False
        self.fade_timer = 0
        self.position = 'bottom'  # 'bottom', 'top', 'center'
        self.style = 'dramatic'  # 'dramatic', 'whisper', 'thought'

    def show(self, text: str, position: str = 'bottom', style: str = 'dramatic', delay: int = 3):
        """Start showing narration"""
        self.text = text
        self.displayed_text = ""
        self.char_timer = 0
        self.char_delay = delay
        self.active = True
        self.fade_timer = 0
        self.position = position
        self.style = style

    def hide(self):
        """Start fading out"""
        self.fade_timer = 60

    def update(self):
        """Update narration state"""
        if self.active:
            self.char_timer += 1
            if self.char_timer >= self.char_delay:
                self.char_timer = 0
                if len(self.displayed_text) < len(self.text):
                    self.displayed_text = self.text[:len(self.displayed_text) + 1]

        if self.fade_timer > 0:
            self.fade_timer -= 1
            if self.fade_timer == 0:
                self.active = False

    def render(self, ax):
        """Render the narration"""
        if not self.active and self.fade_timer == 0:
            return

        alpha = 1.0
        if self.fade_timer > 0:
            alpha = self.fade_timer / 60

        # Position
        if self.position == 'bottom':
            y = HEIGHT * 0.12
        elif self.position == 'top':
            y = HEIGHT * 0.88
        else:
            y = HEIGHT * 0.5

        # Style settings
        if self.style == 'dramatic':
            fontsize = 28
            color = '#FFFFFF'
            bg_alpha = 0.5
        elif self.style == 'whisper':
            fontsize = 22
            color = '#AAAAAA'
            bg_alpha = 0.3
        else:  # thought
            fontsize = 24
            color = '#ADD8E6'
            bg_alpha = 0.4

        # Background bar
        bg = patches.Rectangle((0, y - 40), WIDTH, 80,
                               color='black', alpha=bg_alpha * alpha, zorder=800)
        ax.add_patch(bg)

        # Text with subtle glow
        ax.text(WIDTH/2, y + 3, self.displayed_text,
               fontsize=fontsize, ha='center', va='center',
               color='black', alpha=alpha * 0.3, zorder=801)
        ax.text(WIDTH/2, y, self.displayed_text,
               fontsize=fontsize, ha='center', va='center',
               color=color, alpha=alpha, zorder=802,
               fontfamily='serif', style='italic' if self.style == 'thought' else 'normal')


# ╔═══════════════════════════════════════════════════════════════════════════════╗
# ║                         SLOW MOTION SYSTEM                                    ║
# ╚═══════════════════════════════════════════════════════════════════════════════╝

class SlowMotionManager:
    """Manages dramatic slow-motion sequences"""

    def __init__(self):
        self.active = False
        self.time_scale = 1.0
        self.target_scale = 1.0
        self.vignette_intensity = 0
        self.desaturation = 0
        self.blur_lines = []

    def enter_slowmo(self, scale: float = 0.3, with_vignette: bool = True):
        """Enter slow motion"""
        self.active = True
        self.target_scale = scale
        if with_vignette:
            self.vignette_intensity = 0.6

    def exit_slowmo(self):
        """Exit slow motion"""
        self.target_scale = 1.0
        self.vignette_intensity = 0

    def update(self):
        """Update slow motion state"""
        self.time_scale = lerp(self.time_scale, self.target_scale, 0.1)
        if abs(self.time_scale - 1.0) < 0.05:
            self.active = False

    def get_frame_delta(self) -> float:
        """Get the time delta for this frame"""
        return self.time_scale

    def get_effective_frame(self, frame: int) -> int:
        """Get the effective frame number accounting for slow motion"""
        # In slow motion, we want to slow down the animation
        # For simplicity, just return the frame as-is (slow-mo is visual effect only)
        return frame

    def render_effects(self, ax):
        """Render slow-motion visual effects"""
        if self.vignette_intensity > 0.01:
            # Dark vignette around edges
            for i in range(10):
                t = i / 10
                alpha = self.vignette_intensity * t * 0.15
                edge = patches.Rectangle((-50, -50), WIDTH + 100, HEIGHT + 100,
                                         fill=False, edgecolor='black',
                                         linewidth=50 * (1 - t),
                                         alpha=alpha, zorder=900)
                ax.add_patch(edge)

            # Radial gradient vignette
            for ring in range(5):
                radius = WIDTH * (0.8 - ring * 0.15)
                vignette = patches.Circle((WIDTH/2, HEIGHT/2), radius,
                                         fill=False, edgecolor='black',
                                         linewidth=100, alpha=self.vignette_intensity * 0.1,
                                         zorder=899)
                ax.add_patch(vignette)


