class VillageEnvironment(Environment):
    """Peaceful frog village"""

    def __init__(self):
        super().__init__()
        self.houses = [
            {'x': WIDTH * 0.15, 'y': HEIGHT * 0.35, 'size': 1.0},
            {'x': WIDTH * 0.4, 'y': HEIGHT * 0.38, 'size': 1.2},
            {'x': WIDTH * 0.65, 'y': HEIGHT * 0.33, 'size': 0.9},
            {'x': WIDTH * 0.85, 'y': HEIGHT * 0.36, 'size': 1.1},
        ]

    def render_background(self, ax, frame: int, lighting: LightingSystem):
        sky_color = lighting.get_sky_color()
        ax.set_facecolor(sky_color)
        lighting.render_celestial(ax, frame)

        # Rolling hills
        for i, (hx, hy, scale) in enumerate([(0, 0.5, 1), (WIDTH*0.3, 0.48, 1.2), (WIDTH*0.6, 0.52, 0.9)]):
            hill_color = lighting.apply_ambient_to_color('#3CB371')
            hill = patches.Ellipse((hx + 400, HEIGHT * hy), 800 * scale, 200 * scale,
                                  color=hill_color, zorder=2 + i)
            ax.add_patch(hill)

        # Grass ground
        grass = patches.Rectangle((0, 0), WIDTH, HEIGHT * 0.35,
                                  color=lighting.apply_ambient_to_color('#228B22'), zorder=5)
        ax.add_patch(grass)

        # Village houses (mushroom-style homes)
        for house in self.houses:
            self._draw_mushroom_house(ax, house['x'], house['y'], house['size'], frame, lighting)

        # Path
        path_points = [(0, HEIGHT * 0.15), (WIDTH * 0.3, HEIGHT * 0.18),
                       (WIDTH * 0.6, HEIGHT * 0.14), (WIDTH, HEIGHT * 0.16)]
        path_x = [p[0] for p in path_points]
        path_y = [p[1] for p in path_points]
        ax.fill_between(path_x, [y - 15 for y in path_y], [y + 15 for y in path_y],
                       color='#D2B48C', zorder=6)

    def _draw_mushroom_house(self, ax, x, y, scale, frame, lighting):
        """Draw a cute mushroom-style frog house"""
        s = 60 * scale

        # Stem (door area)
        stem = patches.Rectangle((x - s * 0.4, y - s * 0.8), s * 0.8, s * 0.8,
                                 color=lighting.apply_ambient_to_color('#F5DEB3'), zorder=10)
        ax.add_patch(stem)

        # Door
        door = patches.Rectangle((x - s * 0.15, y - s * 0.7), s * 0.3, s * 0.5,
                                 color='#8B4513', zorder=11)
        ax.add_patch(door)

        # Cap (roof)
        cap = patches.Ellipse((x, y), s * 1.4, s * 0.8,
                             color=lighting.apply_ambient_to_color('#FF6347'), zorder=12)
        ax.add_patch(cap)

        # Spots on cap
        for i in range(4):
            spot_x = x + np.cos(i * 1.5) * s * 0.4
            spot_y = y + np.sin(i * 1.5) * s * 0.2 + s * 0.1
            spot = patches.Circle((spot_x, spot_y), s * 0.12,
                                  color='white', zorder=13)
            ax.add_patch(spot)

        # Window with warm light
        window = patches.Circle((x + s * 0.2, y - s * 0.3), s * 0.12,
                               color='#FFD700', alpha=0.8, zorder=11)
        ax.add_patch(window)


class MountainEnvironment(Environment):
    """Epic mountain peak"""

    def __init__(self):
        super().__init__()

    def render_background(self, ax, frame: int, lighting: LightingSystem):
        ax.set_facecolor('#1a1a2e')

        # Starfield for height
        np.random.seed(123)
        for _ in range(80):
            sx = np.random.uniform(0, WIDTH)
            sy = np.random.uniform(HEIGHT * 0.5, HEIGHT)
            twinkle = 0.5 + 0.5 * np.sin(frame * 0.05 + sx)
            ax.scatter([sx], [sy], c='white', s=twinkle * 15, alpha=twinkle * 0.7, zorder=1)

        # Distant mountains
        for i, (mx, mh, color) in enumerate([
            (WIDTH * 0.2, HEIGHT * 0.7, '#2d3436'),
            (WIDTH * 0.5, HEIGHT * 0.75, '#2d3436'),
            (WIDTH * 0.8, HEIGHT * 0.65, '#2d3436'),
        ]):
            mountain = patches.Polygon([
                [mx - 300, HEIGHT * 0.3],
                [mx, mh],
                [mx + 300, HEIGHT * 0.3],
            ], color=color, zorder=2 + i)
            ax.add_patch(mountain)
            # Snow cap
            snow = patches.Polygon([
                [mx - 50, mh - 50],
                [mx, mh],
                [mx + 50, mh - 50],
            ], color='white', zorder=3 + i)
            ax.add_patch(snow)

        # Main peak where hero stands
        peak = patches.Polygon([
            [WIDTH * 0.3, HEIGHT * 0.2],
            [WIDTH * 0.5, HEIGHT * 0.55],
            [WIDTH * 0.7, HEIGHT * 0.2],
        ], color='#4a4a5c', zorder=5)
        ax.add_patch(peak)

        # Snow on main peak
        snow_peak = patches.Polygon([
            [WIDTH * 0.4, HEIGHT * 0.4],
            [WIDTH * 0.5, HEIGHT * 0.55],
            [WIDTH * 0.6, HEIGHT * 0.4],
        ], color='#FFFAFA', zorder=6)
        ax.add_patch(snow_peak)

        # Clouds below
        for i in range(8):
            cx = (frame * 0.3 + i * 250) % (WIDTH + 400) - 200
            cy = HEIGHT * 0.2 + np.sin(i) * 30
            cloud = patches.Ellipse((cx, cy), 200, 50,
                                   color='white', alpha=0.4, zorder=4)
            ax.add_patch(cloud)


class CastleEnvironment(Environment):
    """Dark fortress castle"""

    def __init__(self):
        super().__init__()

    def render_background(self, ax, frame: int, lighting: LightingSystem):
        ax.set_facecolor('#0d0d15')

        # Ominous red sky
        sky_gradient = patches.Rectangle((0, HEIGHT * 0.4), WIDTH, HEIGHT * 0.6,
                                         color='#1a0a0a', zorder=1)
        ax.add_patch(sky_gradient)

        # Lightning flashes
        if frame % 180 < 5:
            flash = patches.Rectangle((0, 0), WIDTH, HEIGHT,
                                      color='white', alpha=0.3, zorder=500)
            ax.add_patch(flash)

        # Castle silhouette
        castle_parts = [
            # Main wall
            patches.Rectangle((WIDTH * 0.2, HEIGHT * 0.3), WIDTH * 0.6, HEIGHT * 0.2,
                             color='#1a1a1a', zorder=5),
            # Left tower
            patches.Rectangle((WIDTH * 0.15, HEIGHT * 0.3), WIDTH * 0.1, HEIGHT * 0.35,
                             color='#1a1a1a', zorder=6),
            # Right tower
            patches.Rectangle((WIDTH * 0.75, HEIGHT * 0.3), WIDTH * 0.1, HEIGHT * 0.35,
                             color='#1a1a1a', zorder=6),
            # Center tower (tallest)
            patches.Rectangle((WIDTH * 0.4, HEIGHT * 0.3), WIDTH * 0.2, HEIGHT * 0.5,
                             color='#1a1a1a', zorder=7),
        ]
        for part in castle_parts:
            ax.add_patch(part)

        # Tower tops (pointed)
        tower_tops = [
            (WIDTH * 0.2, HEIGHT * 0.65, 60),
            (WIDTH * 0.8, HEIGHT * 0.65, 60),
            (WIDTH * 0.5, HEIGHT * 0.8, 80),
        ]
        for tx, ty, size in tower_tops:
            top = patches.Polygon([
                [tx - size/2, ty],
                [tx, ty + size],
                [tx + size/2, ty],
            ], color='#1a1a1a', zorder=8)
            ax.add_patch(top)

        # Glowing windows (evil)
        windows = [(WIDTH * 0.5, HEIGHT * 0.6), (WIDTH * 0.2, HEIGHT * 0.5),
                   (WIDTH * 0.8, HEIGHT * 0.5), (WIDTH * 0.45, HEIGHT * 0.45),
                   (WIDTH * 0.55, HEIGHT * 0.45)]
        for wx, wy in windows:
            glow_intensity = 0.5 + 0.3 * np.sin(frame * 0.08 + wx)
            window = patches.Circle((wx, wy), 15,
                                   color='#FF4500', alpha=glow_intensity, zorder=10)
            ax.add_patch(window)

        # Ground
        ground = patches.Rectangle((0, 0), WIDTH, HEIGHT * 0.3,
                                   color='#0a0a0a', zorder=3)
        ax.add_patch(ground)


class HuutersRestaurantEnvironment(Environment):
    """The Mysterious Huuters - Sacred Sanctuary of the Starborn

    Built upon the convergence of SEVEN SACRED LEY LINES - the most powerful
    magical nexus in all existence. The very ground pulses with ancient power.
    The walls shimmer between dimensions. Time moves differently within
    its hallowed walls.

    The name "HUUTERS" is an ancient Starborn word meaning "WHERE SOULS INTERTWINE."
    Those who enter seeking comfort find it. Those who enter seeking love...
    find their DESTINY."""

    def __init__(self):
        super().__init__()
        # The SEVEN SACRED LEY LINES - colors of cosmic power
        self.ley_line_colors = [
            '#FFD700',  # Gold - Love
            '#FF6B35',  # Orange - Courage
            '#FF1493',  # Pink - Passion
            '#9400D3',  # Purple - Mystery
            '#00FF7F',  # Green - Life
            '#00BFFF',  # Cyan - Wisdom
            '#FFFFFF',  # White - Purity
        ]
        # Flickering candle positions
        self.candles = [
            {'x': WIDTH * 0.15, 'y': HEIGHT * 0.35, 'phase': 0},
            {'x': WIDTH * 0.3, 'y': HEIGHT * 0.4, 'phase': 1.2},
            {'x': WIDTH * 0.5, 'y': HEIGHT * 0.38, 'phase': 2.4},
            {'x': WIDTH * 0.7, 'y': HEIGHT * 0.42, 'phase': 0.8},
            {'x': WIDTH * 0.85, 'y': HEIGHT * 0.36, 'phase': 1.8},
        ]
        # Table positions
        self.tables = [
            {'x': WIDTH * 0.25, 'y': HEIGHT * 0.18},
            {'x': WIDTH * 0.5, 'y': HEIGHT * 0.15},
            {'x': WIDTH * 0.75, 'y': HEIGHT * 0.2},
        ]

    def render_background(self, ax, frame: int, lighting: LightingSystem):
        # Deep, mysterious purple-black background
        ax.set_facecolor('#0a0510')

        # ═══════════════════════════════════════════════════════════════════
        # THE SEVEN SACRED LEY LINES - pulsing beneath the sanctuary
        # The convergence point is directly beneath Huuters!
        # ═══════════════════════════════════════════════════════════════════
        convergence_x = WIDTH * 0.5
        convergence_y = HEIGHT * 0.15

        # Ley lines radiating from beneath the building
        for i, color in enumerate(self.ley_line_colors):
            # Each ley line comes from a different direction
            angle = (i / 7) * 2 * np.pi + frame * 0.002
            start_x = convergence_x + np.cos(angle) * WIDTH * 0.8
            start_y = convergence_y + np.sin(angle) * HEIGHT * 0.4

            # Pulsing energy along the ley line
            pulse = 0.5 + 0.5 * np.sin(frame * 0.03 + i * 0.9)

            # Draw the ley line as a glowing path
            for w in range(5):
                line_width = (6 - w) * 2
                line_alpha = 0.15 * pulse * (1 - w * 0.15)
                ax.plot([start_x, convergence_x], [start_y, convergence_y],
                       color=color, linewidth=line_width, alpha=line_alpha, zorder=0)

            # Energy nodes along the ley line
            for node in range(5):
                t = node / 5
                node_x = start_x + (convergence_x - start_x) * t
                node_y = start_y + (convergence_y - start_y) * t
                node_pulse = 0.5 + 0.5 * np.sin(frame * 0.05 + i + node * 0.5)
                node_size = 8 + 6 * node_pulse
                ax.scatter([node_x], [node_y], c=color,
                          s=node_size * pulse, alpha=0.6 * pulse, zorder=0)

        # Convergence point GLOWS with combined power
        for i in range(8):
            convergence_glow = patches.Circle(
                (convergence_x, convergence_y), 30 + i * 15 + np.sin(frame * 0.04) * 10,
                color='#FFD700', alpha=0.08 * (1 - i * 0.1), zorder=0
            )
            ax.add_patch(convergence_glow)

        # Dimensional shimmer effect - the walls between worlds are thin here
        for i in range(10):
            shimmer_x = np.random.uniform(WIDTH * 0.1, WIDTH * 0.9)
            shimmer_y = np.random.uniform(HEIGHT * 0.3, HEIGHT * 0.7)
            shimmer_phase = frame * 0.02 + i * 0.628
            if np.sin(shimmer_phase) > 0.8:  # Occasional dimensional flicker
                shimmer = patches.Circle(
                    (shimmer_x, shimmer_y), 20 + np.random.rand() * 30,
                    color=self.ley_line_colors[i % 7], alpha=0.15, zorder=1
                )
                ax.add_patch(shimmer)

        # Swirling mist in the background (ethereal)
        for i in range(15):
            mist_x = (frame * 0.2 + i * 150) % (WIDTH + 300) - 150
            mist_y = HEIGHT * (0.5 + np.sin(i * 0.5) * 0.2)
            mist_size = 200 + np.sin(frame * 0.01 + i) * 50
            mist = patches.Ellipse(
                (mist_x, mist_y), mist_size, mist_size * 0.4,
                color='#2a1a3a', alpha=0.15 + np.sin(frame * 0.02 + i) * 0.05, zorder=1
            )
            ax.add_patch(mist)

        # Starry/sparkly background (mysterious)
        np.random.seed(777)
        for i in range(40):
            star_x = np.random.uniform(0, WIDTH)
            star_y = np.random.uniform(HEIGHT * 0.4, HEIGHT)
            twinkle = 0.3 + 0.7 * (0.5 + 0.5 * np.sin(frame * 0.03 + i * 0.8))
            ax.scatter([star_x], [star_y], c='#FFD700', s=3 + twinkle * 5,
                      alpha=twinkle * 0.5, zorder=2)

        # The restaurant building - gothic/mysterious style
        # Main structure
        building = patches.FancyBboxPatch(
            (WIDTH * 0.1, HEIGHT * 0.25), WIDTH * 0.8, HEIGHT * 0.45,
            boxstyle="round,pad=0.02,rounding_size=20",
            facecolor='#1a0a15', edgecolor='#3a1a25', linewidth=3, zorder=5
        )
        ax.add_patch(building)

        # Roof - dramatic peaked style
        roof_points = [
            [WIDTH * 0.05, HEIGHT * 0.7],
            [WIDTH * 0.5, HEIGHT * 0.92],
            [WIDTH * 0.95, HEIGHT * 0.7],
        ]
        roof = patches.Polygon(roof_points, color='#2a0a18', zorder=6)
        ax.add_patch(roof)
        # Roof trim
        roof_trim = patches.Polygon(roof_points, fill=False,
                                   edgecolor='#8B4513', linewidth=4, zorder=7)
        ax.add_patch(roof_trim)

        # "HUUTERS" sign - glowing neon-style
        sign_x = WIDTH * 0.5
        sign_y = HEIGHT * 0.78
        # Sign backing
        sign_back = patches.FancyBboxPatch(
            (sign_x - 180, sign_y - 30), 360, 60,
            boxstyle="round,pad=0.02,rounding_size=10",
            facecolor='#0a0505', edgecolor='#FFD700', linewidth=2, zorder=10
        )
        ax.add_patch(sign_back)
        # Glowing text effect
        glow_pulse = 0.8 + 0.2 * np.sin(frame * 0.05)
        for i in range(3):
            ax.text(sign_x, sign_y, "HUUTERS",
                   fontsize=36, fontweight='bold', ha='center', va='center',
                   color='#FF6B35', alpha=(0.3 - i * 0.08) * glow_pulse, zorder=11)
        ax.text(sign_x, sign_y, "HUUTERS",
               fontsize=36, fontweight='bold', ha='center', va='center',
               color='#FFD700', alpha=glow_pulse, zorder=12)

        # Mysterious owl logo under the name
        owl_y = sign_y - 45
        # Owl eyes
        for ox in [-15, 15]:
            owl_eye = patches.Circle((sign_x + ox, owl_y), 8,
                                    color='#FF6B35', alpha=0.8, zorder=12)
            ax.add_patch(owl_eye)
            owl_pupil = patches.Circle((sign_x + ox, owl_y), 3,
                                      color='black', alpha=0.9, zorder=13)
            ax.add_patch(owl_pupil)

        # Windows with warm, inviting glow
        windows = [
            (WIDTH * 0.2, HEIGHT * 0.5, 80, 100),
            (WIDTH * 0.4, HEIGHT * 0.5, 80, 100),
            (WIDTH * 0.6, HEIGHT * 0.5, 80, 100),
            (WIDTH * 0.8, HEIGHT * 0.5, 80, 100),
        ]
        for wx, wy, ww, wh in windows:
            # Window frame
            frame_rect = patches.FancyBboxPatch(
                (wx - ww/2 - 5, wy - wh/2 - 5), ww + 10, wh + 10,
                boxstyle="round,pad=0.01,rounding_size=5",
                facecolor='#3a2020', edgecolor='#8B4513', linewidth=2, zorder=8
            )
            ax.add_patch(frame_rect)
            # Warm interior glow
            glow_intensity = 0.6 + 0.2 * np.sin(frame * 0.04 + wx * 0.01)
            window_glow = patches.Rectangle(
                (wx - ww/2, wy - wh/2), ww, wh,
                color='#FFE4B5', alpha=glow_intensity, zorder=9
            )
            ax.add_patch(window_glow)
            # Silhouettes inside (mysterious figures)
            if int(wx) % 200 < 100:
                silhouette = patches.Ellipse(
                    (wx + np.sin(frame * 0.02) * 5, wy - 10),
                    25, 40, color='#2a1510', alpha=0.6, zorder=10
                )
                ax.add_patch(silhouette)

        # Floor/ground - polished wooden look
        floor = patches.Rectangle((0, 0), WIDTH, HEIGHT * 0.25,
                                  color='#2a1a10', zorder=15)
        ax.add_patch(floor)
        # Floor shine
        for i in range(5):
            shine_x = WIDTH * (0.1 + i * 0.2)
            shine = patches.Ellipse(
                (shine_x, HEIGHT * 0.12), 100, 20,
                color='#4a3a20', alpha=0.3, zorder=16
            )
            ax.add_patch(shine)

        # Tables with white tablecloths
        for table in self.tables:
            # Table top
            table_top = patches.Ellipse(
                (table['x'], table['y']), 120, 40,
                color='#FFFAFA', alpha=0.9, zorder=20
            )
            ax.add_patch(table_top)
            # Table leg
            leg = patches.Rectangle(
                (table['x'] - 10, table['y'] - 50), 20, 50,
                color='#3a2a20', zorder=19
            )
            ax.add_patch(leg)

        # Flickering candles on tables
        for candle in self.candles:
            cx, cy = candle['x'], candle['y']
            flicker = np.sin(frame * 0.15 + candle['phase']) * 0.3

            # Candle body
            candle_body = patches.Rectangle(
                (cx - 4, cy - 20), 8, 25,
                color='#FFFAFA', zorder=25
            )
            ax.add_patch(candle_body)

            # Flame
            flame_height = 15 + flicker * 8
            flame = patches.Ellipse(
                (cx, cy + flame_height/2), 8 + flicker * 3, flame_height,
                color='#FF6B35', alpha=0.9, zorder=26
            )
            ax.add_patch(flame)
            # Inner flame
            inner_flame = patches.Ellipse(
                (cx, cy + flame_height/2 - 2), 4, flame_height * 0.6,
                color='#FFD700', alpha=0.8, zorder=27
            )
            ax.add_patch(inner_flame)

            # Candle glow
            for i in range(3):
                glow = patches.Circle(
                    (cx, cy + 5), 25 + i * 15 + flicker * 10,
                    color='#FF6B35', alpha=0.08 - i * 0.02, zorder=24
                )
                ax.add_patch(glow)

        # Mysterious door (slightly ajar, light spilling out)
        door_x = WIDTH * 0.5
        door = patches.FancyBboxPatch(
            (door_x - 40, HEIGHT * 0.25), 80, 130,
            boxstyle="round,pad=0.01,rounding_size=5",
            facecolor='#1a0a08', edgecolor='#8B4513', linewidth=3, zorder=17
        )
        ax.add_patch(door)
        # Door handle
        handle = patches.Circle((door_x + 25, HEIGHT * 0.32), 5,
                               color='#FFD700', zorder=18)
        ax.add_patch(handle)

        # Ambient particles (dust motes, magic sparkles)
        np.random.seed(int(frame * 0.1) % 1000)
        for i in range(10):
            px = np.random.uniform(WIDTH * 0.15, WIDTH * 0.85)
            py = np.random.uniform(HEIGHT * 0.1, HEIGHT * 0.6)
            sparkle_alpha = clamp(0.3 + 0.4 * np.sin(frame * 0.05 + i), 0, 1)
            ax.scatter([px], [py], c='#FFD700', s=5, alpha=sparkle_alpha, zorder=30)


# ╔═══════════════════════════════════════════════════════════════════════════════╗
# ║                              SCENE SYSTEM                                     ║
# ╚═══════════════════════════════════════════════════════════════════════════════╝

class Scene:
    """Base scene class"""
    def __init__(self, start: int, duration: int):
        self.start = start
        self.duration = max(1, duration)  # Prevent division by zero
        self.end = start + self.duration

    def progress(self, frame: int) -> float:
        return clamp((frame - self.start) / self.duration, 0, 1)

    def render(self, ax, frame: int, ctx: dict):
        raise NotImplementedError


class TitleScene(Scene):
    """Epic title screen with polished animations"""
    def render(self, ax, frame: int, ctx: dict):
        p = self.progress(frame)
        local = frame - self.start
        ax.set_facecolor('#000008')

        # Smooth twinkling stars with varied speeds
        np.random.seed(42)
        for i in range(150):
            # Each star has unique twinkle frequency for more organic feel
            twinkle_freq = 0.02 + (i % 10) * 0.005
            twinkle = 0.3 + 0.7 * (0.5 + 0.5 * np.sin(local * twinkle_freq + i * 0.7))
            star_x = np.random.rand() * WIDTH
            star_y = np.random.rand() * HEIGHT
            star_size = (5 + np.random.rand() * 15) * twinkle
            ax.scatter([star_x], [star_y], c='white', s=star_size, alpha=twinkle * 0.8, zorder=1)

        # Smooth shooting star occasionally
        if (local // 120) % 3 == 0:
            shoot_p = (local % 120) / 120
            if shoot_p < 0.3:
                shoot_eased = Easing.ease_out_cubic(shoot_p / 0.3)
                shoot_x = WIDTH * 0.8 - shoot_eased * WIDTH * 0.5
                shoot_y = HEIGHT * 0.9 - shoot_eased * HEIGHT * 0.3
                trail_len = 80
                for t in range(5):
                    trail_alpha = (1 - t * 0.2) * (1 - shoot_p / 0.3)
                    ax.plot([shoot_x + t * 15, shoot_x + t * 15 + trail_len],
                           [shoot_y - t * 5, shoot_y - t * 5 + trail_len * 0.4],
                           color='white', linewidth=3 - t * 0.5, alpha=trail_alpha * 0.6, zorder=2)

        # Title with smooth elastic entrance and glow
        if p > 0.08:
            t_prog = Easing.ease_out_elastic(min(1, (p - 0.08) / 0.35))
            t_prog_clamped = clamp(t_prog, 0, 1)  # Clamp for alpha safety
            title_y = HEIGHT * 0.62 + (1 - t_prog_clamped) * 50  # Slide in from above

            # Pulsing glow behind title
            glow_pulse = 0.8 + 0.2 * np.sin(local * 0.05)
            for i in range(4):
                glow_alpha = clamp((0.15 - i * 0.03) * t_prog_clamped * glow_pulse, 0, 1)
                ax.text(WIDTH/2, title_y, "ELI IS A FROG",
                       fontsize=int(72 * t_prog_clamped), fontweight='bold', ha='center', va='center',
                       color='#00FF00', alpha=glow_alpha, zorder=10)

            # Main title
            ax.text(WIDTH/2, title_y, "ELI IS A FROG",
                   fontsize=int(72 * t_prog_clamped), fontweight='bold', ha='center', va='center',
                   color='#90EE90', alpha=t_prog_clamped, zorder=11)

        # Smooth subtitle fade with slight rise
        if p > 0.32:
            s_prog = min(1, (p - 0.32) / 0.2)
            s_alpha = Easing.ease_out_cubic(s_prog)
            subtitle_y = HEIGHT * 0.48 + (1 - s_prog) * 20
            ax.text(WIDTH/2, subtitle_y, "THE LEGEND OF THE EMERALD GUARDIAN",
                   fontsize=26, ha='center', color='#FFD700', alpha=s_alpha, zorder=11)

        # Smooth dancing frogs with staggered entrance
        if p > 0.45:
            for i in range(5):
                frog_delay = i * 0.03
                frog_prog = max(0, min(1, (p - 0.45 - frog_delay) / 0.15))
                if frog_prog > 0:
                    frog_alpha = Easing.ease_out_cubic(frog_prog)
                    # Smooth bounce with easing
                    bounce_phase = local * 0.1 + i * 1.2
                    bounce = Easing.ease_out_cubic(abs(np.sin(bounce_phase))) * 30
                    frog = Frog(WIDTH * (0.18 + i * 0.16), HEIGHT * 0.2 + bounce, 0.55 + i * 0.02)
                    frog.emotion = Emotion.HAPPY
                    frog.alpha = frog_alpha
                    frog.render(ax, local)

        # Smooth particle emission in circular pattern
        if local % 8 == 0:
            emit_angle = local * 0.08
            emit_x = WIDTH/2 + np.cos(emit_angle) * 120
            emit_y = HEIGHT * 0.55 + np.sin(emit_angle) * 40
            ctx['particles'].emit_magic(emit_x, emit_y, 'gold', 0.5)

        # CINEMATIC EFFECTS - floating dust motes for magical atmosphere
        ctx['lighting'].render_dust_motes(ax, frame, 0.8)

        # Subtle film grain for cinematic quality
        ctx['lighting'].render_film_grain(ax, frame, 0.015)

        # Vignette for focus on title
        ctx['lighting'].render_vignette(ax, 0.35)

        # Bloom around the title for magical glow
        if p > 0.2:
            ctx['lighting'].render_bloom(ax, frame, WIDTH/2, HEIGHT * 0.6, 150,
                                        color='#00FF00', intensity=0.3)


class ChapterScene(Scene):
    """Chapter title card with smooth transitions"""
    def __init__(self, start: int, duration: int, num: int, title: str):
        super().__init__(start, duration)
        self.num, self.title = num, title

    def render(self, ax, frame: int, ctx: dict):
        p = self.progress(frame)
        local = frame - self.start
        ax.set_facecolor('#000000')

        # Smooth fade in/out with easing
        if p < 0.2:
            alpha = Easing.ease_out_cubic(p / 0.2)
        elif p > 0.8:
            alpha = Easing.ease_in_cubic((1 - p) / 0.2)
        else:
            alpha = 1.0

        # Subtle decorative lines that animate in
        line_prog = min(1, p * 3) if p < 0.3 else 1
        line_width = WIDTH * 0.25 * Easing.ease_out_cubic(line_prog)
        if line_width > 10:
            ax.plot([WIDTH/2 - line_width, WIDTH/2 + line_width],
                   [HEIGHT * 0.58, HEIGHT * 0.58],
                   color='#FFD700', linewidth=1, alpha=alpha * 0.5, zorder=9)
            ax.plot([WIDTH/2 - line_width, WIDTH/2 + line_width],
                   [HEIGHT * 0.38, HEIGHT * 0.38],
                   color='#FFD700', linewidth=1, alpha=alpha * 0.5, zorder=9)

        # Chapter number with subtle pulse
        pulse = 1.0 + 0.02 * np.sin(local * 0.08)
        ax.text(WIDTH/2, HEIGHT * 0.55, f"— CHAPTER {self.num} —",
               fontsize=int(24 * pulse), ha='center', color='#FFD700', alpha=alpha * 0.9, zorder=10)

        # Title slides in smoothly
        title_offset = (1 - min(1, p * 4)) * 30 if p < 0.25 else 0
        ax.text(WIDTH/2, HEIGHT * 0.43 - title_offset, self.title.upper(),
               fontsize=48, fontweight='bold', ha='center', color='white', alpha=alpha, zorder=10)


class StoryScene(Scene):
    """General story scene with environment and characters"""
    def __init__(self, start: int, duration: int, env_type: str = 'pond', time: str = 'day'):
        super().__init__(start, duration)
        # Select environment based on type
        env_map = {
            'pond': PondEnvironment,
            'forest': DarkForestEnvironment,
            'battle': BattleArenaEnvironment,
            'village': VillageEnvironment,
            'mountain': MountainEnvironment,
            'castle': CastleEnvironment,
        }
        self.env = env_map.get(env_type, PondEnvironment)()
        self.time = time
        self.chars = []
        self.events = []

    def add_char(self, char: Character): self.chars.append(char)
    def add_event(self, start_pct: float, callback): self.events.append((start_pct, callback))

    def render(self, ax, frame: int, ctx: dict):
        p = self.progress(frame)
        local = frame - self.start

        # Set time of day
        times = {'dawn': TimeOfDay.DAWN, 'day': TimeOfDay.NOON, 'sunset': TimeOfDay.SUNSET,
                'night': TimeOfDay.NIGHT, 'dark': TimeOfDay.MIDNIGHT, 'storm': TimeOfDay.DUSK}
        ctx['lighting'].set_time(times.get(self.time, TimeOfDay.NOON), immediate=True)

        # Set weather for storm
        if self.time == 'storm':
            ctx['weather'].set_weather(WeatherType.STORM, 1.0, immediate=True)

        self.env.render_background(ax, frame, ctx['lighting'])

        for start_pct, cb in self.events:
            if p >= start_pct:
                cb(p, local, ctx, self.chars)

        for c in self.chars:
            c.update(local)
            c.render(ax, local)


