class HuutersDiscoveryScene(Scene):
    """Eli discovers the mysterious Huuters restaurant emerging from the mist

    CINEMATIC EFFECTS: Film grain, vignette, god rays, dust motes, bloom"""

    def __init__(self, start: int, duration: int):
        super().__init__(start, duration)
        self.env = HuutersRestaurantEnvironment()

    def render(self, ax, frame: int, ctx: dict):
        p = self.progress(frame)
        local = frame - self.start

        # Phase 1: Wandering in the mist (0-30%)
        if p < 0.3:
            mist_p = p / 0.3
            ax.set_facecolor('#0a0510')

            # Heavy mist - layered for depth
            for i in range(25):
                mist_x = (local * 0.3 + i * 100) % (WIDTH + 200) - 100
                mist_y = HEIGHT * (0.2 + (i % 5) * 0.15)
                mist_size = 250 + np.sin(local * 0.01 + i) * 80
                mist = patches.Ellipse(
                    (mist_x, mist_y), mist_size, mist_size * 0.3,
                    color='#3a2a4a', alpha=0.4 - mist_p * 0.2, zorder=5
                )
                ax.add_patch(mist)

            # Additional fog layer for atmosphere
            for i in range(10):
                fog_x = (local * 0.15 + i * 200) % (WIDTH + 300) - 150
                fog_y = HEIGHT * 0.15 + (i % 3) * 0.08 * HEIGHT
                fog = patches.Ellipse(
                    (fog_x, fog_y), 300, 80,
                    color='#2a1a2a', alpha=0.25, zorder=3
                )
                ax.add_patch(fog)

            # Eli walking, looking lost - separated from allies after Storm Heron
            eli_x = WIDTH * (0.2 + mist_p * 0.15)
            eli = Frog(eli_x, HEIGHT * 0.2, 1.0)
            eli.emotion = Emotion.SAD
            eli.render(ax, local)

            # Subtle dust motes in the mist
            ctx['lighting'].render_dust_motes(ax, frame, 0.4)

            # NARRATIVE CONTEXT - Why is Eli here?
            # After the Storm Heron battle, he was separated from his allies
            # Something draws him through the mist - the prophecy's pull
            if mist_p < 0.3:
                context_alpha = 1 - mist_p / 0.3
                ax.text(WIDTH/2, HEIGHT * 0.88,
                       "After the battle with the Storm Heron...",
                       fontsize=22, ha='center', color='#7777aa',
                       alpha=context_alpha, style='italic', zorder=100)
                ax.text(WIDTH/2, HEIGHT * 0.82,
                       "Eli was separated from his allies.",
                       fontsize=20, ha='center', color='#6666aa',
                       alpha=context_alpha, style='italic', zorder=100)

            # Main emotional text
            if mist_p > 0.3 and mist_p < 0.7:
                text_alpha = (mist_p - 0.3) / 0.4
                ax.text(WIDTH/2, HEIGHT * 0.8, "Lost... alone...",
                       fontsize=28, ha='center', color='#9999aa',
                       alpha=text_alpha, style='italic', zorder=100)

            # The prophecy's pull
            if mist_p > 0.6:
                pull_alpha = (mist_p - 0.6) / 0.4
                ax.text(WIDTH/2, HEIGHT * 0.72,
                       "But something called to him through the mist...",
                       fontsize=22, ha='center', color='#aaaacc',
                       alpha=pull_alpha, style='italic', zorder=100)
                ax.text(WIDTH/2, HEIGHT * 0.66,
                       '"Where seven ley lines meet..."',
                       fontsize=20, ha='center', color='#FFD700',
                       alpha=pull_alpha * 0.7, style='italic', zorder=100)

            # Heavy vignette for isolated feeling
            ctx['lighting'].render_vignette(ax, 0.5 + mist_p * 0.2, color='#0a0510')

        # Phase 2: Lights appear in the mist (30-50%)
        elif p < 0.5:
            reveal_p = (p - 0.3) / 0.2
            ax.set_facecolor('#0a0510')

            # Mist clearing slightly
            for i in range(15):
                mist_x = (local * 0.2 + i * 150) % (WIDTH + 300) - 150
                mist_y = HEIGHT * (0.3 + (i % 4) * 0.12)
                mist = patches.Ellipse(
                    (mist_x, mist_y), 200, 60,
                    color='#2a1a3a', alpha=0.3 - reveal_p * 0.15, zorder=2
                )
                ax.add_patch(mist)

            # Mysterious lights appearing with bloom effect
            for i in range(5):
                light_x = WIDTH * (0.3 + i * 0.1)
                light_y = HEIGHT * (0.4 + np.sin(i) * 0.1)
                glow_alpha = reveal_p * 0.5 * (0.5 + 0.5 * np.sin(local * 0.05 + i))

                # Multiple layers for bloom effect
                for j in range(3):
                    light = patches.Circle(
                        (light_x, light_y), (30 + reveal_p * 20) * (1 + j * 0.5),
                        color='#FFD700', alpha=glow_alpha * (0.5 - j * 0.15), zorder=10 - j
                    )
                    ax.add_patch(light)

            # Eli looking up with hope
            eli = Frog(WIDTH * 0.35, HEIGHT * 0.2, 1.0)
            eli.emotion = Emotion.SHOCKED
            eli.render(ax, local)

            # Emit gold particles toward lights
            if local % 8 == 0:
                ctx['particles'].emit_magic(
                    WIDTH * 0.5, HEIGHT * 0.3, 'gold', 0.8)

            # "What is that...?" text
            ax.text(WIDTH/2, HEIGHT * 0.75, "What... is that light?",
                   fontsize=26, ha='center', color='#FFD700',
                   alpha=reveal_p, style='italic', zorder=100)

            # Lightening vignette as hope appears
            ctx['lighting'].render_vignette(ax, 0.5 - reveal_p * 0.2, color='#0a0510')
            ctx['lighting'].render_dust_motes(ax, frame, 0.5)

        # Phase 3: Huuters fully revealed (50-100%)
        else:
            full_p = (p - 0.5) / 0.5

            # Render the full Huuters environment with fade-in
            self.env.render_background(ax, frame, ctx['lighting'])

            # Add a mystical glow overlay that fades
            if full_p < 0.3:
                glow_alpha = (0.3 - full_p) / 0.3 * 0.4
                ax.add_patch(patches.Rectangle((0, 0), WIDTH, HEIGHT,
                            color='#FFD700', alpha=glow_alpha, zorder=100))
                # Camera slight shake for impact of reveal
                ctx['camera'].shake(8 * (0.3 - full_p) / 0.3, 0.92)

            # Eli approaching, amazed
            eli_x = WIDTH * (0.35 + full_p * 0.1)
            eli = Frog(eli_x, HEIGHT * 0.18, 1.0)
            eli.emotion = Emotion.SHOCKED if full_p < 0.5 else Emotion.HAPPY
            eli.render(ax, local)

            # "HUUTERS" text emphasis with glow
            if full_p > 0.3 and full_p < 0.7:
                text_alpha = 1 - abs(full_p - 0.5) * 4
                # Glow layers
                for i in range(3):
                    ax.text(WIDTH/2, HEIGHT * 0.5, "HUUTERS",
                           fontsize=60 + i * 4, fontweight='bold', ha='center', va='center',
                           color='#FF6B35', alpha=text_alpha * (0.15 - i * 0.04), zorder=149)
                ax.text(WIDTH/2, HEIGHT * 0.5, "HUUTERS",
                       fontsize=60, fontweight='bold', ha='center', va='center',
                       color='#FFD700', alpha=text_alpha * 0.5, zorder=150)

            # Sparkle particles - more frequent
            if local % 4 == 0:
                ctx['particles'].emit_magic(
                    np.random.uniform(WIDTH * 0.2, WIDTH * 0.8),
                    np.random.uniform(HEIGHT * 0.4, HEIGHT * 0.8), 'gold', 0.7)

            # God rays from the restaurant
            if full_p > 0.4:
                ray_intensity = (full_p - 0.4) / 0.6 * 0.3
                ctx['lighting'].render_god_rays(ax, frame, WIDTH * 0.5, HEIGHT * 0.78,
                                               color='#FFD700', intensity=ray_intensity, num_rays=5)

            # Bloom effect on the sign
            if full_p > 0.5:
                bloom_intensity = (full_p - 0.5) / 0.5
                ctx['lighting'].render_bloom(ax, frame, WIDTH * 0.5, HEIGHT * 0.78, 100,
                                            color='#FF6B35', intensity=bloom_intensity * 0.3)

            # Atmospheric dust
            ctx['lighting'].render_dust_motes(ax, frame, 0.6 + full_p * 0.3)

            # Warm vignette for inviting feeling
            ctx['lighting'].render_vignette(ax, 0.25, color='#1a0a10')

        # Film grain for cinematic quality throughout
        ctx['lighting'].render_film_grain(ax, frame, 0.018)


class HuutersMeetingScene(Scene):
    """Eli meets Bella the waitress - love at first sight

    CINEMATIC EFFECTS: Slow motion, lens flares, god rays, bloom, particles,
    romantic vignette, film grain - matching the quality of WeddingScene"""

    def __init__(self, start: int, duration: int):
        super().__init__(start, duration)
        self.env = HuutersRestaurantEnvironment()

    def render(self, ax, frame: int, ctx: dict):
        p = self.progress(frame)
        local = frame - self.start

        # Always render the Huuters background
        self.env.render_background(ax, frame, ctx['lighting'])

        # Phase 1: Eli enters, looks around (0-25%)
        if p < 0.25:
            enter_p = p / 0.25

            eli_x = WIDTH * (0.1 + enter_p * 0.25)
            eli = Frog(eli_x, HEIGHT * 0.18, 1.0)
            eli.emotion = Emotion.NEUTRAL
            eli.render(ax, local)

            # Atmospheric dust motes
            ctx['lighting'].render_dust_motes(ax, frame, 0.5)

            # Looking around text with subtle fade
            if enter_p > 0.5:
                text_alpha = (enter_p - 0.5) * 2
                # Text glow
                ax.text(WIDTH/2, HEIGHT * 0.7, "Welcome to Huuters...",
                       fontsize=26, ha='center', color='#FF6B35',
                       alpha=text_alpha * 0.3, style='italic', zorder=99)
                ax.text(WIDTH/2, HEIGHT * 0.7, "Welcome to Huuters...",
                       fontsize=24, ha='center', color='#FFD700',
                       alpha=text_alpha, style='italic', zorder=100)

            # Warm vignette
            ctx['lighting'].render_vignette(ax, 0.3, color='#1a0a10')

        # Phase 2: Bella appears - TIME SLOWS (25-50%)
        elif p < 0.5:
            meet_p = (p - 0.25) / 0.25

            # SLOW MOTION EFFECT for dramatic entrance!
            if meet_p < 0.3:
                ctx['slowmo'].enter_slowmo(0.3, with_vignette=True)
            elif meet_p > 0.7:
                ctx['slowmo'].exit_slowmo()

            # Eli frozen in awe
            eli = Frog(WIDTH * 0.35, HEIGHT * 0.18, 1.0)
            eli.emotion = Emotion.SHOCKED if meet_p < 0.5 else Emotion.LOVE
            eli.render(ax, local)

            # Bella entrance - dramatic slow motion effect
            bella_x = WIDTH * (0.8 - meet_p * 0.2)
            bella = Waitress(bella_x, HEIGHT * 0.2, 1.1)
            bella.emotion = Emotion.HAPPY

            # Bella RADIANT glow effect - multiple layers for bloom
            for i in range(6):
                glow = patches.Circle(
                    (bella_x, HEIGHT * 0.2), 60 + i * 25,
                    color='#FFD700', alpha=0.12 - i * 0.018, zorder=30 - i
                )
                ax.add_patch(glow)

            bella.render(ax, local)

            # God rays behind Bella (she's angelic)
            ctx['lighting'].render_god_rays(ax, frame, bella_x, HEIGHT * 0.5,
                                           color='#FFD700', intensity=0.25 * meet_p, num_rays=5)

            # Lens flare as she enters
            if meet_p > 0.3 and meet_p < 0.8:
                flare_intensity = 1 - abs(meet_p - 0.55) * 4
                ctx['lighting'].render_lens_flare(ax, frame, bella_x, HEIGHT * 0.3,
                                                 intensity=flare_intensity * 0.4)

            # Magical sparkles around Bella
            for i in range(8):
                sparkle_x = bella_x + np.sin(local * 0.1 + i) * 70
                sparkle_y = HEIGHT * 0.2 + np.cos(local * 0.08 + i * 0.8) * 60 + i * 8
                sparkle_size = 15 + np.sin(local * 0.2 + i) * 8
                ax.scatter([sparkle_x], [sparkle_y], c='#FFD700',
                          s=sparkle_size, alpha=0.8, zorder=40)

            # Emit magic particles around Bella
            if local % 6 == 0:
                ctx['particles'].emit_magic(bella_x + np.random.randn() * 40,
                                           HEIGHT * 0.25 + np.random.randn() * 30, 'gold', 0.8)

            # Heart connection visualization with glow
            if meet_p > 0.6:
                heart_alpha = (meet_p - 0.6) / 0.4
                heart_x = (WIDTH * 0.35 + bella_x) / 2
                heart_y = HEIGHT * 0.4

                # Heart glow
                for i in range(3):
                    ax.text(heart_x, heart_y, '♥', fontsize=45 + i * 5,
                           color='#FF69B4', alpha=heart_alpha * (0.2 - i * 0.05),
                           ha='center', zorder=49)
                ax.text(heart_x, heart_y, '♥', fontsize=40,
                       color='#FF69B4', alpha=heart_alpha, ha='center', zorder=50)

            # Bloom effect on Bella
            ctx['lighting'].render_bloom(ax, frame, bella_x, HEIGHT * 0.2, 80,
                                        color='#FFD700', intensity=meet_p * 0.3)

            # Romantic pink vignette
            ctx['lighting'].render_vignette(ax, 0.25, color='#2a0a15')

        # Phase 3: They talk, connection builds (50-80%)
        elif p < 0.8:
            talk_p = (p - 0.5) / 0.3

            # Both characters, closer together
            eli = Frog(WIDTH * 0.4, HEIGHT * 0.18, 1.0)
            eli.emotion = Emotion.LOVE
            eli.render(ax, local)

            bella = Waitress(WIDTH * 0.6, HEIGHT * 0.2, 1.0)
            bella.emotion = Emotion.LOVE
            bella.render(ax, local)

            # Warm glow between them
            center_x = WIDTH * 0.5
            for i in range(4):
                glow = patches.Ellipse(
                    (center_x, HEIGHT * 0.19), 180 + i * 35, 100 + i * 20,
                    color='#FFD700', alpha=0.06 - i * 0.012, zorder=15
                )
                ax.add_patch(glow)

            # Conversation bubbles with better styling
            conversations = [
                (0.0, "I'm Bella...", WIDTH * 0.6),
                (0.25, "I'm... Eli.", WIDTH * 0.4),
                (0.5, "You look lost, hero.", WIDTH * 0.6),
                (0.75, "I was... until now.", WIDTH * 0.4),
            ]
            for start_t, text, tx in conversations:
                if talk_p >= start_t and talk_p < start_t + 0.25:
                    bubble_alpha = 1 - abs(talk_p - start_t - 0.125) * 8
                    bubble_alpha = max(0, min(1, bubble_alpha))
                    # Glow behind text
                    ax.text(tx, HEIGHT * 0.4, text,
                           fontsize=20, ha='center', color='#FFD700',
                           alpha=bubble_alpha * 0.3, zorder=99)
                    ax.text(tx, HEIGHT * 0.4, text,
                           fontsize=18, ha='center', color='white',
                           alpha=bubble_alpha, zorder=100,
                           bbox=dict(boxstyle='round,pad=0.5', facecolor='#2a1a2a',
                                   edgecolor='#FFD700', linewidth=2, alpha=bubble_alpha * 0.85))

            # Floating hearts - more of them
            for i in range(6):
                heart_y = HEIGHT * (0.35 + (local * 0.01 + i * 0.25) % 0.35)
                heart_x = WIDTH * (0.42 + np.sin(local * 0.03 + i) * 0.1)
                heart_alpha = 1 - ((local * 0.01 + i * 0.25) % 0.35) / 0.35
                ax.text(heart_x, heart_y, '♥', fontsize=18 + i % 3 * 5,
                       color='#FF69B4', alpha=heart_alpha * talk_p * 0.8, ha='center', zorder=45)

            # Magic particles between them
            if local % 10 == 0:
                ctx['particles'].emit_magic(center_x + np.random.randn() * 50,
                                           HEIGHT * 0.25, 'pink', 0.6)

            # Atmospheric dust
            ctx['lighting'].render_dust_motes(ax, frame, 0.6)

            # Soft vignette
            ctx['lighting'].render_vignette(ax, 0.2, color='#1a0510')

        # Phase 4: Deep connection moment (80-100%)
        else:
            bond_p = (p - 0.8) / 0.2

            # Closer together, intimate moment
            eli = Frog(WIDTH * 0.45, HEIGHT * 0.18, 1.0)
            eli.emotion = Emotion.LOVE
            eli.render(ax, local)

            bella = Waitress(WIDTH * 0.55, HEIGHT * 0.2, 1.0)
            bella.emotion = Emotion.LOVE
            bella.render(ax, local)

            # Strong warm glow between them
            center_x = WIDTH * 0.5
            for i in range(6):
                glow = patches.Ellipse(
                    (center_x, HEIGHT * 0.19), 140 + i * 30, 90 + i * 18,
                    color='#FFD700', alpha=0.1 - i * 0.015, zorder=25
                )
                ax.add_patch(glow)

            # God rays from above (blessing their union)
            ctx['lighting'].render_god_rays(ax, frame, center_x, HEIGHT * 0.8,
                                           color='#FFD700', intensity=bond_p * 0.35, num_rays=4)

            # Bloom on the couple
            ctx['lighting'].render_bloom(ax, frame, center_x, HEIGHT * 0.2, 100,
                                        color='#FFD700', intensity=bond_p * 0.4)

            # Emotional text with dramatic presentation
            if bond_p > 0.3:
                text_alpha = (bond_p - 0.3) / 0.7
                # Text glow layers
                for i in range(2):
                    ax.text(WIDTH/2, HEIGHT * 0.75,
                           "In that moment, everything changed...",
                           fontsize=28 + i * 2, ha='center', color='#FF6B35',
                           alpha=text_alpha * (0.2 - i * 0.08), style='italic', zorder=99)
                ax.text(WIDTH/2, HEIGHT * 0.75,
                       "In that moment, everything changed...",
                       fontsize=26, ha='center', color='#FFD700',
                       alpha=text_alpha, style='italic', zorder=100)

            # Many floating hearts cascade
            for i in range(10):
                heart_y = HEIGHT * (0.28 + (local * 0.006 + i * 0.12) % 0.45)
                heart_x = WIDTH * (0.32 + i * 0.04 + np.sin(local * 0.04 + i) * 0.03)
                heart_alpha = 1 - ((local * 0.006 + i * 0.12) % 0.45) / 0.45
                heart_size = 14 + (i % 4) * 4
                ax.text(heart_x, heart_y, '♥', fontsize=heart_size,
                       color='#FF69B4', alpha=heart_alpha * bond_p * 0.9, ha='center', zorder=45)

            # Lens flare for romantic atmosphere
            ctx['lighting'].render_lens_flare(ax, frame, center_x, HEIGHT * 0.25,
                                             intensity=bond_p * 0.35)

            # Constant magic particles
            if local % 5 == 0:
                ctx['particles'].emit_magic(center_x + np.random.randn() * 60,
                                           HEIGHT * 0.3 + np.random.randn() * 40, 'pink', 0.8)

            # Romantic pink vignette
            ctx['lighting'].render_vignette(ax, 0.2, color='#2a0515')

        # Film grain for cinematic quality throughout
        ctx['lighting'].render_film_grain(ax, frame, 0.015)


class DangerousHorseRideScene(Scene):
    """THE CLIMACTIC DANGEROUS HORSE RIDE - INSANELY DRAMATIC AND STRESSFUL!
    Eli and Bella escape the Dark One's forces on a majestic horse through
    treacherous terrain, dimensional rifts, and near-death experiences.

    CINEMATIC EFFECTS: Film grain, chromatic aberration, bloom, slow motion,
    god rays, lens flares, particles, dynamic vignette - matching BattleScene quality."""

    def __init__(self, start: int, duration: int):
        super().__init__(start, duration)
        self.horse = MajesticHorse(WIDTH * 0.5, HEIGHT * 0.35, 1.8)
        self.shake_intensity = 0
        self.danger_level = 0
        self.slowmo_triggered = False
        self.leap_slowmo_triggered = False

    def render(self, ax, frame: int, ctx: dict):
        p = self.progress(frame)
        local = frame - self.start

        # Reset horse cosmic form at start of each frame - only enable in specific phases
        self.horse.cosmic_form = False
        self.horse.cosmic_power = 0.0
        self.horse.tears_of_joy = False

        # CONSTANT INTENSE CAMERA SHAKE - increases with danger
        self.danger_level = 0.3 + p * 0.7
        self.shake_intensity = 5 + self.danger_level * 20
        ctx['camera'].shake(self.shake_intensity, 0.85)

        # Phase 1: Dark forces attack Huuters! (0-15%)
        if p < 0.15:
            attack_p = p / 0.15
            ax.set_facecolor('#0a0510')

            # Huuters in background, under attack
            # Flames and destruction
            for i in range(15):
                fire_x = np.random.uniform(WIDTH * 0.1, WIDTH * 0.9)
                fire_y = np.random.uniform(HEIGHT * 0.3, HEIGHT * 0.7)
                fire_size = 30 + np.random.rand() * 50 + attack_p * 40
                fire = patches.Circle(
                    (fire_x + np.sin(local * 0.1 + i) * 10, fire_y),
                    fire_size, color='#FF4500',
                    alpha=0.4 + attack_p * 0.3, zorder=10
                )
                ax.add_patch(fire)

            # Shadow creatures approaching
            for i in range(8):
                cx = WIDTH * (0.7 + i * 0.04) + attack_p * WIDTH * 0.1
                cy = HEIGHT * (0.2 + (i % 3) * 0.1)
                creature = patches.Ellipse(
                    (cx, cy), 60, 40, color='#2d0a4e', alpha=0.8, zorder=15
                )
                ax.add_patch(creature)
                # Evil eyes
                ax.scatter([cx - 10, cx + 10], [cy + 5, cy + 5],
                          c='#FF0000', s=20, alpha=0.9, zorder=16)

            # Eli and Bella panicking
            eli = Frog(WIDTH * 0.3, HEIGHT * 0.18, 1.0)
            eli.emotion = Emotion.SCARED
            eli.render(ax, local)

            bella = Waitress(WIDTH * 0.4, HEIGHT * 0.2, 1.0)
            bella.emotion = Emotion.SCARED
            bella.render(ax, local)

            # "RUN!" text
            if attack_p > 0.5:
                ax.text(WIDTH/2, HEIGHT * 0.8, "WE HAVE TO RUN!",
                       fontsize=36, fontweight='bold', ha='center',
                       color='#FF0000', alpha=(attack_p - 0.5) * 2, zorder=100)

            # Lightning flash with chromatic aberration
            if local % 30 < 2:
                ax.add_patch(patches.Rectangle((0, 0), WIDTH, HEIGHT,
                            color='white', alpha=0.6, zorder=500))
                ctx['lighting'].render_chromatic_aberration(ax, frame, 0.6)
                ctx['camera'].shake(25, 0.85)

            # Fire particles and dark energy from attackers
            if local % 4 == 0:
                ctx['particles'].emit_explosion(
                    np.random.uniform(WIDTH * 0.3, WIDTH * 0.8),
                    np.random.uniform(HEIGHT * 0.3, HEIGHT * 0.6), 1.5)
            if local % 6 == 0:
                ctx['particles'].emit_dark_energy(WIDTH * 0.8, HEIGHT * 0.3, 1.0)

            # God rays from fire (ominous orange)
            ctx['lighting'].render_god_rays(ax, frame, WIDTH * 0.5, HEIGHT * 0.5,
                                           color='#FF4500', intensity=attack_p * 0.3, num_rays=5)

            # Heavy danger vignette
            ctx['lighting'].render_vignette(ax, 0.6 + attack_p * 0.2, color='#1a0000')

        # Phase 2: The horse appears! They mount and RIDE! (15-25%)
        elif p < 0.25:
            mount_p = (p - 0.15) / 0.1

            # Dark, stormy background
            ax.set_facecolor('#0a0812')

            # Storm clouds
            for i in range(8):
                cloud_x = (local * 2 + i * 300) % (WIDTH + 400) - 200
                cloud = patches.Ellipse(
                    (cloud_x, HEIGHT * (0.7 + i * 0.03)), 300, 80,
                    color='#1a1025', alpha=0.7, zorder=2
                )
                ax.add_patch(cloud)

            # The horse dramatically appears - THUNDER, THE CELESTIAL STEED!
            horse_x = WIDTH * (0.7 - mount_p * 0.2)
            self.horse.x = horse_x
            self.horse.y = HEIGHT * 0.35
            self.horse.is_galloping = False
            # Thunder WEEPS with joy - he has waited 10,000 years for worthy riders!
            if mount_p > 0.5:
                self.horse.tears_of_joy = True
            self.horse.render(ax, local)

            # Eli and Bella mounting
            rider_x = horse_x - 20
            eli = Frog(rider_x, HEIGHT * 0.5 + mount_p * 0.1 * HEIGHT, 0.9)
            eli.emotion = Emotion.DETERMINED
            eli.render(ax, local)

            bella = Waitress(rider_x + 40, HEIGHT * 0.48 + mount_p * 0.12 * HEIGHT, 0.85)
            bella.emotion = Emotion.SCARED
            bella.render(ax, local)

            # "HOLD ON!" text
            ax.text(WIDTH/2, HEIGHT * 0.85, "HOLD ON TIGHT!",
                   fontsize=32, fontweight='bold', ha='center',
                   color='#FFD700', alpha=mount_p, zorder=100)

            # Dramatic horse entrance with particles
            if local % 3 == 0:
                ctx['particles'].emit_magic(horse_x, HEIGHT * 0.35, 'gold', 0.8)

            # Lens flare as horse appears heroically
            ctx['lighting'].render_lens_flare(ax, frame, horse_x, HEIGHT * 0.5,
                                             intensity=mount_p * 0.4)

            # Bloom around the majestic horse
            ctx['lighting'].render_bloom(ax, frame, horse_x, HEIGHT * 0.4, 120,
                                        color='#8B4513', intensity=mount_p * 0.3)

            # Stormy vignette
            ctx['lighting'].render_vignette(ax, 0.5, color='#0a0812')

        # Phase 3: THE RIDE BEGINS - Galloping through darkness (25-45%)
        elif p < 0.45:
            ride_p = (p - 0.25) / 0.2

            # Rushing dark landscape
            ax.set_facecolor('#050308')

            # Speed lines
            speed = 10 + ride_p * 20
            for i in range(30):
                line_y = HEIGHT * (i / 30)
                line_x = WIDTH - (local * speed + i * 50) % (WIDTH * 1.5)
                line_len = 100 + speed * 10
                ax.plot([line_x, line_x + line_len], [line_y, line_y],
                       color='white', linewidth=2, alpha=0.4, zorder=3)

            # Dark trees rushing past
            for i in range(10):
                tree_x = WIDTH - (local * 8 + i * 200) % (WIDTH + 200)
                tree_height = HEIGHT * (0.3 + (i % 3) * 0.15)
                tree = patches.Polygon([
                    [tree_x, HEIGHT * 0.1],
                    [tree_x - 30, tree_height],
                    [tree_x + 30, tree_height],
                ], color='#0a0a0a', zorder=5)
                ax.add_patch(tree)

            # THE HORSE GALLOPING
            self.horse.x = WIDTH * 0.4
            self.horse.y = HEIGHT * 0.3
            self.horse.is_galloping = True
            self.horse.speed = speed
            self.horse.render(ax, local)

            # Eli and Bella on the horse
            eli = Frog(WIDTH * 0.38, HEIGHT * 0.52, 0.8)
            eli.emotion = Emotion.DETERMINED
            eli.render(ax, local)

            bella = Waitress(WIDTH * 0.44, HEIGHT * 0.5, 0.75)
            bella.emotion = Emotion.SCARED
            bella.render(ax, local)

            # Pursuers behind!
            for i in range(5):
                px = WIDTH * 0.8 + i * 50 + np.sin(local * 0.2 + i) * 30
                py = HEIGHT * (0.2 + i * 0.08)
                pursuer = patches.Ellipse((px, py), 50, 35,
                                         color='#2d0a4e', alpha=0.8, zorder=8)
                ax.add_patch(pursuer)
                ax.scatter([px - 8, px + 8], [py + 5, py + 5],
                          c='#FF0000', s=15, zorder=9)

            # Hoofbeat sound visualization with dust particles
            if local % 8 < 2:
                for i in range(3):
                    hoof = patches.Circle(
                        (WIDTH * 0.35 - i * 30, HEIGHT * 0.15), 10 - i * 2,
                        color='#8B4513', alpha=0.4 - i * 0.1, zorder=4
                    )
                    ax.add_patch(hoof)
                # Emit dust particles on hoofbeat
                ctx['particles'].emit_magic(WIDTH * 0.35, HEIGHT * 0.15, 'brown', 0.5)

            # Dark energy from pursuers
            if local % 10 == 0:
                ctx['particles'].emit_dark_energy(WIDTH * 0.85, HEIGHT * 0.3, 0.8)

            # Speed-induced chromatic aberration (mild)
            ctx['lighting'].render_chromatic_aberration(ax, frame, 0.15 + ride_p * 0.1)

            # Danger vignette that pulses with speed
            pulse = 0.5 + 0.1 * np.sin(local * 0.2)
            ctx['lighting'].render_vignette(ax, 0.4 + ride_p * 0.2 * pulse, color='#050308')

            # God rays from pursuers' eyes (ominous red)
            ctx['lighting'].render_god_rays(ax, frame, WIDTH * 0.85, HEIGHT * 0.3,
                                           color='#FF0000', intensity=0.15, num_rays=3)

        # Phase 4: DIMENSIONAL RIFT - Reality tears apart! (45-60%)
        elif p < 0.6:
            rift_p = (p - 0.45) / 0.15

            # INSANE visual - reality shattering
            ax.set_facecolor('#000010')

            # Dimensional tears
            for i in range(12):
                tear_x = WIDTH * (0.2 + (i % 4) * 0.2)
                tear_y = HEIGHT * (0.3 + (i // 4) * 0.25)
                tear_angle = np.sin(local * 0.05 + i) * 45

                # Rift opening
                rift_size = 50 + rift_p * 100 + np.sin(local * 0.1 + i) * 20
                rift = patches.Ellipse(
                    (tear_x + np.sin(local * 0.03 + i) * 30, tear_y),
                    rift_size, rift_size * 0.3, angle=tear_angle,
                    color='#4B0082', alpha=0.6 + rift_p * 0.3, zorder=5
                )
                ax.add_patch(rift)

                # Electric energy from rifts
                for j in range(3):
                    bolt_end_x = tear_x + np.random.randn() * 80
                    bolt_end_y = tear_y + np.random.randn() * 50
                    ax.plot([tear_x, bolt_end_x], [tear_y, bolt_end_y],
                           color='#9400D3', linewidth=2, alpha=0.7, zorder=6)

            # Strange geometry floating
            for i in range(8):
                geo_x = (local * 5 + i * 250) % WIDTH
                geo_y = HEIGHT * (0.4 + np.sin(local * 0.02 + i) * 0.2)
                shape = patches.RegularPolygon(
                    (geo_x, geo_y), 3 + i % 4, 30 + i * 5,
                    orientation=local * 0.02 + i,
                    color='#8B008B', alpha=0.4, zorder=7
                )
                ax.add_patch(shape)

            # Horse and riders barreling through
            # THUNDER ACTIVATES COSMIC FORM - he can run between dimensions!
            self.horse.x = WIDTH * 0.45
            self.horse.y = HEIGHT * 0.32 + np.sin(local * 0.2) * 20
            self.horse.is_galloping = True
            self.horse.speed = 25
            self.horse.cosmic_form = True  # THUNDER REVEALS HIS TRUE NATURE!
            self.horse.cosmic_power = rift_p  # Power increases as rifts intensify
            self.horse.render(ax, local)

            eli = Frog(WIDTH * 0.43, HEIGHT * 0.54 + np.sin(local * 0.2) * 20, 0.8)
            eli.emotion = Emotion.SHOCKED
            eli.render(ax, local)

            bella = Waitress(WIDTH * 0.49, HEIGHT * 0.52 + np.sin(local * 0.2) * 20, 0.75)
            bella.emotion = Emotion.SCARED
            bella.render(ax, local)

            # Thunder speaks to their minds (ancient wisdom)
            if rift_p > 0.3 and rift_p < 0.6:
                thunder_text_alpha = (rift_p - 0.3) / 0.3
                ax.text(WIDTH/2, HEIGHT * 0.92, '"HOLD FAST! I HAVE RUN BETWEEN WORLDS BEFORE!"',
                       fontsize=22, ha='center', color='#00BFFF',
                       alpha=thunder_text_alpha, style='italic', zorder=100)

            # "WHAT'S HAPPENING?!" text
            ax.text(WIDTH/2, HEIGHT * 0.85, "REALITY IS TEARING APART!",
                   fontsize=30, fontweight='bold', ha='center',
                   color='#9400D3', alpha=0.8, zorder=100)

            # Intense screen flash with heavy chromatic aberration
            if local % 20 < 2:
                ax.add_patch(patches.Rectangle((0, 0), WIDTH, HEIGHT,
                            color='#9400D3', alpha=0.4, zorder=500))
                ctx['lighting'].render_chromatic_aberration(ax, frame, 0.8)
                ctx['camera'].shake(20, 0.85)

            # Constant dimensional particle emission
            if local % 3 == 0:
                ctx['particles'].emit_magic(
                    np.random.uniform(WIDTH * 0.2, WIDTH * 0.8),
                    np.random.uniform(HEIGHT * 0.3, HEIGHT * 0.7), 'purple', 1.2)

            # Bloom around rifts
            for i in range(3):
                tear_x = WIDTH * (0.25 + i * 0.25)
                tear_y = HEIGHT * 0.45
                ctx['lighting'].render_bloom(ax, frame, tear_x, tear_y, 60,
                                            color='#9400D3', intensity=0.3 * rift_p)

            # God rays from the rifts (otherworldly purple)
            ctx['lighting'].render_god_rays(ax, frame, WIDTH * 0.5, HEIGHT * 0.5,
                                           color='#9400D3', intensity=rift_p * 0.4, num_rays=8)

            # Intense danger vignette
            ctx['lighting'].render_vignette(ax, 0.6 + rift_p * 0.2, color='#0a0020')

        # Phase 5: COLLAPSING BRIDGE - Near death! (60-75%)
        elif p < 0.75:
            bridge_p = (p - 0.6) / 0.15

            # Volcanic/hellish landscape
            ax.set_facecolor('#1a0505')

            # Lava below
            for i in range(10):
                lava_x = (local * 3 + i * 200) % WIDTH
                lava = patches.Ellipse(
                    (lava_x, HEIGHT * 0.08), 150, 30,
                    color='#FF4500', alpha=0.8, zorder=2
                )
                ax.add_patch(lava)
                # Lava bubbles
                bubble_y = HEIGHT * 0.08 + abs(np.sin(local * 0.1 + i)) * 20
                ax.add_patch(patches.Circle((lava_x, bubble_y), 10,
                            color='#FFD700', alpha=0.6, zorder=3))

            # Crumbling bridge
            bridge_y = HEIGHT * 0.25
            # Bridge segments that fall
            for i in range(15):
                segment_x = WIDTH * (0.1 + i * 0.055)
                # Segments behind the horse fall
                if segment_x < WIDTH * (0.3 + bridge_p * 0.2):
                    fall_amount = (WIDTH * (0.3 + bridge_p * 0.2) - segment_x) * 0.5
                    segment_y = bridge_y - fall_amount - abs(np.sin(local * 0.1 + i)) * fall_amount * 0.3
                    segment_alpha = max(0, 1 - fall_amount / 100)
                else:
                    segment_y = bridge_y
                    segment_alpha = 1

                if segment_alpha > 0:
                    segment = patches.Rectangle(
                        (segment_x, segment_y), WIDTH * 0.05, 20,
                        color='#4a3020', alpha=segment_alpha, zorder=10
                    )
                    ax.add_patch(segment)

            # Horse JUMPING over gaps
            jump_cycle = (local % 60) / 60
            jump_height = np.sin(jump_cycle * np.pi) * 80

            horse_x = WIDTH * (0.35 + bridge_p * 0.25)
            self.horse.x = horse_x
            self.horse.y = HEIGHT * 0.35 + jump_height
            self.horse.is_galloping = True
            self.horse.speed = 30
            self.horse.render(ax, local)

            eli = Frog(horse_x - 10, HEIGHT * 0.57 + jump_height, 0.8)
            eli.emotion = Emotion.SCARED
            eli.render(ax, local)

            # BELLA REVEALS HER TRUE STARBORN NATURE TO PROTECT ELI!
            bella = Waitress(horse_x + 30, HEIGHT * 0.55 + jump_height, 0.75)

            # As danger peaks, Bella's celestial form awakens!
            if bridge_p > 0.4:
                bella.celestial_form = True
                bella.celestial_power = min(1.0, (bridge_p - 0.4) * 2.5)  # Power surges!
                bella.emotion = Emotion.DETERMINED  # No longer scared - protecting her love!
            else:
                bella.emotion = Emotion.SCARED
            bella.render(ax, local)

            # Bella's dialogue - THE MOMENT SHE REVEALS HER POWER!
            if bridge_p > 0.5 and bridge_p < 0.7:
                ax.text(WIDTH/2, HEIGHT * 0.8, '"I WON\'T LET YOU FALL!"',
                       fontsize=28, fontweight='bold', ha='center',
                       color='#FFD700', alpha=(bridge_p - 0.5) * 3, zorder=100)

            # Bella reveals her true nature!
            if bridge_p > 0.7:
                reveal_alpha = (bridge_p - 0.7) / 0.3
                ax.text(WIDTH/2, HEIGHT * 0.88,
                       '"I AM BELLA, LAST OF THE STARBORN!"',
                       fontsize=24, ha='center', color='#00BFFF',
                       alpha=reveal_alpha, style='italic', zorder=100)
                ax.text(WIDTH/2, HEIGHT * 0.82,
                       '"FOR TEN THOUSAND YEARS I WAITED FOR YOU!"',
                       fontsize=20, ha='center', color='#FFD700',
                       alpha=reveal_alpha * 0.8, style='italic', zorder=100)

            # The ley lines respond to Bella's awakening - golden energy pulses!
            if bridge_p > 0.5:
                ley_pulse = bridge_p - 0.5
                for i in range(7):
                    ley_angle = (i / 7) * 2 * np.pi + local * 0.01
                    ley_x = horse_x + 30 + np.cos(ley_angle) * 150 * ley_pulse
                    ley_y = HEIGHT * 0.55 + jump_height + np.sin(ley_angle) * 100 * ley_pulse
                    ley_colors = ['#FFD700', '#FF6B35', '#FF1493', '#9400D3', '#00FF7F', '#00BFFF', '#FFFFFF']
                    ax.scatter([ley_x], [ley_y], c=ley_colors[i],
                              s=30 * ley_pulse * 2, alpha=0.7 * ley_pulse, zorder=50)

            # Rocks falling
            for i in range(8):
                rock_x = WIDTH * 0.3 + np.random.randn() * 200
                rock_y = HEIGHT * 0.5 - (local * 5 + i * 50) % (HEIGHT * 0.6)
                rock = patches.Circle((rock_x, rock_y), 15 + i * 3,
                                      color='#3a2a20', alpha=0.7, zorder=15)
                ax.add_patch(rock)

            # DANGER text flashing
            if local % 30 < 15:
                ax.text(WIDTH/2, HEIGHT * 0.5, "DANGER",
                       fontsize=50, fontweight='bold', ha='center',
                       color='#FF0000', alpha=0.6, zorder=100)

            # Lava glow bloom
            ctx['lighting'].render_bloom(ax, frame, WIDTH * 0.5, HEIGHT * 0.08, 200,
                                        color='#FF4500', intensity=0.5)

            # Explosion particles from falling rocks
            if local % 12 == 0:
                ctx['particles'].emit_explosion(
                    WIDTH * 0.3 + np.random.rand() * WIDTH * 0.4,
                    HEIGHT * 0.15, 1.2)

            # God rays from lava below (hellish orange)
            ctx['lighting'].render_god_rays(ax, frame, WIDTH * 0.5, HEIGHT * 0.05,
                                           color='#FF4500', intensity=0.3, num_rays=6)

            # Chromatic aberration on every jump impact
            if local % 60 > 55:
                ctx['lighting'].render_chromatic_aberration(ax, frame, 0.5)

            # Hellish red vignette
            ctx['lighting'].render_vignette(ax, 0.6 + bridge_p * 0.15, color='#1a0505')

            # Lens flare from lava
            ctx['lighting'].render_lens_flare(ax, frame, WIDTH * 0.5, HEIGHT * 0.1,
                                             intensity=0.25)

        # Phase 6: FINAL LEAP - Escape to safety (75-90%)
        # THIS IS THE CLIMACTIC SLOW-MOTION MOMENT!
        elif p < 0.9:
            leap_p = (p - 0.75) / 0.15

            # SLOW MOTION during the epic leap! (apex of jump)
            if leap_p > 0.3 and leap_p < 0.7 and not self.leap_slowmo_triggered:
                ctx['slowmo'].enter_slowmo(0.25, with_vignette=True)
                self.leap_slowmo_triggered = True
            elif leap_p > 0.7 and self.leap_slowmo_triggered:
                ctx['slowmo'].exit_slowmo()
                self.leap_slowmo_triggered = False

            # Transitioning to safer ground
            safe_color = lerp_color('#1a0505', '#0a1a0a', leap_p)
            ax.set_facecolor(safe_color)

            # The final massive leap
            leap_arc = np.sin(leap_p * np.pi)
            leap_height = leap_arc * HEIGHT * 0.4

            # Safe ground ahead
            safe_ground = patches.Rectangle(
                (WIDTH * 0.6, 0), WIDTH * 0.4, HEIGHT * 0.3,
                color='#1a3a1a', zorder=5
            )
            ax.add_patch(safe_ground)

            # Chasm they're jumping over
            chasm = patches.Rectangle(
                (WIDTH * 0.3, 0), WIDTH * 0.3, HEIGHT * 0.3,
                color='#050505', zorder=4
            )
            ax.add_patch(chasm)

            # Horse in mid-leap - THUNDER IN FULL COSMIC GLORY!
            horse_x = WIDTH * (0.35 + leap_p * 0.35)
            self.horse.x = horse_x
            self.horse.y = HEIGHT * 0.25 + leap_height
            self.horse.is_galloping = True
            self.horse.speed = 35
            # Thunder channels cosmic power for the impossible leap!
            self.horse.cosmic_form = True
            self.horse.cosmic_power = leap_arc  # Power peaks at apex of jump
            self.horse.render(ax, local)

            eli = Frog(horse_x - 10, HEIGHT * 0.47 + leap_height, 0.8)
            eli.emotion = Emotion.DETERMINED
            eli.render(ax, local)

            bella = Waitress(horse_x + 30, HEIGHT * 0.45 + leap_height, 0.75)
            bella.emotion = Emotion.DETERMINED
            bella.render(ax, local)

            # God rays during the leap (hope shining through)
            if leap_p > 0.2:
                ctx['lighting'].render_god_rays(ax, frame, WIDTH * 0.7, HEIGHT * 0.7,
                                               color='#FFD700', intensity=(leap_p - 0.2) * 0.4, num_rays=5)

            # Bloom around the leaping horse (heroic glow)
            ctx['lighting'].render_bloom(ax, frame, horse_x, HEIGHT * 0.35 + leap_height, 100,
                                        color='#FFD700', intensity=leap_arc * 0.5)

            # Lens flare at apex of jump
            if 0.4 < leap_p < 0.6:
                flare_intensity = 1 - abs(leap_p - 0.5) / 0.1
                ctx['lighting'].render_lens_flare(ax, frame, horse_x, HEIGHT * 0.5 + leap_height,
                                                 intensity=flare_intensity * 0.5)

            # Render slow-mo effects
            ctx['slowmo'].render_effects(ax)

            # Magic particles trail behind the horse during leap
            if local % 2 == 0:
                ctx['particles'].emit_magic(horse_x - 40, HEIGHT * 0.3 + leap_height, 'gold', 0.8)

            # Triumphant moment - landing
            if leap_p > 0.7:
                # Landing impact with chromatic aberration
                ctx['camera'].shake(30, 0.8)
                ctx['lighting'].render_chromatic_aberration(ax, frame, 0.4)

                # Dust cloud
                for i in range(10):
                    dust_x = horse_x + np.random.randn() * 50
                    dust_y = HEIGHT * 0.28 + np.random.rand() * 20
                    dust = patches.Circle((dust_x, dust_y), 20 + i * 5,
                                         color='#8B7355', alpha=0.3 - i * 0.025, zorder=20)
                    ax.add_patch(dust)

                # Explosion of hope particles on landing
                if leap_p > 0.75 and leap_p < 0.78:
                    for _ in range(5):
                        ctx['particles'].emit_magic(horse_x + np.random.randn() * 40,
                                                   HEIGHT * 0.3, 'gold', 1.5)

            # Stars/hope appearing
            for i in range(15):
                star_x = WIDTH * (0.65 + np.random.rand() * 0.3)
                star_y = HEIGHT * (0.5 + np.random.rand() * 0.4)
                twinkle = 0.5 + 0.5 * np.sin(local * 0.1 + i)
                ax.scatter([star_x], [star_y], c='#FFD700',
                          s=10 * twinkle * leap_p, alpha=twinkle * leap_p, zorder=25)

            # Transition vignette (from danger to safety)
            vignette_color = lerp_color('#1a0000', '#0a1a0a', leap_p)
            ctx['lighting'].render_vignette(ax, 0.4 - leap_p * 0.2, color=vignette_color)

        # Phase 7: Safe at last - tender moment (90-100%)
        else:
            safe_p = (p - 0.9) / 0.1

            # Peaceful, dawn-like atmosphere
            ax.set_facecolor('#1a2a3a')

            # Gentle sky gradient
            for i in range(5):
                band_y = HEIGHT * (0.6 + i * 0.1)
                band = patches.Rectangle(
                    (0, band_y), WIDTH, HEIGHT * 0.1,
                    color='#3a4a6a' if i < 3 else '#5a4a5a', alpha=0.5, zorder=1
                )
                ax.add_patch(band)

            # Sunrise hints
            sun_glow = patches.Circle(
                (WIDTH * 0.8, HEIGHT * 0.7), 100,
                color='#FFD700', alpha=0.3 * safe_p, zorder=2
            )
            ax.add_patch(sun_glow)

            # Safe meadow
            meadow = patches.Rectangle(
                (0, 0), WIDTH, HEIGHT * 0.35,
                color='#2a4a2a', zorder=5
            )
            ax.add_patch(meadow)

            # Horse resting
            self.horse.x = WIDTH * 0.3
            self.horse.y = HEIGHT * 0.35
            self.horse.is_galloping = False
            self.horse.speed = 0
            self.horse.render(ax, local)

            # Eli and Bella dismounted, close together
            eli = Frog(WIDTH * 0.5, HEIGHT * 0.2, 1.0)
            eli.emotion = Emotion.LOVE
            eli.render(ax, local)

            bella = Waitress(WIDTH * 0.58, HEIGHT * 0.22, 1.0)
            bella.emotion = Emotion.LOVE
            bella.render(ax, local)

            # Tender moment - they embrace
            if safe_p > 0.3:
                embrace_alpha = (safe_p - 0.3) / 0.7
                # Warm glow around them
                for i in range(4):
                    glow = patches.Ellipse(
                        (WIDTH * 0.54, HEIGHT * 0.21), 120 + i * 30, 80 + i * 20,
                        color='#FFD700', alpha=0.08 * embrace_alpha, zorder=25
                    )
                    ax.add_patch(glow)

            # Final emotional text
            if safe_p > 0.5:
                text_alpha = (safe_p - 0.5) / 0.5
                ax.text(WIDTH/2, HEIGHT * 0.8,
                       "\"We made it... together.\"",
                       fontsize=28, ha='center', color='#FFD700',
                       alpha=text_alpha, style='italic', zorder=100)

            # Hearts rising
            for i in range(5):
                heart_y = HEIGHT * (0.35 + safe_p * 0.3 + i * 0.08)
                heart_x = WIDTH * 0.54 + np.sin(local * 0.05 + i) * 30
                ax.text(heart_x, heart_y, '♥', fontsize=20,
                       color='#FF69B4', alpha=safe_p * (1 - i * 0.15), ha='center', zorder=30)

            # Romantic god rays from sunrise
            ctx['lighting'].render_god_rays(ax, frame, WIDTH * 0.8, HEIGHT * 0.7,
                                           color='#FFD700', intensity=safe_p * 0.35, num_rays=4)

            # Bloom around the couple
            ctx['lighting'].render_bloom(ax, frame, WIDTH * 0.54, HEIGHT * 0.21, 80,
                                        color='#FFD700', intensity=safe_p * 0.4)

            # Lens flare from sunrise
            ctx['lighting'].render_lens_flare(ax, frame, WIDTH * 0.8, HEIGHT * 0.7,
                                             intensity=safe_p * 0.3)

            # Romantic magic particles
            if local % 4 == 0 and safe_p > 0.3:
                ctx['particles'].emit_magic(WIDTH * 0.54 + np.random.randn() * 40,
                                           HEIGHT * 0.25, 'pink', 0.6)

            # Soft romantic vignette
            ctx['lighting'].render_vignette(ax, 0.2, color='#1a1a2a')

        # UNIVERSAL EFFECTS throughout the entire ride
        # Film grain for cinematic texture (like BattleScene)
        ctx['lighting'].render_film_grain(ax, frame, 0.02)

        # Update and render particles
        ctx['particles'].update()
        ctx['particles'].render(ax)


class TransformScene(Scene):
    """Magical transformation with smooth animations"""
    def render(self, ax, frame: int, ctx: dict):
        p = self.progress(frame)
        local = frame - self.start

        # Smooth eased progress for key animations
        eased_p = Easing.ease_in_out_cubic(p)

        # Dynamic background color shift
        bg_hue = 0.75 + p * 0.1  # Purple to more violet
        ax.set_facecolor('#1a0a2e')

        # Smooth swirling vortex with multiple layers
        for layer in range(2):
            layer_offset = layer * np.pi
            for i in range(30):
                angle = (i / 30) * 2 * np.pi + local * (0.02 + layer * 0.01) + layer_offset
                # Smooth pulsing distance
                pulse = Easing.smooth_step(1 - abs(eased_p - 0.5) * 2)
                dist = 100 + 220 * pulse + np.sin(local * 0.03 + i * 0.5) * 20
                px = WIDTH/2 + np.cos(angle) * dist
                py = HEIGHT/2 + np.sin(angle) * dist * 0.7
                # Smooth size pulsing
                size = 12 + 12 * (0.5 + 0.5 * np.sin(local * 0.04 + i * 0.3))
                color = '#9400D3' if (i + layer) % 2 else '#00FF7F'
                alpha = 0.6 * (0.5 + 0.5 * np.sin(local * 0.05 + i))
                ax.scatter([px], [py], c=color, s=size, alpha=alpha, zorder=5 + layer)

        # Smooth pulsing magic rings
        for r in range(4):
            ring_pulse = np.sin(local * 0.06 + r * 0.8) * 0.5 + 0.5
            ring_radius = 80 + r * 40 + ring_pulse * 25
            ring_alpha = (0.5 - r * 0.1) * (0.7 + 0.3 * ring_pulse)
            ring = patches.Circle((WIDTH/2, HEIGHT/2), ring_radius,
                        fill=False, edgecolor='#FFD700', linewidth=2 + ring_pulse,
                        alpha=ring_alpha, zorder=10)
            ax.add_patch(ring)

        # Smooth human silhouette fade
        if p < 0.45:
            fade_p = Easing.ease_in_cubic(p / 0.45)
            alpha = 1 - fade_p
            # Dissolving effect with multiple fading circles
            for i in range(5):
                offset_x = np.sin(local * 0.1 + i) * 5 * fade_p
                offset_y = np.cos(local * 0.12 + i) * 3 * fade_p
                ax.add_patch(patches.Circle((WIDTH/2 + offset_x, HEIGHT/2 + 70 + offset_y),
                            30 * (1 - fade_p * 0.3), color='white', alpha=alpha * (1 - i * 0.15), zorder=15))
            ax.add_patch(patches.Rectangle((WIDTH/2 - 20, HEIGHT/2 - 40), 40, 90,
                        color='white', alpha=alpha * 0.9, zorder=15))

        # Smooth frog emergence with elastic effect
        if p > 0.2:
            emerge_p = min(1, (p - 0.2) / 0.5)
            eased_emerge = Easing.ease_out_elastic(emerge_p) if emerge_p < 0.8 else 1.0
            eased_emerge = clamp(eased_emerge, 0, 1.2)  # Allow slight overshoot for scale
            scale = 0.6 + eased_emerge * 0.8
            frog = Frog(WIDTH/2, HEIGHT/2, scale)
            frog.alpha = clamp(emerge_p * 1.5, 0, 1)
            frog.emotion = Emotion.SHOCKED if p < 0.6 else Emotion.POWERFUL
            glow_intensity = clamp(emerge_p * 1.2, 0, 1)
            frog.set_glow(True, '#00FF7F', glow_intensity)
            frog.render(ax, local)

        # Smooth particle emission
        if local % 3 == 0:
            angle = local * 0.1
            emit_x = WIDTH/2 + np.cos(angle) * 50
            emit_y = HEIGHT/2 + np.sin(angle) * 30
            ctx['particles'].emit_magic(emit_x, emit_y, 'purple', 0.7)

        # Smooth text fade in
        if p > 0.78:
            text_alpha = Easing.ease_out_cubic((p - 0.78) / 0.22)
            # Glow effect behind text
            for i in range(3):
                ax.text(WIDTH/2, HEIGHT * 0.12, "THE TRANSFORMATION IS COMPLETE",
                       fontsize=32, ha='center', color='#00FF00',
                       alpha=text_alpha * (0.2 - i * 0.05), fontweight='bold', zorder=99)
            ax.text(WIDTH/2, HEIGHT * 0.12, "THE TRANSFORMATION IS COMPLETE",
                   fontsize=32, ha='center', color='#FFD700',
                   alpha=text_alpha, fontweight='bold', zorder=100)


class BattleScene(Scene):
    """Epic boss battle with slow-motion finishing moves"""
    def __init__(self, start: int, duration: int, boss_type: str):
        super().__init__(start, duration)
        self.boss_type = boss_type
        self.env = BattleArenaEnvironment()
        self.slowmo_triggered = False

    def render(self, ax, frame: int, ctx: dict):
        p = self.progress(frame)
        local = frame - self.start
        self.env.render_background(ax, frame, ctx['lighting'])

        # Create boss
        if self.boss_type == 'serpent':
            boss = ShadowSerpent(WIDTH * 0.7, HEIGHT * 0.4, 1.8)
        elif self.boss_type == 'heron':
            boss = StormHeron(WIDTH * 0.75, HEIGHT * 0.35, 2.0)
        else:
            boss = TheDarkOne(WIDTH * 0.65, HEIGHT * 0.5, 2.5)

        # Hero position changes during battle - dramatic movement
        hero_x = WIDTH * 0.25 + np.sin(local * 0.02) * 50
        hero_y = HEIGHT * 0.35 + np.cos(local * 0.015) * 20

        # Final blow positioning
        if p > 0.8 and p < 0.92:
            # Hero charges forward for the kill
            charge_p = (p - 0.8) / 0.12
            hero_x = lerp(WIDTH * 0.25, WIDTH * 0.55, Easing.ease_out_cubic(charge_p))
            hero_y = HEIGHT * 0.35 + np.sin(charge_p * np.pi) * 100  # Jump arc

        hero = Frog(hero_x, hero_y, 1.2)
        hero.emotion = Emotion.DETERMINED if p < 0.7 else Emotion.POWERFUL
        hero.set_glow(p > 0.5, '#00FF7F', min(1, (p - 0.5) * 2))

        boss.emotion = Emotion.ANGRY
        if hasattr(boss, 'is_attacking'):
            boss.is_attacking = (local % 50) < 25

        # SLOW MOTION during finishing blow!
        if p > 0.78 and p < 0.88 and not self.slowmo_triggered:
            ctx['slowmo'].enter_slowmo(0.3, with_vignette=True)
            self.slowmo_triggered = True
        elif p > 0.88 and self.slowmo_triggered:
            ctx['slowmo'].exit_slowmo()
            self.slowmo_triggered = False

        # Combat with enhanced effects
        if local % 40 == 0 and p < 0.9:
            hero.jump(10)
            ctx['particles'].emit_magic(hero.x, hero.y, 'green', 1.2)
            ctx['camera'].shake(12, 0.88)
        if local % 55 == 25:
            ctx['particles'].emit_dark_energy(boss.x, boss.y, 1.0)

        # Big explosion on finishing blow
        if p > 0.85 and p < 0.87:
            ctx['particles'].emit_explosion(boss.x, boss.y, 3.0)
            ctx['camera'].shake(25, 0.85)
            for i in range(5):
                ctx['particles'].emit_magic(boss.x + np.random.randn() * 50,
                                           boss.y + np.random.randn() * 50, 'gold', 2.0)

        boss.render(ax, local)
        hero.render(ax, local)

        # Render slow-mo effects
        ctx['slowmo'].render_effects(ax)

        # CINEMATIC EFFECTS - god rays during dramatic moments
        if p > 0.5:
            # Hero power glow creates god rays
            ctx['lighting'].render_god_rays(ax, frame, hero_x, hero_y + 50,
                                           color='#00FF7F', intensity=0.2 * (p - 0.5) * 2, num_rays=6)

        # Lens flare during finishing blow
        if 0.82 < p < 0.88:
            flare_intensity = 1 - abs(p - 0.85) / 0.03
            ctx['lighting'].render_lens_flare(ax, frame, hero_x, hero_y, flare_intensity * 0.6)

        # Dramatic vignette throughout battle, intensifies during slow-mo
        vignette_intensity = 0.3 if not self.slowmo_triggered else 0.6
        ctx['lighting'].render_vignette(ax, vignette_intensity)

        # CHROMATIC ABERRATION on big impacts
        if 0.84 < p < 0.88:
            impact_intensity = 1 - abs(p - 0.86) / 0.02
            ctx['lighting'].render_chromatic_aberration(ax, frame, impact_intensity * 0.5)

        # Bloom around hero's power glow
        if p > 0.5:
            ctx['lighting'].render_bloom(ax, frame, hero_x, hero_y, 80,
                                        color='#00FF7F', intensity=(p - 0.5) * 0.8)

        # Film grain for cinematic texture
        ctx['lighting'].render_film_grain(ax, frame, 0.02)

        # Health bars with pulsing effect when low
        boss_hp = max(0, 100 - p * 105)
        pulse = 1.0 if boss_hp > 20 else 1.0 + np.sin(local * 0.3) * 0.1
        ax.add_patch(patches.Rectangle((WIDTH/2 - 180, HEIGHT - 55), 360, 25, color='#222', zorder=200))
        bar_color = '#FF0000' if boss_hp > 20 else '#FF4444'
        ax.add_patch(patches.Rectangle((WIDTH/2 - 175, HEIGHT - 52), 350 * boss_hp / 100 * pulse, 19, color=bar_color, zorder=201))
        ax.text(WIDTH/2, HEIGHT - 75, self.boss_type.upper().replace('_', ' '), fontsize=18, ha='center', color='#FF4444', fontweight='bold', zorder=202)

        # Epic victory sequence
        if p > 0.92:
            victory_p = (p - 0.92) / 0.08
            # Screen flash
            ax.add_patch(patches.Rectangle((0, 0), WIDTH, HEIGHT, color='white', alpha=victory_p * 0.7, zorder=300))
            # Pulsing victory text
            text_scale = 1 + np.sin(local * 0.2) * 0.1
            ax.text(WIDTH/2, HEIGHT/2, "VICTORY!", fontsize=int(70 * text_scale), ha='center', va='center',
                   color='#FFD700', alpha=victory_p, fontweight='bold', zorder=301)
            # Particle celebration
            if local % 5 == 0:
                ctx['particles'].emit_magic(np.random.uniform(100, WIDTH-100), HEIGHT * 0.7, 'gold', 1.5)


class HeroicRiseScene(Scene):
    """Eli falls, appears defeated, then dramatically rises with new power"""
    def render(self, ax, frame: int, ctx: dict):
        p = self.progress(frame)
        local = frame - self.start

        # Dark, hopeless background
        darkness = max(0, 0.9 - p * 0.5 if p > 0.6 else 0.9)
        ax.set_facecolor(f'#{int(10 + (1-darkness)*40):02x}{int(5 + (1-darkness)*30):02x}{int(15 + (1-darkness)*20):02x}')

        # Phase 1: Eli falls (0-30%)
        if p < 0.3:
            fall_p = p / 0.3
            eli_y = HEIGHT * 0.5 - Easing.ease_in_cubic(fall_p) * HEIGHT * 0.35
            eli = Frog(WIDTH * 0.5, eli_y, 1.2 - fall_p * 0.3)
            eli.emotion = Emotion.SAD
            eli.alpha = 1.0 - fall_p * 0.3
            eli.render(ax, local)

            # Impact shake
            if fall_p > 0.9:
                ctx['camera'].shake(20, 0.9)

        # Phase 2: Darkness and despair (30-50%)
        elif p < 0.5:
            despair_p = (p - 0.3) / 0.2
            # Eli lying on ground
            eli = Frog(WIDTH * 0.5, HEIGHT * 0.15, 0.9)
            eli.emotion = Emotion.SAD
            eli.alpha = 0.7 - despair_p * 0.3
            eli.render(ax, local)

            # Sad text
            ax.text(WIDTH/2, HEIGHT * 0.7, "All hope is lost...", fontsize=28,
                   ha='center', color='#666666', alpha=despair_p, style='italic', zorder=100)

            # Friends crying in background
            luna = Frog(WIDTH * 0.3, HEIGHT * 0.2, 0.7, 'princess', 'Luna')
            luna.emotion = Emotion.SAD
            luna.alpha = 0.5
            luna.render(ax, local)

        # Phase 3: The spark of hope (50-65%)
        elif p < 0.65:
            spark_p = (p - 0.5) / 0.15
            # Heartbeat pulse
            pulse = np.sin(spark_p * np.pi * 4) * 0.5 + 0.5

            # Small light appears
            glow_radius = spark_p * 100
            for i in range(5):
                ax.add_patch(patches.Circle((WIDTH * 0.5, HEIGHT * 0.2), glow_radius + i * 20,
                            color='#00FF7F', alpha=pulse * 0.1 * (1 - i * 0.15), zorder=50))

            # Eli still down but glowing
            eli = Frog(WIDTH * 0.5, HEIGHT * 0.15, 0.9)
            eli.set_glow(True, '#00FF7F', spark_p * pulse)
            eli.render(ax, local)

            ax.text(WIDTH/2, HEIGHT * 0.7, "But wait...", fontsize=24,
                   ha='center', color='#00FF7F', alpha=spark_p, zorder=100)

        # Phase 4: THE RISE (65-85%)
        elif p < 0.85:
            rise_p = (p - 0.65) / 0.2
            eased = Easing.ease_out_elastic(min(1, rise_p * 1.2))

            # Eli rises dramatically
            eli_y = HEIGHT * 0.15 + eased * HEIGHT * 0.35
            eli_scale = 0.9 + eased * 0.6

            eli = Frog(WIDTH * 0.5, eli_y, eli_scale)
            eli.emotion = Emotion.POWERFUL
            eli.has_crown = rise_p > 0.5
            eli.set_glow(True, '#00FF7F', min(1, eased * 1.5))
            eli.render(ax, local)

            # Massive energy burst
            for i in range(8):
                ring_radius = rise_p * 300 + i * 40
                ax.add_patch(patches.Circle((WIDTH * 0.5, eli_y), ring_radius,
                            fill=False, edgecolor='#00FF7F', linewidth=4 - i * 0.4,
                            alpha=max(0, 0.8 - rise_p * 0.5 - i * 0.08), zorder=45))

            # Screen shake and particles
            ctx['camera'].shake(15 * (1 - rise_p), 0.9)
            if local % 3 == 0:
                ctx['particles'].emit_magic(WIDTH * 0.5 + np.random.randn() * 100,
                                           eli_y + np.random.randn() * 50, 'green', 2.0)

            # Epic text
            if rise_p > 0.3:
                text_alpha = min(1, (rise_p - 0.3) / 0.3)
                ax.text(WIDTH/2, HEIGHT * 0.85, "I AM THE EMERALD GUARDIAN!",
                       fontsize=36, ha='center', fontweight='bold',
                       color='#00FF7F', alpha=text_alpha, zorder=100)

        # Phase 5: Full power pose (85-100%)
        else:
            power_p = (p - 0.85) / 0.15

            # Powerful Eli
            eli = Frog(WIDTH * 0.5, HEIGHT * 0.5, 1.5)
            eli.emotion = Emotion.POWERFUL
            eli.has_crown = True
            eli.set_glow(True, '#FFD700', 0.8 + np.sin(local * 0.1) * 0.2)
            eli.render(ax, local)

            # Golden aura
            for i in range(6):
                ax.add_patch(patches.Circle((WIDTH * 0.5, HEIGHT * 0.5), 150 + i * 30,
                            fill=False, edgecolor='#FFD700', linewidth=3,
                            alpha=0.4 - i * 0.06, zorder=40))

            # Continuous particles
            if local % 4 == 0:
                angle = local * 0.05
                px = WIDTH * 0.5 + np.cos(angle) * 150
                py = HEIGHT * 0.5 + np.sin(angle) * 100
                ctx['particles'].emit_magic(px, py, 'gold', 1.0)

            # CINEMATIC EFFECTS - god rays emanating from Eli
            ctx['lighting'].render_god_rays(ax, frame, WIDTH * 0.5, HEIGHT * 0.5 + 100,
                                           color='#FFD700', intensity=0.5, num_rays=10)

            # Lens flare from power
            ctx['lighting'].render_lens_flare(ax, frame, WIDTH * 0.5, HEIGHT * 0.5,
                                             intensity=0.4 + power_p * 0.3)

        # Vignette throughout - darkness at edges focuses attention on Eli
        vignette_strength = 0.5 if p < 0.65 else max(0.2, 0.5 - (p - 0.65) * 1.5)
        ctx['lighting'].render_vignette(ax, vignette_strength)

        # CHROMATIC ABERRATION during the power surge (THE RISE phase)
        if 0.7 < p < 0.85:
            surge_intensity = 1 - abs(p - 0.775) / 0.075
            ctx['lighting'].render_chromatic_aberration(ax, frame, surge_intensity * 0.4)

        # Film grain for cinematic texture
        ctx['lighting'].render_film_grain(ax, frame, 0.025)

        # Bloom during power phases
        if p > 0.65:
            bloom_intensity = min(1, (p - 0.65) * 3)
            ctx['lighting'].render_bloom(ax, frame, WIDTH * 0.5, HEIGHT * 0.4, 120,
                                        color='#00FF7F', intensity=bloom_intensity * 0.5)


class WeddingScene(Scene):
    """Beautiful wedding between Eli and Bella - the happy ending
    After their harrowing escape through the dangerous horse ride,
    Eli and Bella's love has been tested and proven true."""
    def render(self, ax, frame: int, ctx: dict):
        p = self.progress(frame)
        local = frame - self.start

        # Beautiful sunset gradient background
        for i in range(20):
            y = HEIGHT * i / 20
            t = i / 20
            r = int(lerp(255, 135, t))
            g = int(lerp(200, 206, t))
            b = int(lerp(150, 235, t))
            ax.add_patch(patches.Rectangle((0, y), WIDTH, HEIGHT/20 + 1,
                        color=f'#{r:02x}{g:02x}{b:02x}', zorder=1))

        # Floating hearts
        np.random.seed(42)
        for i in range(20):
            hx = (np.random.rand() * WIDTH + local * 0.5) % WIDTH
            hy = np.random.rand() * HEIGHT * 0.5 + HEIGHT * 0.4
            size = 15 + np.random.rand() * 15
            alpha = 0.3 + np.sin(local * 0.05 + i) * 0.2
            ax.text(hx, hy, '♥', fontsize=int(size), color='#FF69B4',
                   alpha=clamp(alpha, 0.1, 0.6), ha='center', zorder=5)

        # Draw flower arch
        for i in range(40):
            angle = np.pi * 0.15 + (i / 40) * np.pi * 0.7
            fx = WIDTH * 0.5 + np.cos(angle) * 220
            fy = HEIGHT * 0.6 + np.sin(angle) * 160
            colors = ['#FF69B4', '#FFB6C1', '#FFFFFF', '#FF1493', '#FFD700']
            flower_color = colors[i % len(colors)]
            ax.add_patch(patches.Circle((fx, fy), 12 + np.sin(local * 0.1 + i) * 3,
                        color=flower_color, alpha=0.8, zorder=10))

        # Grass/ground
        ax.add_patch(patches.Rectangle((0, 0), WIDTH, HEIGHT * 0.25, color='#228B22', zorder=2))

        # Aisle with flower petals
        ax.add_patch(patches.Rectangle((WIDTH * 0.35, 0), WIDTH * 0.3, HEIGHT * 0.25,
                    color='#FFFFFF', alpha=0.3, zorder=3))

        # The happy couple - ELI AND BELLA!
        eli = Frog(WIDTH * 0.45, HEIGHT * 0.28, 1.3)
        eli.emotion = Emotion.LOVE
        eli.has_crown = True
        eli.set_glow(True, '#FFD700', 0.3)
        eli.render(ax, local)

        # BELLA - the waitress from Huuters, now Eli's bride!
        bella = Waitress(WIDTH * 0.55, HEIGHT * 0.28, 1.2)
        bella.emotion = Emotion.LOVE
        bella.render(ax, local)

        # Kiss moment!
        if p > 0.4 and p < 0.7:
            kiss_p = (p - 0.4) / 0.3
            # Hearts burst out
            if local % 8 == 0:
                ctx['particles'].emit_magic(WIDTH * 0.5, HEIGHT * 0.35, 'pink', 1.0)

            # Sparkles around them
            for i in range(8):
                angle = (i / 8) * 2 * np.pi + local * 0.03
                sx = WIDTH * 0.5 + np.cos(angle) * (80 + kiss_p * 40)
                sy = HEIGHT * 0.3 + np.sin(angle) * 50
                ax.scatter([sx], [sy], c='#FFD700', s=50, alpha=0.7, zorder=50)

        # Crowd cheering (other frogs)
        for i in range(15):
            row = i // 5
            col = i % 5
            fx = WIDTH * (0.15 + col * 0.08) if col < 2.5 else WIDTH * (0.62 + (col - 2.5) * 0.08)
            fy = HEIGHT * (0.12 + row * 0.04)
            bounce = abs(np.sin(local * 0.1 + i * 0.5)) * 8 if p > 0.3 else 0
            frog = Frog(fx, fy + bounce, 0.4)
            frog.emotion = Emotion.HAPPY
            frog.render(ax, local)

        # Sage officiating
        sage = WiseTurtle(WIDTH * 0.5, HEIGHT * 0.38, 1.0)
        sage.render(ax, local)

        # LUNA - Princess and dear friend, serving as bridesmaid!
        # She stands proudly beside Bella, happy for her friend's love
        luna = Frog(WIDTH * 0.68, HEIGHT * 0.26, 0.9, 'princess', 'Luna')
        luna.emotion = Emotion.HAPPY
        # Luna wears a flower crown for the occasion
        luna.render(ax, local)
        # Bridesmaid flower
        ax.add_patch(patches.Circle((WIDTH * 0.68 - 15, HEIGHT * 0.28), 8,
                    color='#FF69B4', alpha=0.9, zorder=30))

        # THUNDER - The Celestial Steed watches proudly from the background!
        # He brought them together through the dangerous ride
        thunder = MajesticHorse(WIDTH * 0.15, HEIGHT * 0.25, 1.2)
        thunder.is_galloping = False
        # Thunder shows gentle cosmic glow at the wedding
        thunder.cosmic_form = True
        thunder.cosmic_power = 0.3  # Gentle, not overwhelming
        thunder.tears_of_joy = True  # He weeps shooting stars of joy!
        thunder.render(ax, local)

        # Spark flying around joyfully
        spark_x = WIDTH * 0.5 + np.sin(local * 0.08) * 150
        spark_y = HEIGHT * 0.55 + np.cos(local * 0.06) * 50
        spark = Dragonfly(spark_x, spark_y, 0.6)
        spark.render(ax, local)

        # "Happily Ever After" text
        if p > 0.75:
            text_p = (p - 0.75) / 0.25
            text_y = HEIGHT * 0.8 + (1 - Easing.ease_out_cubic(text_p)) * 30
            ax.text(WIDTH/2, text_y, "And they lived happily ever after...",
                   fontsize=32, ha='center', style='italic',
                   color='#8B4513', alpha=text_p, zorder=100)

        # Confetti!
        if p > 0.5:
            if local % 4 == 0:
                ctx['particles'].emit_magic(np.random.uniform(100, WIDTH-100),
                                           HEIGHT * 0.9, 'gold', 0.8)

        # CINEMATIC EFFECTS - soft god rays for romantic atmosphere
        ctx['lighting'].render_god_rays(ax, frame, WIDTH * 0.85, HEIGHT * 0.9,
                                       color='#FFB6C1', intensity=0.25, num_rays=6)

        # Soft pink vignette for romantic mood
        ctx['lighting'].render_vignette(ax, 0.25, color='#4A0020')

        # Lens flare during kiss
        if 0.45 < p < 0.65:
            kiss_flare = 1 - abs(p - 0.55) / 0.1
            ctx['lighting'].render_lens_flare(ax, frame, WIDTH * 0.5, HEIGHT * 0.35,
                                             intensity=kiss_flare * 0.4)


class CreditsScene(Scene):
    """Rolling credits"""
    def render(self, ax, frame: int, ctx: dict):
        local = frame - self.start
        ax.set_facecolor('#000000')

        np.random.seed(999)
        for _ in range(100):
            ax.scatter([np.random.rand() * WIDTH], [np.random.rand() * HEIGHT], c='white', s=np.random.rand() * 12, alpha=0.6)

        credits = [("ELI IS A FROG", 65, '#90EE90'), ("THE LEGEND OF THE EMERALD GUARDIAN", 24, '#FFD700'), ("", 35, 'w'),
                   ("Directed by", 20, '#888'), ("Claude Code Productions", 28, '#FFD700'), ("", 25, 'w'),
                   ("Starring", 20, '#888'), ("ELI - The Emerald Guardian", 24, '#32CD32'),
                   ("SAGE - The Wise Mentor", 22, '#8B4513'), ("SPARK - The Loyal Friend", 22, '#00CED1'),
                   ("LUNA - The Princess", 22, '#FF69B4'), ("", 25, 'w'),
                   ("THE SHADOW SERPENT", 22, '#4B0082'), ("THE STORM HERON", 22, '#708090'),
                   ("THE DARK ONE", 22, '#8B0000'), ("", 30, 'w'),
                   ("Animation", 20, '#888'), ("Matplotlib Studios", 24, '#87CEEB'), ("", 20, 'w'),
                   ("Sound", 20, '#888'), ("NumPy Audio", 24, '#87CEEB'), ("", 35, 'w'),
                   ("A CLAUDE CODE PRODUCTION", 28, '#FFD700'), ("", 25, 'w'),
                   ("THE END", 45, '#90EE90')]

        y = -local * 1.0 + HEIGHT * 0.25
        for txt, sz, col in credits:
            if -40 < y < HEIGHT + 40:
                ax.text(WIDTH/2, y, txt, fontsize=sz, ha='center', color=col, zorder=10)
            y += sz * 1.7

        if local > self.duration * 0.85:
            frog = Frog(WIDTH/2, 90, 0.9)
            frog.emotion = Emotion.HAPPY
            frog.has_crown = True
            frog.render(ax, local)


class MentorSacrificeScene(Scene):
    """Sage the Wise Turtle sacrifices himself to save Eli - tearjerker moment"""
    def render(self, ax, frame: int, ctx: dict):
        p = self.progress(frame)
        local = frame - self.start

        # Dramatic dark battlefield
        ax.set_facecolor('#0a0505')

        # Storm clouds
        for i in range(8):
            cloud_x = (local * 0.3 + i * 250) % (WIDTH + 300) - 150
            cloud_y = HEIGHT * (0.7 + i * 0.03)
            ax.add_patch(patches.Ellipse((cloud_x, cloud_y), 400, 100,
                        color='#1a0a0a', alpha=0.8, zorder=2))

        # Lightning flashes
        if local % 60 < 3:
            ax.add_patch(patches.Rectangle((0, 0), WIDTH, HEIGHT,
                        color='white', alpha=0.3, zorder=100))
            ctx['camera'].shake(10, 0.9)

        # Phase 1: Dark One attacks Eli (0-25%)
        if p < 0.25:
            attack_p = p / 0.25

            # Dark One charging attack
            dark_one = TheDarkOne(WIDTH * 0.7, HEIGHT * 0.5, 2.0)
            dark_one.render(ax, local)

            # Dark energy beam charging
            beam_intensity = Easing.ease_in_cubic(attack_p)
            for i in range(5):
                ax.add_patch(patches.Circle((WIDTH * 0.7, HEIGHT * 0.5), 50 + i * 20 + beam_intensity * 100,
                            color='#4B0082', alpha=0.3 - i * 0.05, zorder=30))

            # Eli in danger
            eli = Frog(WIDTH * 0.3, HEIGHT * 0.25, 1.0)
            eli.emotion = Emotion.SHOCKED
            eli.render(ax, local)

            # Sage watching with concern
            sage = WiseTurtle(WIDTH * 0.15, HEIGHT * 0.3, 1.2)
            sage.render(ax, local)

            # Warning text
            if attack_p > 0.7:
                ax.text(WIDTH/2, HEIGHT * 0.85, "ELI, LOOK OUT!",
                       fontsize=32, ha='center', color='#FF0000',
                       alpha=(attack_p - 0.7) / 0.3, fontweight='bold', zorder=200)

        # Phase 2: Sage jumps in front (25-40%)
        elif p < 0.4:
            jump_p = (p - 0.25) / 0.15
            eased = Easing.ease_out_cubic(jump_p)

            # Dark One firing
            dark_one = TheDarkOne(WIDTH * 0.7, HEIGHT * 0.5, 2.0)
            dark_one.render(ax, local)

            # Dark beam
            beam_width = 60
            ax.add_patch(patches.Rectangle((WIDTH * 0.35, HEIGHT * 0.45), WIDTH * 0.35, beam_width,
                        color='#8B0000', alpha=0.8, zorder=50))
            ax.add_patch(patches.Rectangle((WIDTH * 0.35, HEIGHT * 0.45 + 10), WIDTH * 0.35, beam_width - 20,
                        color='#FF0000', alpha=0.6, zorder=51))

            # Sage jumping into the beam's path
            sage_x = lerp(WIDTH * 0.15, WIDTH * 0.35, eased)
            sage_y = HEIGHT * 0.3 + np.sin(eased * np.pi) * 100
            sage = WiseTurtle(sage_x, sage_y, 1.2)
            sage.render(ax, local)

            # Eli behind
            eli = Frog(WIDTH * 0.3, HEIGHT * 0.25, 1.0)
            eli.emotion = Emotion.SHOCKED
            eli.render(ax, local)

            # SLOW MOTION
            if jump_p > 0.3 and jump_p < 0.9:
                ctx['slowmo'].enter_slowmo(0.2, with_vignette=True)

        # Phase 3: Impact - Sage takes the hit (40-55%)
        elif p < 0.55:
            impact_p = (p - 0.4) / 0.15
            ctx['slowmo'].exit_slowmo()

            # Massive screen shake
            ctx['camera'].shake(30, 0.85)

            # Explosion of light
            for i in range(10):
                ax.add_patch(patches.Circle((WIDTH * 0.35, HEIGHT * 0.35), 50 + impact_p * 200 + i * 30,
                            fill=False, edgecolor='#FFD700', linewidth=4 - i * 0.3,
                            alpha=max(0, 0.8 - impact_p - i * 0.07), zorder=60))

            # Sage hit
            sage = WiseTurtle(WIDTH * 0.35, HEIGHT * 0.3 - impact_p * 50, 1.2)
            sage.alpha = 1.0 - impact_p * 0.3
            sage.render(ax, local)

            # Dark One recoiling
            dark_one = TheDarkOne(WIDTH * 0.75 + impact_p * 30, HEIGHT * 0.5, 2.0)
            dark_one.render(ax, local)

            # Eli reaching out
            eli = Frog(WIDTH * 0.25 + impact_p * 20, HEIGHT * 0.25, 1.0)
            eli.emotion = Emotion.SAD
            eli.render(ax, local)

            # "NOOO!" text
            ax.text(WIDTH/2, HEIGHT * 0.8, "NOOOOO!",
                   fontsize=int(40 + impact_p * 20), ha='center', color='#FFFFFF',
                   alpha=1 - impact_p * 0.5, fontweight='bold', zorder=200)

            if local % 3 == 0:
                ctx['particles'].emit_magic(WIDTH * 0.35 + np.random.randn() * 50,
                                           HEIGHT * 0.35 + np.random.randn() * 30, 'gold', 2.0)

        # Phase 4: Sage's final words (55-85%)
        elif p < 0.85:
            words_p = (p - 0.55) / 0.3

            # Gentle lighting now
            ax.set_facecolor('#0a0510')

            # Sage on ground, glowing
            sage = WiseTurtle(WIDTH * 0.4, HEIGHT * 0.2, 1.0)
            sage.alpha = 0.8 - words_p * 0.4
            # Golden glow around Sage
            for i in range(5):
                ax.add_patch(patches.Circle((WIDTH * 0.4, HEIGHT * 0.22), 80 + i * 20,
                            color='#FFD700', alpha=0.1 - i * 0.015, zorder=5))
            sage.render(ax, local)

            # Eli kneeling beside
            eli = Frog(WIDTH * 0.5, HEIGHT * 0.22, 1.0)
            eli.emotion = Emotion.SAD
            eli.render(ax, local)

            # Luna crying nearby
            luna = Frog(WIDTH * 0.6, HEIGHT * 0.25, 0.8, 'princess', 'Luna')
            luna.emotion = Emotion.SAD
            luna.alpha = 0.7
            luna.render(ax, local)

            # Sage's final words appearing
            words = [
                "You have... the heart of a true guardian...",
                "The prophecy... chose well...",
                "Protect them... Eli...",
                "I believe... in you..."
            ]
            word_idx = min(int(words_p * len(words)), len(words) - 1)
            word_alpha = (words_p * len(words)) % 1

            ax.text(WIDTH/2, HEIGHT * 0.7, words[word_idx],
                   fontsize=24, ha='center', color='#FFD700',
                   alpha=0.5 + word_alpha * 0.5, style='italic', zorder=100)

            # Floating particles (soul leaving)
            if local % 5 == 0:
                ctx['particles'].emit_magic(WIDTH * 0.4 + np.random.randn() * 30,
                                           HEIGHT * 0.25 + words_p * 100, 'gold', 0.5)

        # Phase 5: Sage fades away, Eli gains power (85-100%)
        else:
            fade_p = (p - 0.85) / 0.15

            # Sage dissolving into light
            if fade_p < 0.5:
                sage_alpha = 1 - fade_p * 2
                sage = WiseTurtle(WIDTH * 0.4, HEIGHT * 0.2 + fade_p * 50, 1.0)
                sage.alpha = sage_alpha * 0.5
                sage.render(ax, local)

            # Golden particles rising
            for i in range(20):
                py = HEIGHT * 0.2 + fade_p * HEIGHT * 0.6 + np.sin(local * 0.1 + i) * 30
                px = WIDTH * 0.4 + np.sin(local * 0.05 + i * 0.5) * (50 + fade_p * 100)
                size = 10 + np.random.rand() * 10
                ax.scatter([px], [py], c='#FFD700', s=size, alpha=0.5 - fade_p * 0.3, zorder=50)

            # Eli absorbing the power
            eli = Frog(WIDTH * 0.5, HEIGHT * 0.25, 1.0 + fade_p * 0.3)
            eli.emotion = Emotion.DETERMINED
            eli.set_glow(True, '#FFD700', fade_p)
            eli.render(ax, local)

            # "I won't let you down" text
            if fade_p > 0.3:
                text_alpha = (fade_p - 0.3) / 0.7
                ax.text(WIDTH/2, HEIGHT * 0.8, "I won't let you down, Sage...",
                       fontsize=28, ha='center', color='#90EE90',
                       alpha=text_alpha, style='italic', zorder=100)

            # Screen gradually brightening with determination
            ax.add_patch(patches.Rectangle((0, 0), WIDTH, HEIGHT,
                        color='#FFD700', alpha=fade_p * 0.2, zorder=200))


class VillainOriginScene(Scene):
    """The Dark One's tragic backstory - he was once good"""
    def render(self, ax, frame: int, ctx: dict):
        p = self.progress(frame)
        local = frame - self.start

        # Sepia/desaturated flashback look
        ax.set_facecolor('#2a2015')

        # Vignette effect
        for i in range(6):
            ax.add_patch(patches.Rectangle((0, 0), WIDTH, HEIGHT,
                        fill=False, edgecolor='#1a1510', linewidth=80 * (1 - i/6),
                        alpha=0.2, zorder=100))

        # Phase 1: Young Dark One (he was once a guardian) (0-35%)
        if p < 0.35:
            show_p = p / 0.35

            ax.text(WIDTH/2, HEIGHT * 0.9, "1000 Years Ago...",
                   fontsize=20, ha='center', color='#888866', alpha=show_p, zorder=50)

            # Beautiful peaceful village
            ax.add_patch(patches.Rectangle((0, 0), WIDTH, HEIGHT * 0.3, color='#3a5a30', zorder=2))

            # Sun
            ax.add_patch(patches.Circle((WIDTH * 0.8, HEIGHT * 0.85), 60,
                        color='#FFD700', alpha=0.7, zorder=3))

            # Young version (shown as a noble frog, before corruption)
            young_villain = Frog(WIDTH * 0.5, HEIGHT * 0.25, 1.3)
            young_villain.emotion = Emotion.HAPPY
            young_villain.has_crown = True
            young_villain.set_glow(True, '#00FF7F', 0.3)  # He was green/good!
            young_villain.render(ax, local)

            ax.text(WIDTH/2, HEIGHT * 0.6, "He was once the Emerald Guardian...",
                   fontsize=22, ha='center', color='#90EE90', alpha=show_p, style='italic', zorder=50)

        # Phase 2: Tragedy strikes (35-60%)
        elif p < 0.6:
            tragedy_p = (p - 0.35) / 0.25

            # Darkening sky
            darkness = tragedy_p * 0.5
            ax.set_facecolor(f'#{int(42 - darkness*30):02x}{int(32 - darkness*25):02x}{int(21 - darkness*15):02x}')

            # Fire and destruction
            for i in range(10):
                fire_x = np.random.uniform(0, WIDTH)
                fire_y = np.random.uniform(HEIGHT * 0.1, HEIGHT * 0.4)
                ax.add_patch(patches.Circle((fire_x, fire_y), 20 + np.random.rand() * 30,
                            color='#FF4500', alpha=0.3 + tragedy_p * 0.3, zorder=10))

            # His love dying in his arms
            villain = Frog(WIDTH * 0.45, HEIGHT * 0.2, 1.2)
            villain.emotion = Emotion.SAD
            villain.render(ax, local)

            # Fallen loved one
            fallen = Frog(WIDTH * 0.55, HEIGHT * 0.15, 0.9, 'princess')
            fallen.emotion = Emotion.SAD
            fallen.alpha = 0.5 - tragedy_p * 0.3
            fallen.render(ax, local)

            ax.text(WIDTH/2, HEIGHT * 0.7, "But he lost everything he loved...",
                   fontsize=22, ha='center', color='#FF6666', alpha=tragedy_p, style='italic', zorder=50)

            if local % 8 == 0:
                ctx['particles'].emit_fire(np.random.uniform(100, WIDTH-100), HEIGHT * 0.3, 1.0)

        # Phase 3: The corruption (60-85%)
        elif p < 0.85:
            corrupt_p = (p - 0.6) / 0.25

            # Dark, twisted background
            ax.set_facecolor('#0a0510')

            # Swirling darkness
            for i in range(15):
                angle = (i / 15) * 2 * np.pi + local * 0.02
                dist = 150 + corrupt_p * 100 + np.sin(local * 0.05 + i) * 30
                sx = WIDTH * 0.5 + np.cos(angle) * dist
                sy = HEIGHT * 0.4 + np.sin(angle) * dist * 0.5
                ax.add_patch(patches.Circle((sx, sy), 30 + corrupt_p * 20,
                            color='#2d0a4e', alpha=0.4, zorder=5))

            # Transforming - frog becoming The Dark One
            if corrupt_p < 0.5:
                # Still somewhat frog-like
                trans_frog = Frog(WIDTH * 0.5, HEIGHT * 0.35, 1.3 + corrupt_p * 0.5)
                trans_frog.emotion = Emotion.ANGRY
                trans_frog.body_color = f'#{int(50 - corrupt_p * 80):02x}{int(205 - corrupt_p * 200):02x}{int(50 - corrupt_p * 80):02x}'
                trans_frog.set_glow(True, '#4B0082', corrupt_p)
                trans_frog.render(ax, local)
            else:
                # Becoming The Dark One
                dark_one = TheDarkOne(WIDTH * 0.5, HEIGHT * 0.4, 1.5 + (corrupt_p - 0.5) * 1.5)
                dark_one.alpha = (corrupt_p - 0.5) * 2
                dark_one.render(ax, local)

            ax.text(WIDTH/2, HEIGHT * 0.8, "Grief twisted his heart to darkness...",
                   fontsize=22, ha='center', color='#8B0000', alpha=corrupt_p, style='italic', zorder=50)

            ctx['camera'].shake(corrupt_p * 10, 0.95)

        # Phase 4: The monster he became (85-100%)
        else:
            monster_p = (p - 0.85) / 0.15

            ax.set_facecolor('#050008')

            # Full Dark One in all his terrible glory
            dark_one = TheDarkOne(WIDTH * 0.5, HEIGHT * 0.45, 2.5)
            dark_one.render(ax, local)

            # Menacing aura
            for i in range(8):
                ax.add_patch(patches.Circle((WIDTH * 0.5, HEIGHT * 0.45), 200 + i * 40,
                            fill=False, edgecolor='#4B0082', linewidth=3,
                            alpha=0.3 - i * 0.03, zorder=3))

            # Dark particles
            if local % 4 == 0:
                ctx['particles'].emit_dark_energy(WIDTH * 0.5, HEIGHT * 0.45, 1.5)

            ax.text(WIDTH/2, HEIGHT * 0.85, "And swore to destroy all hope...",
                   fontsize=24, ha='center', color='#FF0000', alpha=monster_p, fontweight='bold', zorder=50)


class EpicClimaxScene(Scene):
    """The final clash - Eli vs Dark One with MAXIMUM drama"""
    def render(self, ax, frame: int, ctx: dict):
        p = self.progress(frame)
        local = frame - self.start

        # Apocalyptic sky
        for i in range(10):
            y = HEIGHT * i / 10
            t = i / 10
            r = int(lerp(20, 80, t) + np.sin(local * 0.05) * 10)
            g = int(lerp(5, 20, t))
            b = int(lerp(30, 60, t))
            ax.add_patch(patches.Rectangle((0, y), WIDTH, HEIGHT/10 + 1,
                        color=f'#{clamp(r, 0, 255):02x}{clamp(g, 0, 255):02x}{clamp(b, 0, 255):02x}', zorder=1))

        # Epic lightning
        if local % 45 < 2:
            ax.add_patch(patches.Rectangle((0, 0), WIDTH, HEIGHT, color='white', alpha=0.5, zorder=500))
            ctx['camera'].shake(15, 0.9)

        # Floating debris
        np.random.seed(42)
        for i in range(20):
            dx = (np.random.rand() * WIDTH + local * (0.5 + np.random.rand())) % WIDTH
            dy = np.random.rand() * HEIGHT * 0.6 + HEIGHT * 0.1
            size = 10 + np.random.rand() * 20
            ax.add_patch(patches.Polygon([
                [dx, dy], [dx + size, dy + size/2], [dx + size/2, dy + size]
            ], color='#333', alpha=0.6, zorder=5))

        # Phase 1: Both charging up (0-30%)
        if p < 0.3:
            charge_p = p / 0.3

            # Eli on left, powering up
            eli = Frog(WIDTH * 0.25, HEIGHT * 0.35, 1.3 + charge_p * 0.3)
            eli.emotion = Emotion.POWERFUL
            eli.has_crown = True
            eli.set_glow(True, '#00FF7F', charge_p)
            eli.render(ax, local)

            # Green energy spiraling around Eli
            for i in range(12):
                angle = (i / 12) * 2 * np.pi + local * 0.1
                dist = 60 + charge_p * 80 + np.sin(local * 0.2 + i) * 20
                ex = WIDTH * 0.25 + np.cos(angle) * dist
                ey = HEIGHT * 0.35 + np.sin(angle) * dist * 0.6
                ax.scatter([ex], [ey], c='#00FF7F', s=30 + charge_p * 50, alpha=0.7, zorder=40)

            # Dark One on right
            dark_one = TheDarkOne(WIDTH * 0.75, HEIGHT * 0.45, 2.0 + charge_p * 0.5)
            dark_one.render(ax, local)

            # Purple energy around Dark One
            for i in range(12):
                angle = (i / 12) * 2 * np.pi - local * 0.08
                dist = 80 + charge_p * 100
                vx = WIDTH * 0.75 + np.cos(angle) * dist
                vy = HEIGHT * 0.45 + np.sin(angle) * dist * 0.5
                ax.scatter([vx], [vy], c='#8B0000', s=40 + charge_p * 60, alpha=0.7, zorder=40)

            # "THIS ENDS NOW" text
            if charge_p > 0.5:
                ax.text(WIDTH/2, HEIGHT * 0.85, "THIS ENDS NOW!",
                       fontsize=36, ha='center', color='#FFD700',
                       alpha=(charge_p - 0.5) * 2, fontweight='bold', zorder=100)

        # Phase 2: BEAM CLASH! (30-70%)
        elif p < 0.7:
            clash_p = (p - 0.3) / 0.4

            # Eli firing green beam
            eli = Frog(WIDTH * 0.2, HEIGHT * 0.35, 1.5)
            eli.emotion = Emotion.POWERFUL
            eli.has_crown = True
            eli.set_glow(True, '#00FF7F', 1.0)
            eli.render(ax, local)

            # Dark One firing dark beam
            dark_one = TheDarkOne(WIDTH * 0.8, HEIGHT * 0.45, 2.2)
            dark_one.render(ax, local)

            # THE BEAMS!
            clash_x = WIDTH * 0.5 + np.sin(local * 0.1) * 30 * (0.5 - abs(clash_p - 0.5))

            # Green beam (Eli's)
            beam_height = 80
            ax.add_patch(patches.Polygon([
                [WIDTH * 0.25, HEIGHT * 0.35],
                [clash_x, HEIGHT * 0.4 + beam_height/2],
                [clash_x, HEIGHT * 0.4 - beam_height/2]
            ], color='#00FF7F', alpha=0.8, zorder=60))
            ax.add_patch(patches.Polygon([
                [WIDTH * 0.25, HEIGHT * 0.35],
                [clash_x, HEIGHT * 0.4 + beam_height/3],
                [clash_x, HEIGHT * 0.4 - beam_height/3]
            ], color='#90EE90', alpha=0.9, zorder=61))

            # Dark beam
            ax.add_patch(patches.Polygon([
                [WIDTH * 0.75, HEIGHT * 0.45],
                [clash_x, HEIGHT * 0.4 + beam_height/2],
                [clash_x, HEIGHT * 0.4 - beam_height/2]
            ], color='#4B0082', alpha=0.8, zorder=60))
            ax.add_patch(patches.Polygon([
                [WIDTH * 0.75, HEIGHT * 0.45],
                [clash_x, HEIGHT * 0.4 + beam_height/3],
                [clash_x, HEIGHT * 0.4 - beam_height/3]
            ], color='#8B0000', alpha=0.9, zorder=61))

            # Clash point explosion
            for i in range(8):
                ax.add_patch(patches.Circle((clash_x, HEIGHT * 0.4), 30 + i * 15,
                            fill=False, edgecolor='#FFFFFF', linewidth=3,
                            alpha=0.5 - i * 0.05, zorder=70))

            # Massive particles at clash
            if local % 2 == 0:
                ctx['particles'].emit_magic(clash_x + np.random.randn() * 30,
                                           HEIGHT * 0.4 + np.random.randn() * 30, 'white', 2.0)

            # Screen shake throughout
            ctx['camera'].shake(20, 0.92)

            # Eli winning towards the end
            if clash_p > 0.7:
                win_p = (clash_p - 0.7) / 0.3
                ax.text(WIDTH/2, HEIGHT * 0.1, "FOR SAGE! FOR EVERYONE!",
                       fontsize=28, ha='center', color='#00FF7F',
                       alpha=win_p, fontweight='bold', zorder=100)

        # Phase 3: Eli WINS - massive explosion (70-100%)
        else:
            win_p = (p - 0.7) / 0.3

            # Screen getting brighter
            ax.set_facecolor(f'#{int(20 + win_p * 200):02x}{int(50 + win_p * 200):02x}{int(30 + win_p * 200):02x}')

            # Eli victorious
            eli = Frog(WIDTH * 0.4, HEIGHT * 0.35, 1.5 + win_p * 0.3)
            eli.emotion = Emotion.POWERFUL
            eli.has_crown = True
            eli.set_glow(True, '#FFD700', 1.0)
            eli.render(ax, local)

            # Dark One disintegrating
            if win_p < 0.6:
                dark_one = TheDarkOne(WIDTH * 0.7 + win_p * 50, HEIGHT * 0.45, 2.0 - win_p * 1.5)
                dark_one.alpha = 1 - win_p * 1.5
                dark_one.render(ax, local)

            # MASSIVE explosion rings
            for i in range(15):
                ring_r = win_p * 500 + i * 40
                ax.add_patch(patches.Circle((WIDTH * 0.6, HEIGHT * 0.4), ring_r,
                            fill=False, edgecolor='#FFD700', linewidth=5 - i * 0.3,
                            alpha=max(0, 0.8 - win_p - i * 0.04), zorder=50))

            # Victory particles everywhere
            if local % 2 == 0:
                ctx['particles'].emit_magic(np.random.uniform(100, WIDTH-100),
                                           np.random.uniform(100, HEIGHT-100), 'gold', 2.0)

            # "VICTORY" text
            if win_p > 0.5:
                text_scale = 1 + np.sin(local * 0.3) * 0.1
                ax.text(WIDTH/2, HEIGHT/2, "VICTORY",
                       fontsize=int(80 * text_scale), ha='center', va='center',
                       color='#FFD700', alpha=(win_p - 0.5) * 2, fontweight='bold', zorder=200)

            ctx['camera'].shake(30 * (1 - win_p), 0.9)


class FlashbackScene(Scene):
    """Pixar-style emotional flashback sequence"""
    def __init__(self, start: int, duration: int, memory_type: str = 'happy'):
        super().__init__(start, duration)
        self.memory_type = memory_type  # 'happy', 'sad', 'origin'

    def render(self, ax, frame: int, ctx: dict):
        p = self.progress(frame)
        local = frame - self.start

        # Dreamy sepia/desaturated look
        if self.memory_type == 'happy':
            bg_color = '#FFF8DC'  # Warm sepia
            vignette_color = '#DEB887'
        elif self.memory_type == 'sad':
            bg_color = '#E0E0E0'  # Cold grey
            vignette_color = '#808080'
        else:
            bg_color = '#E6E6FA'  # Mystical lavender
            vignette_color = '#9370DB'

        ax.set_facecolor(bg_color)

        # Vignette effect for dreamy feel
        for i in range(8):
            t = i / 8
            vignette = patches.Rectangle((0, 0), WIDTH, HEIGHT,
                                        fill=False, edgecolor=vignette_color,
                                        linewidth=80 * (1 - t), alpha=0.1, zorder=100)
            ax.add_patch(vignette)

        # Floating memory particles
        np.random.seed(int(self.start))
        for i in range(30):
            px = np.random.uniform(0, WIDTH)
            py = (np.random.uniform(0, HEIGHT) + local * 0.5) % HEIGHT
            size = np.random.uniform(5, 15)
            alpha = 0.3 + 0.2 * np.sin(local * 0.02 + i)
            ax.scatter([px], [py], c='white', s=size, alpha=alpha, zorder=50)

        # Transition in/out ripple effect
        if p < 0.15:
            ripple_alpha = 1 - p / 0.15
            for ring in range(10):
                radius = (1 - p / 0.15) * WIDTH * (0.1 + ring * 0.1)
                ax.add_patch(patches.Circle((WIDTH/2, HEIGHT/2), radius,
                            fill=False, edgecolor='white',
                            linewidth=5, alpha=ripple_alpha * 0.5, zorder=200))
        elif p > 0.85:
            ripple_alpha = (p - 0.85) / 0.15
            for ring in range(10):
                radius = ripple_alpha * WIDTH * (0.1 + ring * 0.1)
                ax.add_patch(patches.Circle((WIDTH/2, HEIGHT/2), radius,
                            fill=False, edgecolor='white',
                            linewidth=5, alpha=ripple_alpha * 0.5, zorder=200))

        # Memory content based on type
        if self.memory_type == 'happy':
            # Young Eli playing at the pond
            young_eli = Frog(WIDTH * 0.4, HEIGHT * 0.25, 0.7)
            young_eli.emotion = Emotion.HAPPY
            young_eli.render(ax, local)
            # Parent frogs watching
            parent1 = Frog(WIDTH * 0.2, HEIGHT * 0.28, 1.0, 'green', 'Father')
            parent1.emotion = Emotion.HAPPY
            parent1.render(ax, local)
            parent2 = Frog(WIDTH * 0.65, HEIGHT * 0.26, 0.9, 'green', 'Mother')
            parent2.emotion = Emotion.LOVE
            parent2.render(ax, local)
            # Hearts floating
            if local % 30 < 15:
                ctx['particles'].emit_magic(WIDTH * 0.5, HEIGHT * 0.3, 'gold', 0.3)

        elif self.memory_type == 'sad':
            # The day the darkness came
            young_eli = Frog(WIDTH * 0.5, HEIGHT * 0.25, 0.8)
            young_eli.emotion = Emotion.SAD
            young_eli.render(ax, local)
            # Dark clouds approaching
            for i in range(5):
                cloud_x = WIDTH * (0.2 + i * 0.15) + np.sin(local * 0.02) * 20
                cloud_y = HEIGHT * 0.7
                cloud = patches.Ellipse((cloud_x, cloud_y), 150, 60,
                                       color='#333333', alpha=0.7, zorder=30)
                ax.add_patch(cloud)
            if local % 20 == 0:
                ctx['particles'].emit_dark_energy(WIDTH * 0.5, HEIGHT * 0.6, 0.5)

        else:  # origin - the prophecy being told
            # Ancient frog elder
            elder = Frog(WIDTH * 0.5, HEIGHT * 0.3, 1.5, 'golden', 'Elder')
            elder.set_glow(True, '#FFD700', 0.5)
            elder.render(ax, local)
            # Mystical runes floating
            runes = ['◊', '○', '△', '☆', '◇']
            for i, rune in enumerate(runes):
                rune_x = WIDTH * 0.2 + i * WIDTH * 0.15
                rune_y = HEIGHT * 0.6 + np.sin(local * 0.05 + i) * 30
                ax.text(rune_x, rune_y, rune, fontsize=40,
                       color='#FFD700', alpha=0.7 + 0.3 * np.sin(local * 0.1 + i),
                       ha='center', va='center', zorder=40)

        # "Memory" label
        if p > 0.1 and p < 0.9:
            ax.text(WIDTH * 0.1, HEIGHT * 0.92, "Memory...",
                   fontsize=18, color='#888888', alpha=0.7, style='italic')


class ProphecyScene(Scene):
    """Ancient prophecy visualization with glowing runes"""
    def render(self, ax, frame: int, ctx: dict):
        p = self.progress(frame)
        local = frame - self.start
        ax.set_facecolor('#0a0014')

        # Starfield
        np.random.seed(777)
        for i in range(150):
            sx = np.random.uniform(0, WIDTH)
            sy = np.random.uniform(0, HEIGHT)
            twinkle = 0.5 + 0.5 * np.sin(local * 0.03 + i)  # Range [0, 1] - safe for alpha
            ax.scatter([sx], [sy], c='white', s=twinkle * 10, alpha=clamp(twinkle * 0.5, 0.01, 1), zorder=1)

        # Central prophecy tablet
        tablet = patches.FancyBboxPatch(
            (WIDTH * 0.25, HEIGHT * 0.2), WIDTH * 0.5, HEIGHT * 0.6,
            boxstyle="round,pad=0.02,rounding_size=20",
            facecolor='#1a1a3a', edgecolor='#FFD700',
            linewidth=3, alpha=0.9, zorder=10
        )
        ax.add_patch(tablet)

        # Glowing border
        glow_intensity = 0.5 + 0.3 * np.sin(local * 0.05)
        for i in range(3):
            glow_alpha = clamp(glow_intensity * (0.3 - i * 0.1), 0.01, 1)
            glow_tablet = patches.FancyBboxPatch(
                (WIDTH * 0.25 - i * 5, HEIGHT * 0.2 - i * 5),
                WIDTH * 0.5 + i * 10, HEIGHT * 0.6 + i * 10,
                boxstyle="round,pad=0.02,rounding_size=20",
                fill=False, edgecolor='#FFD700',
                linewidth=2, alpha=glow_alpha, zorder=9
            )
            ax.add_patch(glow_tablet)

        # Prophecy text appearing letter by letter
        # THE COMPLETE PROPHECY - includes foreshadowing of HUUTERS!
        prophecy_lines = [
            "When darkness rises from the deep,",
            "And shadows make the brave men weep,",
            "A child of pond, transformed by fate,",
            "Shall rise to meet the darkest hate.",
            "",
            "The Emerald Guardian shall arise,",
            "With courage true and ancient eyes,",
            "To vanquish evil, restore the light,",
            "And bring an end to endless night.",
            "",
            "But first, where seven ley lines meet,",  # HUUTERS FORESHADOWING!
            "A sanctuary his soul shall greet,",      # The sacred restaurant
            "The Last Starborn waits within,",        # BELLA!
            "Their love, the key that lets light in.", # Their cosmic love
            "",
            "Through fire and void, on celestial steed,",  # THUNDER!
            "Their bond shall prove the final deed.",       # The dangerous ride
        ]

        chars_per_frame = 0.8
        total_chars = int(local * chars_per_frame)
        current_char = 0
        y_pos = HEIGHT * 0.72

        for line in prophecy_lines:
            if current_char + len(line) <= total_chars:
                displayed = line
            elif current_char < total_chars:
                displayed = line[:total_chars - current_char]
            else:
                displayed = ""

            if displayed:
                ax.text(WIDTH * 0.5, y_pos, displayed,
                       fontsize=22, ha='center', va='center',
                       color='#FFD700', fontfamily='serif', zorder=20)
            current_char += len(line)
            y_pos -= 45

        # Floating runes around tablet
        rune_symbols = ['☾', '☀', '★', '⚡', '✧', '◈', '❖', '✦']
        for i, rune in enumerate(rune_symbols):
            angle = (i / len(rune_symbols)) * 2 * np.pi + local * 0.01
            dist = 280 + np.sin(local * 0.02 + i) * 30
            rx = WIDTH * 0.5 + np.cos(angle) * dist
            ry = HEIGHT * 0.5 + np.sin(angle) * dist * 0.5
            rune_alpha = clamp(0.5 + 0.5 * np.sin(local * 0.05 + i * 0.7), 0.01, 1)
            ax.text(rx, ry, rune, fontsize=35, ha='center', va='center',
                   color='#9370DB', alpha=rune_alpha, zorder=15)

        if local % 15 == 0:
            ctx['particles'].emit_magic(WIDTH * 0.5 + np.random.randn() * 200,
                                        HEIGHT * 0.5 + np.random.randn() * 100, 'gold', 0.5)


class TrainingMontageScene(Scene):
    """Epic training montage showing Eli's growth"""
    def __init__(self, start: int, duration: int):
        super().__init__(start, duration)
        self.stages = [
            ('jumping', 'Learning to Jump'),
            ('swimming', 'Mastering the Waters'),
            ('magic', 'Channeling Inner Power'),
            ('combat', 'Combat Training'),
            ('meditation', 'Finding Inner Peace'),
        ]

    def render(self, ax, frame: int, ctx: dict):
        p = self.progress(frame)
        local = frame - self.start

        # Determine current training stage
        stage_idx = min(int(p * len(self.stages)), len(self.stages) - 1)
        stage_progress = (p * len(self.stages)) % 1
        stage_type, stage_name = self.stages[stage_idx]

        # Background based on training
        if stage_type == 'jumping':
            ax.set_facecolor('#87CEEB')
            # Grass field
            grass = patches.Rectangle((0, 0), WIDTH, HEIGHT * 0.35,
                                      color='#228B22', zorder=5)
            ax.add_patch(grass)
            # Hurdles
            for i in range(5):
                hx = WIDTH * (0.2 + i * 0.15)
                hurdle = patches.Rectangle((hx - 10, HEIGHT * 0.35), 20, 50 + i * 20,
                                          color='#8B4513', zorder=6)
                ax.add_patch(hurdle)
            # Eli jumping over hurdles
            jump_phase = (local * 0.1) % (2 * np.pi)
            eli_x = WIDTH * (0.15 + (local * 0.003) % 0.7)
            eli_y = HEIGHT * 0.35 + abs(np.sin(jump_phase)) * 120
            eli = Frog(eli_x, eli_y, 1.0)
            eli.emotion = Emotion.DETERMINED
            eli.render(ax, local)

        elif stage_type == 'swimming':
            ax.set_facecolor('#1E90FF')
            # Underwater scene
            for i in range(15):
                bubble_x = np.random.uniform(0, WIDTH)
                bubble_y = (local * 2 + i * 60) % HEIGHT
                ax.add_patch(patches.Circle((bubble_x, bubble_y), 10 + i % 5,
                            color='white', alpha=0.3, zorder=10))
            # Eli swimming
            swim_wave = np.sin(local * 0.15) * 50
            eli = Frog(WIDTH * 0.5 + swim_wave, HEIGHT * 0.4 + np.cos(local * 0.1) * 30, 1.0)
            eli.emotion = Emotion.DETERMINED
            eli.render(ax, local)

        elif stage_type == 'magic':
            ax.set_facecolor('#1a0a3a')
            # Magical training ground
            for i in range(20):
                sx = np.random.uniform(0, WIDTH)
                sy = np.random.uniform(HEIGHT * 0.5, HEIGHT)
                ax.scatter([sx], [sy], c='white', s=np.random.rand() * 15, alpha=0.5)
            # Eli channeling power
            eli = Frog(WIDTH * 0.5, HEIGHT * 0.3, 1.2)
            eli.emotion = Emotion.POWERFUL
            glow_intensity = 0.5 + 0.5 * np.sin(local * 0.1)
            eli.set_glow(True, '#00FF7F', glow_intensity)
            eli.render(ax, local)
            # Magic circles
            for i in range(3):
                radius = 100 + i * 50 + np.sin(local * 0.05 + i) * 20
                circle = patches.Circle((WIDTH * 0.5, HEIGHT * 0.3), radius,
                                        fill=False, edgecolor='#00FF7F',
                                        linewidth=2, alpha=0.5 - i * 0.15, zorder=8)
                ax.add_patch(circle)
            if local % 5 == 0:
                ctx['particles'].emit_magic(WIDTH * 0.5, HEIGHT * 0.3, 'green', 1.5)

        elif stage_type == 'combat':
            ax.set_facecolor('#2a1a1a')
            # Dojo-like setting
            floor = patches.Rectangle((0, 0), WIDTH, HEIGHT * 0.3,
                                      color='#8B4513', zorder=5)
            ax.add_patch(floor)
            # Eli fighting training dummies
            eli = Frog(WIDTH * 0.4, HEIGHT * 0.25, 1.0)
            eli.emotion = Emotion.DETERMINED
            if local % 40 < 20:
                eli.emotion = Emotion.ANGRY
            eli.render(ax, local)
            # Mentor watching
            sage = WiseTurtle(WIDTH * 0.8, HEIGHT * 0.25, 1.0)
            sage.render(ax, local)
            if local % 30 == 0:
                ctx['particles'].emit_magic(WIDTH * 0.4, HEIGHT * 0.25, 'green', 0.8)
                ctx['camera'].shake(5, 0.9)

        else:  # meditation
            ax.set_facecolor('#0a1a2a')
            # Peaceful night scene
            np.random.seed(456)
            for i in range(100):
                ax.scatter([np.random.rand() * WIDTH], [np.random.rand() * HEIGHT],
                          c='white', s=np.random.rand() * 10, alpha=0.6)
            # Mountain silhouette
            ax.add_patch(patches.Polygon([
                [0, HEIGHT * 0.3], [WIDTH * 0.3, HEIGHT * 0.6],
                [WIDTH * 0.6, HEIGHT * 0.4], [WIDTH, HEIGHT * 0.5], [WIDTH, HEIGHT * 0.3]
            ], color='#1a1a2a', zorder=5))
            # Eli meditating
            eli = Frog(WIDTH * 0.5, HEIGHT * 0.35, 1.0)
            eli.emotion = Emotion.NEUTRAL
            eli.set_glow(True, '#ADD8E6', 0.3 + 0.2 * np.sin(local * 0.03))
            eli.render(ax, local)
            # Energy flowing upward
            if local % 10 == 0:
                ctx['particles'].emit_magic(WIDTH * 0.5, HEIGHT * 0.35, 'blue', 0.5)

        # Stage title
        title_alpha = 1 - abs(stage_progress - 0.5) * 2 if stage_progress < 0.2 else 0
        title_alpha = max(0, min(1, (1 - stage_progress * 5) if stage_progress < 0.2 else 0))
        if title_alpha > 0:
            ax.text(WIDTH * 0.5, HEIGHT * 0.85, stage_name.upper(),
                   fontsize=36, ha='center', fontweight='bold',
                   color='white', alpha=title_alpha, zorder=100)

        # Progress bar
        bar_width = WIDTH * 0.6
        ax.add_patch(patches.Rectangle((WIDTH * 0.2, HEIGHT * 0.05), bar_width, 15,
                    color='#333333', zorder=100))
        ax.add_patch(patches.Rectangle((WIDTH * 0.2, HEIGHT * 0.05), bar_width * p, 15,
                    color='#FFD700', zorder=101))
        ax.text(WIDTH * 0.5, HEIGHT * 0.08, "TRAINING PROGRESS",
               fontsize=12, ha='center', color='white', zorder=102)


class SacrificeScene(Scene):
    """Emotional sacrifice and resurrection scene"""
    def __init__(self, start: int, duration: int, is_sacrifice: bool = True):
        super().__init__(start, duration)
        self.is_sacrifice = is_sacrifice

    def render(self, ax, frame: int, ctx: dict):
        p = self.progress(frame)
        local = frame - self.start
        ax.set_facecolor('#0a0a15')

        if self.is_sacrifice:
            # Dark stormy battlefield
            for i in range(30):
                sx = np.random.uniform(0, WIDTH)
                sy = np.random.uniform(HEIGHT * 0.6, HEIGHT)
                ax.scatter([sx], [sy], c='white', s=2, alpha=0.3)

            # Wounded friends in background
            luna = Frog(WIDTH * 0.2, HEIGHT * 0.2, 0.8, 'princess', 'Luna')
            luna.emotion = Emotion.SAD
            luna.alpha = 0.7
            luna.render(ax, local)

            spark = Dragonfly(WIDTH * 0.3, HEIGHT * 0.3, 0.6)
            spark.alpha = 0.7
            spark.render(ax, local)

            # Dark One threatening
            dark_one = TheDarkOne(WIDTH * 0.8, HEIGHT * 0.5, 2.0)
            dark_one.render(ax, local)

            # Eli making the sacrifice
            eli = Frog(WIDTH * 0.5, HEIGHT * 0.25, 1.2)
            if p < 0.5:
                eli.emotion = Emotion.DETERMINED
                eli.set_glow(True, '#00FF7F', p * 2)
            else:
                eli.emotion = Emotion.POWERFUL
                eli.set_glow(True, '#FFFFFF', 1.0)

            # Rising into the air
            eli_y = HEIGHT * 0.25 + p * HEIGHT * 0.3
            eli.y = eli_y
            eli.render(ax, local)

            # Sacrificial light beam
            if p > 0.3:
                beam_alpha = (p - 0.3) / 0.7
                beam = patches.Rectangle((WIDTH * 0.45, 0), WIDTH * 0.1, HEIGHT,
                                         color='white', alpha=beam_alpha * 0.5, zorder=50)
                ax.add_patch(beam)
                ctx['particles'].emit_magic(WIDTH * 0.5, eli_y, 'white', 2.0)

            # Screen flash at climax
            if p > 0.9:
                flash_alpha = (p - 0.9) / 0.1
                ax.add_patch(patches.Rectangle((0, 0), WIDTH, HEIGHT,
                            color='white', alpha=flash_alpha, zorder=200))

        else:  # Resurrection
            # Gradual light returning
            bg_brightness = int(10 + p * 100)
            ax.set_facecolor(f'#{bg_brightness:02x}{bg_brightness:02x}{bg_brightness + 20:02x}')

            # Celestial background
            for i in range(50):
                sx = np.random.uniform(0, WIDTH)
                sy = np.random.uniform(HEIGHT * 0.5, HEIGHT)
                ax.scatter([sx], [sy], c='white', s=5 + p * 10, alpha=p, zorder=1)

            # Friends looking up with hope
            luna = Frog(WIDTH * 0.3, HEIGHT * 0.2, 0.9, 'princess', 'Luna')
            luna.emotion = Emotion.SHOCKED if p < 0.5 else Emotion.HAPPY
            luna.render(ax, local)

            spark = Dragonfly(WIDTH * 0.25, HEIGHT * 0.35, 0.7)
            spark.render(ax, local)

            sage = WiseTurtle(WIDTH * 0.7, HEIGHT * 0.22, 1.0)
            sage.render(ax, local)

            # Eli descending from light
            if p > 0.3:
                eli_progress = (p - 0.3) / 0.7
                eli_y = HEIGHT * 0.8 - eli_progress * HEIGHT * 0.5
                eli = Frog(WIDTH * 0.5, eli_y, 1.3)
                eli.emotion = Emotion.POWERFUL
                eli.has_crown = True
                eli.set_glow(True, '#FFD700', 1.0 - eli_progress * 0.3)
                eli.render(ax, local)

                # Angelic light rays
                for i in range(12):
                    angle = (i / 12) * np.pi + np.pi / 2
                    ray_len = 200 + 100 * eli_progress
                    rx = WIDTH * 0.5 + np.cos(angle) * 50
                    ry = eli_y
                    rx2 = rx + np.cos(angle) * ray_len
                    ry2 = ry + np.sin(angle) * ray_len
                    ax.plot([rx, rx2], [ry, ry2], color='#FFD700',
                           linewidth=3, alpha=0.5 * (1 - eli_progress * 0.5), zorder=40)

            if local % 8 == 0:
                ctx['particles'].emit_magic(WIDTH * 0.5, HEIGHT * 0.5, 'gold', 1.5)

            # "THE PROPHECY IS FULFILLED" text
            if p > 0.7:
                text_alpha = (p - 0.7) / 0.3
                ax.text(WIDTH * 0.5, HEIGHT * 0.9, "THE PROPHECY IS FULFILLED",
                       fontsize=40, ha='center', fontweight='bold',
                       color='#FFD700', alpha=text_alpha, zorder=100)


class ArmyBattleScene(Scene):
    """Epic army vs army battle scene"""
    def render(self, ax, frame: int, ctx: dict):
        p = self.progress(frame)
        local = frame - self.start
        ax.set_facecolor('#1a0a0a')

        # Dramatic red sky
        for i in range(5):
            cloud_x = (local * 0.5 + i * 400) % (WIDTH + 400) - 200
            cloud_y = HEIGHT * (0.75 + i * 0.04)
            cloud = patches.Ellipse((cloud_x, cloud_y), 350, 80,
                                   color='#2a0a0a', alpha=0.7, zorder=2)
            ax.add_patch(cloud)

        # Battle ground
        ground = patches.Rectangle((0, 0), WIDTH, HEIGHT * 0.35,
                                   color='#2a1a10', zorder=5)
        ax.add_patch(ground)

        # Good army (left side) - 25 frogs
        np.random.seed(888)
        for i in range(25):
            fx = WIDTH * 0.1 + np.random.uniform(0, WIDTH * 0.25)
            fy = HEIGHT * 0.1 + np.random.uniform(0, HEIGHT * 0.2)
            frog = Frog(fx + np.sin(local * 0.1 + i) * 5, fy, 0.4 + np.random.rand() * 0.3)
            frog.emotion = Emotion.DETERMINED if np.random.rand() > 0.3 else Emotion.ANGRY
            frog.facing = 1
            frog.render(ax, local)

        # Evil army (right side) - dark creatures
        for i in range(20):
            ex = WIDTH * 0.65 + np.random.uniform(0, WIDTH * 0.25)
            ey = HEIGHT * 0.1 + np.random.uniform(0, HEIGHT * 0.2)
            # Dark shadow creatures
            creature = patches.Ellipse((ex + np.sin(local * 0.08 + i) * 8, ey),
                                       30 + np.random.rand() * 20, 20 + np.random.rand() * 15,
                                       color='#2d0a4e', alpha=0.8, zorder=10)
            ax.add_patch(creature)
            # Evil eyes
            ax.scatter([ex - 5, ex + 5], [ey + 5, ey + 5],
                      c='#FF0000', s=10, alpha=0.9, zorder=11)

        # Hero Eli in the center leading the charge
        eli = Frog(WIDTH * 0.45, HEIGHT * 0.22, 1.3)
        eli.emotion = Emotion.POWERFUL
        eli.set_glow(True, '#00FF7F', 0.7 + 0.3 * np.sin(local * 0.1))
        eli.render(ax, local)

        # Allied characters
        luna = Frog(WIDTH * 0.35, HEIGHT * 0.2, 0.9, 'princess', 'Luna')
        luna.emotion = Emotion.DETERMINED
        luna.render(ax, local)

        spark = Dragonfly(WIDTH * 0.4, HEIGHT * 0.4, 0.8)
        spark.render(ax, local)

        # Battle effects
        if local % 10 == 0:
            # Random explosions
            exp_x = np.random.uniform(WIDTH * 0.4, WIDTH * 0.6)
            exp_y = np.random.uniform(HEIGHT * 0.15, HEIGHT * 0.3)
            ctx['particles'].emit_explosion(exp_x, exp_y, 0.8)
            ctx['camera'].shake(8, 0.92)

        if local % 15 == 0:
            # Magic blasts
            ctx['particles'].emit_magic(WIDTH * 0.45, HEIGHT * 0.22, 'green', 1.0)

        # War cry text
        if p < 0.1:
            text_alpha = p / 0.1
            ax.text(WIDTH * 0.5, HEIGHT * 0.7, "FOR THE LIGHT!",
                   fontsize=50, ha='center', fontweight='bold',
                   color='#FFD700', alpha=text_alpha, zorder=100)

        # Battle progress bar
        good_progress = 0.3 + p * 0.5  # Heroes winning
        bar_width = WIDTH * 0.4
        ax.add_patch(patches.Rectangle((WIDTH * 0.3, HEIGHT * 0.92), bar_width, 20,
                    color='#FF0000', zorder=100))
        ax.add_patch(patches.Rectangle((WIDTH * 0.3, HEIGHT * 0.92), bar_width * good_progress, 20,
                    color='#00FF00', zorder=101))


class CoronationScene(Scene):
    """Grand coronation and celebration finale"""
    def render(self, ax, frame: int, ctx: dict):
        p = self.progress(frame)
        local = frame - self.start
        ax.set_facecolor('#FFE4B5')

        # Sunny celebration day
        # Sun
        sun = patches.Circle((WIDTH * 0.8, HEIGHT * 0.85), 80,
                            color='#FFD700', zorder=3)
        ax.add_patch(sun)
        for i in range(12):
            angle = (i / 12) * 2 * np.pi + local * 0.01
            ray_len = 100 + np.sin(local * 0.05 + i) * 20
            rx = WIDTH * 0.8 + np.cos(angle) * ray_len
            ry = HEIGHT * 0.85 + np.sin(angle) * ray_len
            ax.plot([WIDTH * 0.8, rx], [HEIGHT * 0.85, ry],
                   color='#FFD700', linewidth=4, alpha=0.5, zorder=2)

        # Decorated grass field
        grass = patches.Rectangle((0, 0), WIDTH, HEIGHT * 0.35,
                                  color='#32CD32', zorder=5)
        ax.add_patch(grass)

        # Flower decorations
        np.random.seed(321)
        for i in range(30):
            fx = np.random.uniform(0, WIDTH)
            fy = np.random.uniform(HEIGHT * 0.05, HEIGHT * 0.33)
            colors = ['#FF69B4', '#FFD700', '#FF6347', '#BA55D3']
            flower = patches.Circle((fx, fy), 8,
                                   color=colors[i % len(colors)], zorder=6)
            ax.add_patch(flower)

        # Grand stage/platform
        stage = patches.FancyBboxPatch(
            (WIDTH * 0.35, HEIGHT * 0.35), WIDTH * 0.3, HEIGHT * 0.08,
            boxstyle="round,pad=0.01,rounding_size=5",
            facecolor='#8B4513', edgecolor='#FFD700', linewidth=3, zorder=10
        )
        ax.add_patch(stage)

        # Eli being crowned
        eli = Frog(WIDTH * 0.5, HEIGHT * 0.42, 1.5)
        eli.emotion = Emotion.HAPPY
        eli.has_crown = p > 0.4
        eli.set_glow(True, '#FFD700', 0.5)
        eli.render(ax, local)

        # Crown descending animation
        if p < 0.4:
            crown_y = HEIGHT * 0.8 - p * HEIGHT * 0.35 / 0.4
            crown_points = [
                [WIDTH * 0.5 - 30, crown_y],
                [WIDTH * 0.5 - 25, crown_y + 25],
                [WIDTH * 0.5 - 15, crown_y + 12],
                [WIDTH * 0.5, crown_y + 35],
                [WIDTH * 0.5 + 15, crown_y + 12],
                [WIDTH * 0.5 + 25, crown_y + 25],
                [WIDTH * 0.5 + 30, crown_y],
            ]
            crown = patches.Polygon(crown_points, color='#FFD700', zorder=50)
            ax.add_patch(crown)
            for i in range(3):
                glow = patches.Circle((WIDTH * 0.5, crown_y + 15), 40 + i * 15,
                                      color='#FFD700', alpha=0.2 - i * 0.05, zorder=49)
                ax.add_patch(glow)

        # Crowd cheering (many frogs)
        for i in range(40):
            row = i // 10
            col = i % 10
            fx = WIDTH * (0.1 + col * 0.08)
            fy = HEIGHT * (0.08 + row * 0.06)
            bounce = abs(np.sin(local * 0.15 + i * 0.5)) * 10 if p > 0.5 else 0
            frog = Frog(fx, fy + bounce, 0.35 + np.random.rand() * 0.15)
            frog.emotion = Emotion.HAPPY
            frog.render(ax, local)

        # Bella on stage - Eli's love from Huuters
        bella = Waitress(WIDTH * 0.38, HEIGHT * 0.42, 0.9)
        bella.emotion = Emotion.LOVE
        bella.render(ax, local)

        sage = WiseTurtle(WIDTH * 0.62, HEIGHT * 0.42, 1.0)
        sage.render(ax, local)

        spark = Dragonfly(WIDTH * 0.55, HEIGHT * 0.55, 0.7)
        spark.render(ax, local)

        # Confetti!
        if p > 0.5:
            if local % 3 == 0:
                ctx['particles'].emit_magic(
                    np.random.uniform(WIDTH * 0.2, WIDTH * 0.8),
                    HEIGHT * 0.9, 'gold', 0.8)

        # "THE EMERALD GUARDIAN" title
        if p > 0.6:
            title_alpha = min(1, (p - 0.6) / 0.2)
            ax.text(WIDTH * 0.5, HEIGHT * 0.75, "THE EMERALD GUARDIAN",
                   fontsize=55, ha='center', fontweight='bold',
                   color='#006400', alpha=title_alpha, zorder=100)
            ax.text(WIDTH * 0.5, HEIGHT * 0.65, "Long Live King Eli!",
                   fontsize=30, ha='center', style='italic',
                   color='#228B22', alpha=title_alpha, zorder=100)

        # CINEMATIC EFFECTS - god rays from the sun for a heavenly coronation
        ctx['lighting'].render_god_rays(ax, frame, WIDTH * 0.8, HEIGHT * 0.85,
                                       color='#FFD700', intensity=0.35, num_rays=12)

        # Lens flare when crown lands
        if 0.35 < p < 0.5:
            flare_intensity = 1 - abs(p - 0.4) / 0.05
            ctx['lighting'].render_lens_flare(ax, frame, WIDTH * 0.5, HEIGHT * 0.55,
                                             intensity=flare_intensity * 0.5)

        # Subtle warm vignette for the joyous occasion
        ctx['lighting'].render_vignette(ax, 0.2, color='#8B4513')


# ╔═══════════════════════════════════════════════════════════════════════════════╗
# ║                           EPIC SOUNDTRACK                                     ║
# ╚═══════════════════════════════════════════════════════════════════════════════╝

def generate_epic_soundtrack(duration: int, sample_rate: int = 44100) -> np.ndarray:
    """Generate an epic orchestral-style soundtrack"""
    samples = int(duration * sample_rate)
    t = np.linspace(0, duration, samples)
    audio = np.zeros(samples)

    # Ambient pad (strings-like)
    pad_freqs = [130.81, 164.81, 196.00, 261.63]  # C major chord
    for freq in pad_freqs:
        # Slow attack pad
        env = (1 - np.exp(-t * 0.5)) * np.exp(-t * 0.001)
        audio += np.sin(2 * np.pi * freq * t) * env * 0.03
        audio += np.sin(2 * np.pi * freq * 2 * t) * env * 0.015  # Harmonic

    # Epic drums pattern
    drum_pattern = [0, 0.5, 1.0, 1.5, 2.0, 2.25, 2.5, 3.0, 3.5]
    for base_time in range(0, duration, 4):
        for offset in drum_pattern:
            hit_time = base_time + offset
            if hit_time < duration:
                start = int(hit_time * sample_rate)
                length = min(int(0.2 * sample_rate), samples - start)
                if length > 0:
                    drum_t = np.linspace(0, 0.2, length)
                    # Kick drum
                    kick = np.sin(2 * np.pi * (80 - drum_t * 200) * drum_t) * np.exp(-drum_t * 15)
                    audio[start:start+length] += kick * 0.15

    # Heroic melody
    melody_notes = [
        (261.63, 0.5), (293.66, 0.5), (329.63, 1.0), (293.66, 0.5), (261.63, 0.5),
        (329.63, 0.5), (349.23, 0.5), (392.00, 1.5), (349.23, 0.5),
        (329.63, 0.5), (293.66, 0.5), (261.63, 1.0), (196.00, 1.0),
        (261.63, 0.5), (329.63, 0.5), (392.00, 1.0), (440.00, 0.5), (392.00, 0.5),
        (349.23, 1.0), (329.63, 1.0), (293.66, 2.0),
    ]

    melody_duration = sum(n[1] for n in melody_notes)
    current_time = 5  # Start after intro

    while current_time < duration - 30:  # Leave room for ending
        note_time = current_time
        for freq, dur in melody_notes:
            if note_time + dur < duration:
                start = int(note_time * sample_rate)
                length = min(int(dur * sample_rate), samples - start)
                if length > 0:
                    note_t = np.linspace(0, dur, length)
                    envelope = (1 - np.exp(-note_t * 10)) * np.exp(-note_t * 1.5)
                    note = np.sin(2 * np.pi * freq * note_t) * envelope
                    note += np.sin(2 * np.pi * freq * 2 * note_t) * envelope * 0.3
                    audio[start:start+length] += note * 0.08
            note_time += dur
        current_time += melody_duration + 8  # Gap between repetitions

    # Ribbit sounds at key moments
    ribbit_times = [10, 25, 45, 70, 100, 130, 160, 200, 250, 300, 400, 500, 600, 700, 800]
    for rt in ribbit_times:
        if rt < duration:
            start = int(rt * sample_rate)
            ribbit_len = int(0.25 * sample_rate)
            if start + ribbit_len < samples:
                ribbit_t = np.linspace(0, 0.25, ribbit_len)
                freq1 = 220 + 80 * np.sin(2 * np.pi * 6 * ribbit_t)
                freq2 = 330 + 100 * np.sin(2 * np.pi * 8 * ribbit_t)
                env = np.exp(-ribbit_t * 10) * (1 - np.exp(-ribbit_t * 50))
                ribbit = (np.sin(2 * np.pi * freq1 * ribbit_t) * 0.4 +
                         np.sin(2 * np.pi * freq2 * ribbit_t) * 0.3) * env
                audio[start:start+ribbit_len] += ribbit * 0.2

    # Battle intensity sections (louder drums, faster tempo)
    battle_sections = [(420, 480), (540, 600), (660, 750)]
    for start_sec, end_sec in battle_sections:
        if start_sec < duration:
            start_s = int(start_sec * sample_rate)
            end_s = min(int(end_sec * sample_rate), samples)
            section_len = end_s - start_s
            if section_len > 0:
                battle_t = np.linspace(0, end_sec - start_sec, section_len)
                # Intense low rumble
                rumble = np.sin(2 * np.pi * 40 * battle_t) * 0.1
                rumble += np.sin(2 * np.pi * 60 * battle_t) * 0.08
                audio[start_s:end_s] += rumble * np.exp(-battle_t * 0.02)

    # Triumphant ending
    if duration > 60:
        end_start = int((duration - 30) * sample_rate)
        end_length = min(int(25 * sample_rate), samples - end_start)
        if end_length > 0:
            end_t = np.linspace(0, 25, end_length)
            # Major chord swell
            for freq in [261.63, 329.63, 392.00, 523.25]:
                swell = np.sin(2 * np.pi * freq * end_t)
                swell *= (1 - np.exp(-end_t * 0.3)) * np.exp(-(end_t - 12) ** 2 / 50)
                audio[end_start:end_start+end_length] += swell * 0.05

    # Normalize
    max_val = np.max(np.abs(audio))
    if max_val > 0:
        audio = audio / max_val * 0.85

    return audio


def save_wav(filename: str, audio: np.ndarray, sample_rate: int = 44100):
    """Save audio as WAV file"""
    audio_int = np.int16(audio * 32767)
    with wave.open(filename, 'w') as wav_file:
        wav_file.setnchannels(1)
        wav_file.setsampwidth(2)
        wav_file.setframerate(sample_rate)
        wav_file.writeframes(audio_int.tobytes())


