    scenes.append(HeroicRiseScene(f, 1500)); f += 1500  # 25 sec dramatic rise!

    # Chapter 25: The Prophecy Fulfilled
    scenes.append(ChapterScene(f, 180, 25, "The Prophecy Fulfilled")); f += 180
