    # Chapter 30: The Legend Lives On
    scenes.append(ChapterScene(f, 180, 30, "The Legend Lives On")); f += 180
    s = StoryScene(f, 900, 'pond', 'sunset'); f += 900  # Extended
    hero = Frog(WIDTH * 0.5, HEIGHT * 0.22, 1.3)
